    "exp1_intro": "Durant mon passage dans l'entreprise, j'ai développé des systèmes logiciels complets utilisés quotidiennement par les succursales et les employés : un système de gestion de tickets de support, une plateforme interne de distribution de logiciels et un outil de traitement et migration de données massives — ainsi que la conception et la documentation de l'infrastructure réseau et la gestion de la maintenance et du matériel.",
