    "ts_desc": "Entraîneur de frappe multiplateforme avec support RTL complet (arabe/hébreu/persan), statistiques WPM et précision détaillées, arrêt forcé en cas d'erreur, raccourcis globaux et barre système.",
    "nui_sub": "Launcher Android — Kotlin + Jetpack Compose",
