    "r30_sub": "Gestion de salaire et budget — Flutter",
    "r30_desc": "Application de budget intelligente Offline-First : répartition automatique 50/30/20, budget quotidien dynamique, défis d'épargne, section charité, graphiques (fl_chart) et calendrier financier mensuel — six plateformes.",
    "pomo_sub": "Minuteur Pomodoro — Flutter",
    "pomo_desc": "Gestion des sessions de travail et de pause avec la technique Pomodoro : objectifs quotidiens et hebdomadaires personnalisables, alertes sonores, thèmes multiples et paquets Linux (Flatpak / .desktop) — 5 plateformes.",
    "lm_sub": "Générateur de vidéos avec filigrane — Flutter + FFmpeg",
    "lm_desc": "Génère des vidéos MP4 avec filigrane texte animé sans vidéo d'entrée : texte arabe rendu avec Flutter Canvas en haute fidélité, exporté via FFmpeg sur Android et Windows.",
