    "miqyas_sub": "ایپ آئیکن سیف زون اسٹوڈیو اور اسٹور ماک اپس - پھڑپھڑانا",
    "miqyas_desc": "تمام پلیٹ فارمز پر 66×66 سیف زون کے اندر ایپ آئیکنز کو درست طریقے سے سیدھ میں لانے کے لیے ڈویلپرز کے لیے انٹرایکٹو اسٹوڈیو، جس میں گوگل پلے اور ایپ اسٹور کے لیے ایک لائیو ملٹی ڈیوائس ماک اپ پیش نظارہ اور خودکار اسٹور اسکرین شاٹ جنریٹر شامل ہے۔",
    "mufarrigh_sub": "اسپرائٹ شیٹ ایکسٹریکٹر اور بیک گراؤنڈ ریموور — فلٹر + ڈارٹ ویژن",
    "mufarrigh_desc": "سمارٹ ڈیسک ٹاپ اور موبائل ٹول اسپرائٹ شیٹس کو سلائس کرنے اور پیور ڈارٹ انجن، BFS فلڈ فل، اور انکولی 3-پین UI اور بیچ ایکسپورٹ کے ساتھ گیپ ایروشن کا استعمال کرتے ہوئے پس منظر کو ہٹانے کے لیے۔",
