    "tip1_badge": "فلٹر بلڈ وارننگ اور درست کریں۔",
    "tip1_title": "ورژن کے تنازعات کو روکنے کے لیے جاوا ایکسٹینشن کے لیے گریڈل کا درست استعمال",
    "tip1_desc": "اپنے IDE (VS Code / Antigravity) میں <b>Gradle for Java</b> ایکسٹینشن کو فعال کرتے وقت، اگر آپ کے <b>Flutter</b> پروجیکٹ میں Gradle کے متعدد ورژن یا ماڈیولز ہیں، تو ایکسٹینشن ہر ایک کو آزادانہ طور پر دریافت کرنے اور بنانے کی کوشش کرتا ہے۔ یہ ورژن کی مماثلت کی خرابیوں کو متحرک کر سکتا ہے (مثال کے طور پر <code>کم سے کم تعاون یافتہ گریڈل ورژن 9.6.0 ہے۔ موجودہ ورژن 9.4.0</code> ہے) اور تعمیر میں ناکامی کا سبب بن سکتا ہے۔ تجویز کردہ نقطہ نظر تعاون یافتہ ورک اسپیس تک توسیع کو اسکوپ کرنا ہے یا فلٹر سب ڈائرکٹریز کے لیے خودکار گہری پروجیکٹ کی دریافت کو غیر فعال کرنا ہے۔",
    "tip2_badge": "لینکس آٹومیشن ٹول",
