    "tip2_desc": "Bash اسکرپٹ جو آرک لینکس پر تازہ ترین مستحکم فلٹر SDK کو انسٹال کرنے کو خودکار بناتا ہے: خود بخود آفیشل سورس سے تازہ ترین ریلیز لاتا ہے، تین شیلوں (Bash، Zsh، اور Fish) میں ماحولیاتی متغیرات کو ترتیب دیتا ہے، اور ایک قدم میں <code>archlinux-java</code> کے ذریعے تازہ ترین OpenJDK کو بطور ڈیفالٹ سیٹ کرتا ہے۔",
