    "exp1_li1": "ডিজাইন এবং ডেভেলপ করা হয়েছে <b>কেসডেস্ক</b>, শাখা এবং কর্মচারীদের জন্য একটি সাপোর্ট টিকিট ম্যানেজমেন্ট সিস্টেম — দ্বৈত ডেটাবেস সহ অফলাইন-প্রথম আর্কিটেকচার (PHP REST API এর মাধ্যমে স্থানীয় হাইভ + ক্লাউড)।",
