    "exp1_li3": "বিল্ট <b>RatilConvert</b>, যা রিটেইল প্রো থেকে <b>+715,463 গ্রাহক রেকর্ড</b> প্রক্রিয়া এবং পরিষ্কার করে এবং Odoo ERP-তে 100% সামঞ্জস্য সহ রপ্তানি করে — ম্যানুয়াল মাইগ্রেশনের সময় 95% কমিয়ে দেয়।",
