    "exp1_intro": "কোম্পানিতে থাকাকালীন, আমি শাখা এবং কর্মচারীদের দ্বারা প্রতিদিন ব্যবহৃত সম্পূর্ণ সফ্টওয়্যার সিস্টেমগুলি তৈরি করেছি: একটি সমর্থন টিকিট ম্যানেজমেন্ট সিস্টেম, একটি অভ্যন্তরীণ সফ্টওয়্যার বিতরণ প্ল্যাটফর্ম, এবং একটি বিগ-ডেটা প্রসেসিং এবং মাইগ্রেশন টুল — নেটওয়ার্ক পরিকাঠামো ডিজাইন এবং নথিভুক্ত করার পাশাপাশি এবং রক্ষণাবেক্ষণ ও হার্ডওয়্যার কাজগুলি পরিচালনা করে৷",
