    "boycott_badge": "নীতি ও অবস্থান",
    "boycott_p1": "একজন <b>নেটওয়ার্ক বিশেষজ্ঞ</b> হিসেবে, আমি <b>সিসকো</b>কে বয়কট করি কারণ তাদের গভীর সহযোগিতা এবং নবী ও নিপীড়কদের হত্যাকারীদের প্রতি সমর্থন। সিসকো থেকে প্রত্যয়িত প্রমাণপত্র ধারণ করা সত্ত্বেও, আমি আল্লাহর সন্তুষ্টির জন্য সানন্দে তাদের ত্যাগ করছি। যে কেউ আমার মুসলিম ভাইদের ক্ষতি করবে, আমি আমার ব্যক্তিগত স্বার্থের জন্যও ত্যাগ করব- কেননা আমাদের রিযিক আল্লাহর উপর, যিনি স্বয়ংসম্পূর্ণ, প্রশংসিত।",
    "boycott_p2": "<b>আমি এই কর্পোরেশনগুলিকে বয়কট করি, কিন্তু কীভাবে আমরা এর থেকে সর্বোচ্চ সুবিধা পেতে পারি?</b><br>এমন একটি কোম্পানিতে কাজ করার সময় যেখানে আমি ডাটাবেস স্থাপনে সাহায্য করেছি, আমি তাদের সমর্থন না করার জন্য <b>ওরাকল</b> স্থাপন বা ব্যবহার করা এড়িয়ে চলি। কেউ সামান্য ভুল করলে তা থেকে শিক্ষা নেয়; যতক্ষণ পর্যন্ত আমার কোন ফার্মে হাত বা প্রযুক্তিগত প্রভাব থাকে, আমি কেবলমাত্র এমন প্রযুক্তি ব্যবহার করি যা আমাদের ভাইদের রক্ত ​​ঝরাতে সাহায্য করে না এবং আমার জীবিকা আল্লাহর উপর।",
    "boycott_p3": "এবং আল্লাহর প্রশংসা, আজ প্রতিটি প্রযুক্তির একটি মুক্ত এবং স্বাধীন বিকল্প রয়েছে.. এবং এই ক্ষণস্থায়ী জীবন থেকে আপনি বিদায় নেবেন (তাই আল্লাহকে ভয় করুন)।",
