    "casedesk_desc": "শাখা এবং কর্মচারীদের জন্য সম্পূর্ণ হেল্প ডেস্ক সিস্টেম: অফলাইন-ফার্স্ট ক্লাউড সিঙ্ক, ইন্টারেক্টিভ কেপিআই অ্যানালিটিক্স ড্যাশবোর্ড, আরবি পিডিএফ/এক্সেল রিপোর্ট, স্মার্ট টিকিট অটো-ফিল, এবং হোয়াটসঅ্যাপ বিজ্ঞপ্তি।",
