    "itsc_sub": "উদ্যোগের জন্য অভ্যন্তরীণ সফ্টওয়্যার বিতরণ প্ল্যাটফর্ম",
    "itsc_desc": "কোম্পানি নেটওয়ার্কের মধ্যে অনুমোদিত সফ্টওয়্যার বিতরণের জন্য এন্টারপ্রাইজ অ্যাপ: লাইভ অগ্রগতি সহ ডাউনলোড ম্যানেজার (ডিও), অ্যানিমেটেড ব্যাজ সহ স্বয়ংক্রিয় আপডেট সনাক্তকরণ, আরবি/ইংরেজি সমর্থন এবং অন্ধকার মোড (মেটেরিয়াল 3)।",
