    "tpc_desc": "স্বয়ংক্রিয় GPU সনাক্তকরণ এবং একটি আধুনিক গ্লাসমর্ফিজম UI সহ স্ট্রীম কপির মাধ্যমে 100% ক্ষতিহীন মানের ভিডিও (1/2/3 মিনিট বা অর্ধেক) বিভক্ত করার জন্য ডেস্কটপ অ্যাপ। উইন্ডোজ, লিনাক্স এবং ম্যাকোসে চলে।",
    "ts_sub": "টাইপিং স্পিড প্রশিক্ষক — Electron.js",
    "ts_desc": "সম্পূর্ণ RTL সমর্থন সহ ক্রস-প্ল্যাটফর্ম টাইপিং প্রশিক্ষক (আরবি/হিব্রু/পার্সিয়ান), বিশদ WPM এবং নির্ভুলতা পরিসংখ্যান, পেশী মেমরি, গ্লোবাল শর্টকাট এবং সিস্টেম ট্রে তৈরি করতে ত্রুটির উপর জোর করে থামানো।",
