    "roms_desc": "সম্পূর্ণ AOSP ROM কার্নেল টিউনিং, ডিভাইস ট্রি সেটআপ এবং ভেন্ডর ব্লব ম্যানেজমেন্ট সহ উৎস থেকে তৈরি হয়।",
