    "haris_desc": "একটি ওপেন-সোর্স, গোপনীয়তা-প্রথম ক্রস-ব্রাউজার এক্সটেনশন যা YouTube-কে একটি পরিষ্কার, ফোকাসড শেখার পরিবেশে রূপান্তরিত করে যাতে চ্যানেল হোয়াইটলিস্টিং, শর্টস ব্লকার এবং 40+ ভাষা সমর্থনকারী স্থানীয়-প্রথম আর্কিটেকচার।",
    "miqyas_sub": "অ্যাপ আইকন সেফ-জোন স্টুডিও এবং স্টোর মকআপস — ফ্লটার",
    "miqyas_desc": "সমস্ত প্ল্যাটফর্ম জুড়ে 66×66 নিরাপদ অঞ্চলের মধ্যে অ্যাপ আইকনগুলিকে সঠিকভাবে সারিবদ্ধ করার জন্য বিকাশকারীদের জন্য ইন্টারেক্টিভ স্টুডিও, একটি লাইভ মাল্টি-ডিভাইস মকআপ প্রিভিউ এবং Google Play এবং অ্যাপ স্টোরের জন্য স্বয়ংক্রিয় স্টোর স্ক্রিনশট জেনারেটর বৈশিষ্ট্যযুক্ত।",
    "mufarrigh_sub": "স্প্রাইট শীট এক্সট্র্যাক্টর এবং ব্যাকগ্রাউন্ড রিমুভার — ফ্লাটার + ডার্ট ভিশন",
    "mufarrigh_desc": "পিওর-ডার্ট ইঞ্জিন, বিএফএস ফ্লাড-ফিল, এবং অভিযোজিত 3-প্যান UI এবং ব্যাচ এক্সপোর্টের সাথে ফাঁক ক্ষয় ব্যবহার করে স্প্রাইট শীটগুলিকে টুকরো টুকরো করতে এবং ব্যাকগ্রাউন্ডগুলি সরানোর জন্য স্মার্ট ডেস্কটপ এবং মোবাইল টুল।",
    "tips_small": "গাইড, অন্তর্দৃষ্টি এবং সমাধান",
