    "tips_desc": "ব্যবহারিক নির্দেশিকা, সমস্যা সমাধানের অন্তর্দৃষ্টি, এবং উন্নয়ন এবং সিস্টেম প্রশাসনের সময় অর্জিত অটোমেশন সরঞ্জাম।",
    "tip1_badge": "ফ্লটার বিল্ড সতর্কতা এবং ঠিক করুন",
    "tip1_title": "সংস্করণ দ্বন্দ্ব প্রতিরোধ করতে জাভা এক্সটেনশনের জন্য Gradle এর সঠিক ব্যবহার",
    "tip1_desc": "আপনার IDE (VS Code / Antigravity) তে <b>Gradle for Java</b> এক্সটেনশন সক্রিয় করার সময়, যদি আপনার <b>ফ্লাটার</b> প্রোজেক্টে একাধিক গ্রেডল সংস্করণ বা মডিউল থাকে, তবে এক্সটেনশন প্রতিটিকে স্বাধীনভাবে আবিষ্কার ও নির্মাণ করার চেষ্টা করে। এটি সংস্করণের অমিল ত্রুটিগুলিকে ট্রিগার করতে পারে (যেমন <code>সর্বনিম্ন সমর্থিত গ্রেডল সংস্করণ 9.6.0। বর্তমান সংস্করণ 9.4.0</code>) এবং বিল্ড ব্যর্থতার কারণ হতে পারে। প্রস্তাবিত পন্থা হল সমর্থিত ওয়ার্কস্পেসগুলিতে এক্সটেনশন স্কোপ করা বা Flutter সাবডিরেক্টরিগুলির জন্য স্বয়ংক্রিয় গভীর প্রকল্প আবিষ্কার অক্ষম করা।",
    "tip2_badge": "লিনাক্স অটোমেশন টুল",
    "tip2_sub": "লিনাক্স অটোমেশন টুল - ব্যাশ + আর্চ লিনাক্স",
    "tip2_title": "আর্চ লিনাক্সের জন্য ফ্লাটার ইনস্টলার — স্বয়ংক্রিয় SDK সেটআপ",
    "tip2_desc": "Bash স্ক্রিপ্ট যা আর্ক লিনাক্সে সর্বশেষ স্থিতিশীল ফ্লাটার SDK ইনস্টল করার স্বয়ংক্রিয়ভাবে কাজ করে: স্বয়ংক্রিয়ভাবে অফিসিয়াল সোর্স থেকে নতুন রিলিজ আনে, তিনটি শেল জুড়ে পরিবেশের ভেরিয়েবল কনফিগার করে (Bash, Zsh, এবং Fish), এবং একটি ধাপে <code>archlinux-java</code> এর মাধ্যমে সর্বশেষ OpenJDK কে ডিফল্ট হিসেবে সেট করে।",
