    "exp1_li1": "طراحی و توسعه <b>CaseDesk</b>، یک سیستم مدیریت بلیط پشتیبانی برای شعب و کارمندان — معماری Offline-First با پایگاه داده دوگانه (Hive + cloud از طریق APIهای PHP REST).",
