    "boycott_p1": "من به عنوان یک <b>متخصص شبکه</b>، <b>Cisco</b> را به دلیل همدستی و حمایت عمیق آنها از قاتلان پیامبران و ستمگران تحریم می کنم. علیرغم داشتن مدارک تایید شده از سیسکو، من با کمال میل به خاطر خدا از آنها چشم پوشی می کنم. هر کس برادران مسلمانم را آزار دهد، حتی به بهای منافع شخصی خود دست بردارم، زیرا روزی ما بر خدای بی‌نیاز و ستوده است.",
    "boycott_p2": "<b>من این شرکت‌ها را تحریم می‌کنم، اما چگونه می‌توانیم از این مزیت به حداکثر برسانیم؟</b><br>وقتی در شرکتی کار می‌کردم که به استقرار پایگاه‌های داده کمک می‌کردم، از استقرار یا استفاده از <b>Oracle</b> برای اطمینان از عدم پشتیبانی از آنها اجتناب کردم. اگر یک اشتباه کوچک مرتکب شود، از آن درس می گیرد. تا زمانی که در هر بنگاهی نفوذ فنی یا دستی دارم، فقط از فناوری هایی استفاده می کنم که از کسانی که خون برادرانمان را می ریزند حمایت نمی کنند و رزق و روزی من بر خداست.",
    "boycott_p3": "و الحمدلله امروز هر تکنولوژی جایگزینی آزاد و مستقل دارد... و از این زندگی زودگذر خارج خواهید شد (پس از خدا بترسید).",
