    "tip1_desc": "هنگام فعال کردن پسوند <b>Gradle برای جاوا</b> در IDE خود (VS Code / Antigravity)، اگر پروژه <b>Flutter</b> شما حاوی چندین نسخه یا ماژول Gradle باشد، برنامه افزودنی سعی می کند هر یک را به طور مستقل کشف و بسازد. این می تواند خطاهای عدم تطابق نسخه را ایجاد کند (به عنوان مثال <code>حداقل نسخه Gradle پشتیبانی شده 9.6.0 است. نسخه فعلی 9.4.0 است</code>) و باعث خرابی در ساخت شود. رویکرد پیشنهادی، گسترش دامنه به فضاهای کاری پشتیبانی شده یا غیرفعال کردن کشف خودکار عمیق پروژه برای زیرشاخه‌های Flutter است.",
