    "exp1_li1": "Direka dan dibangunkan <b>CaseDesk</b>, sistem pengurusan tiket sokongan untuk cawangan dan pekerja — Seni bina Luar Talian Pertama dengan dwi pangkalan data (Hive + awan tempatan melalui PHP REST API).",
    "exp1_li2": "Membangunkan aplikasi <b>Pusat Perisian IT</b> untuk mengedarkan perisian yang diluluskan di dalam rangkaian syarikat dengan pengesanan kemas kini automatik dan pengurus muat turun pintar.",
    "exp1_li3": "<b>RatilConvert</b> yang dibina, yang memproses dan membersihkan <b>+715,463 rekod pelanggan</b> daripada Retail Pro dan mengeksportnya dengan keserasian 100% kepada Odoo ERP — mengurangkan masa pemindahan manual sebanyak 95%.",
    "exp1_li4": "Mereka bentuk rajah rangkaian fizikal syarikat menggunakan draw.io, termasuk pengedaran pelayan, tembok api, suis teras dan suis jabatan, dengan dokumentasi rangkaian penuh.",
    "exp1_li5": "Mengendalikan tugas penyelenggaraan dan perkakasan, menganalisis KPI melalui papan pemuka interaktif dan menghasilkan laporan PDF/Excel Arab profesional.",
    "exp1_intro": "Semasa berada di syarikat itu, saya membangunkan sistem perisian lengkap yang digunakan setiap hari oleh cawangan dan pekerja: sistem pengurusan tiket sokongan, platform pengedaran perisian dalaman dan alat pemprosesan & migrasi data besar — ​​di samping mereka bentuk dan mendokumentasikan infrastruktur rangkaian serta mengendalikan tugasan penyelenggaraan & perkakasan.",
    "boycott_title": "🕊️ Boikot Teknikal",
