    "boycott_badge": "Prinsip & Pendirian",
    "boycott_p1": "Sebagai seorang <b>pakar rangkaian</b>, saya memboikot <b>Cisco</b> kerana keterlibatan dan sokongan mendalam mereka terhadap pembunuh nabi dan penindas. Walaupun memegang tauliah yang diperakui daripada Cisco, saya dengan senang hati meninggalkannya kerana Allah. Sesiapa yang menyakiti saudara-saudaraku yang Islam, aku akan tinggalkan walaupun dengan mengorbankan kepentingan peribadiku - kerana rezeki kami adalah dari Allah Yang Maha Kaya lagi Maha Terpuji.",
    "boycott_p2": "<b>Saya memboikot syarikat ini, tetapi bagaimanakah kita boleh memaksimumkan manfaat daripada ini?</b><br>Semasa bekerja di syarikat tempat saya membantu menggunakan pangkalan data, saya mengelak daripada menggunakan atau menggunakan <b>Oracle</b> untuk memastikan tidak menyokongnya. Jika seseorang membuat sedikit kesilapan, mereka belajar daripadanya; selagi saya ada tangan atau pengaruh teknikal di mana-mana firma, saya hanya menggunakan teknologi yang tidak menyokong mereka yang menumpahkan darah saudara kita, dan rezeki saya atas Allah.",
    "boycott_p3": "Dan segala puji bagi Allah, hari ini setiap teknologi mempunyai alternatif yang bebas dan bebas.. dan dari kehidupan yang sekejap ini kamu akan pergi (maka bertakwalah kepada Allah).",
