    "boycott_tip": "<b>Nasihat untuk mereka yang terpaksa:</b> Jika seseorang terpaksa membeli produk daripada entiti yang diboikot tanpa alternatif tersedia, beli produk itu <b>terpakai / terpakai</b> supaya syarikat memperoleh keuntungan baharu sifar. Segala puji bagi Allah dan kepada-Nya kami bertawakkal.",
