    "casedesk_sub": "Sistem pengurusan tiket sokongan IT — Flutter Desktop",
    "casedesk_desc": "Sistem Meja Bantuan yang lengkap untuk cawangan dan pekerja: Penyegerakan awan Luar Talian-Pertama, papan pemuka analitik KPI interaktif, laporan PDF/Excel Arab, auto-isi tiket pintar dan pemberitahuan WhatsApp.",
    "ratil_sub": "Pro Runcit → Penghijrahan data ERP Odoo",
    "ratil_desc": "Diproses dan dibersihkan <b>+715,463 rekod pelanggan</b> dengan algoritma pembersihan pintar dan pemprosesan selari (Dart Isolates) tanpa membekukan UI — 100% ketepatan dan 95% kurang masa pemindahan manual.",
    "itsc_sub": "Platform pengedaran perisian dalaman untuk perusahaan",
    "itsc_desc": "Apl perusahaan untuk mengedarkan perisian yang diluluskan dalam rangkaian syarikat: pengurus muat turun dengan kemajuan langsung (Dio), pengesanan kemas kini automatik dengan lencana animasi, sokongan Arab/Inggeris dan mod gelap (Bahan 3).",
    "tpc_sub": "Pemisahan video — Electron.js + FFmpeg",
    "tpc_desc": "Apl desktop untuk memisahkan video (1/2/3 minit atau separuh) pada kualiti 100% tanpa kerugian melalui Salin Strim, dengan pengesanan GPU automatik dan UI Glassmorphism moden. Berjalan pada Windows, Linux dan macOS.",
    "ts_sub": "Pelatih kelajuan menaip — Electron.js",
    "ts_desc": "Jurulatih menaip merentas platform dengan sokongan penuh RTL (Arab/Ibrani/Parsi), WPM terperinci dan statistik ketepatan, terpaksa berhenti pada ralat untuk membina memori otot, pintasan global dan dulang sistem.",
    "nui_sub": "Pelancar Android — Kotlin + Jetpack Compose",
    "nui_desc": "Pelancar Android moden dengan seni bina MVVM dan Room DB: kalendar Hijriah/Gregorian terbina dalam, nota skrin utama, pengkategorian apl automatik, tong sampah dan menyembunyikan apl sensitif.",
    "r30_sub": "Pengurusan gaji & bajet — Flutter",
    "r30_desc": "Apl belanjawan Luar Talian Pintar: pengedaran automatik 50/30/20, belanjawan harian dinamik, cabaran penjimatan, bahagian amal, carta (fl_chart) dan kalendar kewangan bulanan — enam platform yang disokong.",
    "pomo_sub": "Pemasa produktiviti Pomodoro — Berkibar",
    "pomo_desc": "Pengurusan sesi kerja/rehat dengan teknik Pomodoro: matlamat harian dan mingguan yang boleh disesuaikan, makluman bunyi, berbilang tema dan pakej Linux (Flatpak / .desktop) — berjalan pada 5 platform.",
    "lm_sub": "Penjana video tera air — Flutter + FFmpeg",
    "lm_desc": "Menjana video MP4 dengan tera air teks animasi tanpa sebarang video input: Teks Arab yang diberikan dengan enjin Flutter Canvas pada ketepatan tinggi dengan sokongan diakritik penuh, dieksport melalui FFmpeg pada Android dan Windows.",
    "roms_small": "Sistem Operasi",
    "roms_title": "🤖 Membina ROM Android Tersuai daripada Sumber",
    "roms_desc": "ROM AOSP penuh dibina daripada sumber dengan penalaan kernel, persediaan pokok peranti dan pengurusan gumpalan vendor.",
    "rom1_desc": "Binaan AOSP penuh daripada sumber dengan lapisan Evolution X, penalaan kernel tersuai dan pepohon peranti, pembetulan HAL dan persediaan kamera serta pengalaman Pixel pada perkakasan Xiaomi.",
    "rom2_desc": "AOSP Android 16 binaan daripada sumber dengan ciri Infinity X, penalaan inti dan pokok peranti serta pengurusan gumpalan vendor & HAL.",
    "rom3_desc": "PixelOS dibina daripada sumber dengan kompilasi kernel, persediaan pepohon peranti dan pengekstrakan gumpalan vendor — pengalaman Pixel yang bersih pada perkakasan Motorola.",
    "rom4_desc": "Binaan vanila tanpa perkhidmatan Google (GApps) — pengalaman AOSP tulen 100% pada peranti yang sama.",
    "rom4_tag3": "Tiada GApps",
    "rom5_desc": "Mengekalkan dan membina ROM LineageOS 23.2 rasmi untuk Moto G54 5G — ROM sumber terbuka yang stabil dan ringan dengan kemas kini keselamatan biasa.",
