    "haris_desc": "Sambungan rentas penyemak imbas sumber terbuka dan mengutamakan privasi yang mengubah YouTube menjadi persekitaran pembelajaran yang bersih dan terfokus dengan penyenaraian putih saluran, penyekat Shorts dan seni bina tempatan pertama yang menyokong 40+ bahasa.",
    "miqyas_sub": "Mockup studio & kedai zon selamat ikon apl — Flutter",
    "miqyas_desc": "Studio interaktif untuk pembangun menjajarkan ikon apl dengan tepat dalam zon selamat 66×66 merentas semua platform, menampilkan pratonton mockup berbilang peranti secara langsung dan penjana tangkapan skrin kedai automatik untuk Google Play dan App Store.",
    "mufarrigh_sub": "Pengekstrak helaian Sprite & penghilang latar belakang — Flutter + Dart Vision",
    "mufarrigh_desc": "Alat desktop & mudah alih pintar untuk menghiris helaian sprite dan mengalih keluar latar belakang menggunakan enjin Dart tulen, BFS Flood-Fill dan hakisan jurang dengan UI 3 anak tetingkap adaptif dan eksport kelompok.",
    "tips_small": "Panduan, pandangan & penyelesaian",
    "tips_title": "💡 Petua & Penyelesaian Teknologi",
    "tips_desc": "Panduan praktikal, cerapan penyelesaian masalah dan alat automasi yang diperoleh semasa pembangunan dan pentadbiran sistem.",
    "tip1_badge": "Amaran & Betulkan Binaan Flutter",
    "tip1_title": "Penggunaan Gradle untuk sambungan Java yang betul untuk mengelakkan konflik versi",
    "tip1_desc": "Apabila mendayakan sambungan <b>Gradle untuk Java</b> dalam IDE anda (Kod VS / Antigraviti), jika projek <b>Flutter</b> anda mengandungi berbilang versi atau modul Gradle, sambungan cuba menemui dan membina setiap satu secara bebas. Ini boleh mencetuskan ralat ketidakpadanan versi (cth. <code>Versi Gradle yang disokong minimum ialah 9.6.0. Versi semasa ialah 9.4.0</code>) dan menyebabkan kegagalan binaan. Pendekatan yang disyorkan ialah merangkumi pelanjutan ke ruang kerja yang disokong atau melumpuhkan penemuan projek mendalam automatik untuk subdirektori Flutter.",
    "tip2_badge": "Alat Automasi Linux",
    "tip2_sub": "Alat automasi Linux — Bash + Arch Linux",
    "tip2_title": "Flutter Installer untuk Arch Linux — Persediaan SDK Automatik",
    "tip2_desc": "Skrip Bash yang mengautomasikan pemasangan Flutter SDK terbaharu yang stabil pada Arch Linux: secara automatik mengambil keluaran terbaharu daripada sumber rasmi, mengkonfigurasikan pembolehubah persekitaran merentas tiga cengkerang (Bash, Zsh dan Fish) dan menetapkan OpenJDK terbaharu sebagai lalai melalui <code>archlinux-java</code> dalam satu langkah.",
    "tip_img_tag": "📸 Sambungan & Tangkapan Skrin Ralat",
