    "boycott_p2": "<b>زه دا کارپوریشنونه بایکاټ کوم، مګر موږ څنګه له دې څخه اعظمي ګټه پورته کړو؟</b><br>په داسې حال کې چې په یوه شرکت کې کار کوم چیرې چې ما د ډیټابیسونو په نصبولو کې مرسته کړې، ما د <b>Oracle</b> د ځای پرځای کولو یا کارولو څخه ډډه وکړه ترڅو ډاډ ترلاسه شي چې دوی ملاتړ نه کوي. که یو څوک لږه غلطي وکړي، دوی ترې زده کوي؛ تر څو چې زه په کوم شرکت کې لاس یا تخنیکي نفوذ لرم، زه یوازې هغه ټیکنالوژي کاروم چې د هغه چا ملاتړ نه کوي چې زموږ د وروڼو وینې تویوي، او زما رزق په الله باندې دی.",
