    "exp1_li1": "ਡਿਜ਼ਾਇਨ ਅਤੇ ਵਿਕਸਿਤ ਕੀਤਾ <b>ਕੇਸਡੇਸਕ</b>, ਸ਼ਾਖਾਵਾਂ ਅਤੇ ਕਰਮਚਾਰੀਆਂ ਲਈ ਇੱਕ ਸਮਰਥਨ ਟਿਕਟ ਪ੍ਰਬੰਧਨ ਸਿਸਟਮ — ਦੋਹਰੇ ਡੇਟਾਬੇਸ (PHP REST APIs ਦੁਆਰਾ ਸਥਾਨਕ Hive + ਕਲਾਉਡ) ਦੇ ਨਾਲ ਔਫਲਾਈਨ-ਪਹਿਲਾ ਆਰਕੀਟੈਕਚਰ।",
    "exp1_li2": "ਆਟੋਮੈਟਿਕ ਅੱਪਡੇਟ ਖੋਜ ਅਤੇ ਇੱਕ ਸਮਾਰਟ ਡਾਉਨਲੋਡ ਮੈਨੇਜਰ ਦੇ ਨਾਲ ਕੰਪਨੀ ਨੈੱਟਵਰਕ ਦੇ ਅੰਦਰ ਮਨਜ਼ੂਰਸ਼ੁਦਾ ਸੌਫਟਵੇਅਰ ਨੂੰ ਵੰਡਣ ਲਈ <b>IT ਸਾਫਟਵੇਅਰ ਸੈਂਟਰ</b> ਐਪ ਵਿਕਸਿਤ ਕੀਤਾ ਗਿਆ ਹੈ।",
    "exp1_li3": "ਬਿਲਟ <b>RatilConvert</b>, ਜਿਸ ਨੇ ਰਿਟੇਲ ਪ੍ਰੋ ਤੋਂ <b>+715,463 ਗਾਹਕ ਰਿਕਾਰਡਾਂ</b> ਨੂੰ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਅਤੇ ਸਾਫ਼ ਕੀਤਾ ਅਤੇ ਉਹਨਾਂ ਨੂੰ Odoo ERP ਵਿੱਚ 100% ਅਨੁਕੂਲਤਾ ਨਾਲ ਨਿਰਯਾਤ ਕੀਤਾ — ਮੈਨੂਅਲ ਮਾਈਗ੍ਰੇਸ਼ਨ ਸਮੇਂ ਵਿੱਚ 95% ਦੀ ਕਟੌਤੀ ਕੀਤੀ।",
    "exp1_li4": "ਪੂਰੇ ਨੈੱਟਵਰਕ ਦਸਤਾਵੇਜ਼ਾਂ ਦੇ ਨਾਲ, ਸਰਵਰ ਡਿਸਟ੍ਰੀਬਿਊਸ਼ਨ, ਫਾਇਰਵਾਲ, ਕੋਰ ਸਵਿੱਚ, ਅਤੇ ਡਿਪਾਰਟਮੈਂਟ ਸਵਿੱਚਾਂ ਸਮੇਤ draw.io ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹੋਏ ਕੰਪਨੀ ਦੇ ਭੌਤਿਕ ਨੈੱਟਵਰਕ ਡਾਇਗ੍ਰਾਮ ਨੂੰ ਡਿਜ਼ਾਈਨ ਕੀਤਾ ਗਿਆ ਹੈ।",
    "exp1_li5": "ਸਾਂਭ-ਸੰਭਾਲ ਅਤੇ ਹਾਰਡਵੇਅਰ ਕਾਰਜਾਂ ਨੂੰ ਸੰਭਾਲਿਆ, ਇੰਟਰਐਕਟਿਵ ਡੈਸ਼ਬੋਰਡਾਂ ਰਾਹੀਂ KPIs ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕੀਤਾ, ਅਤੇ ਪੇਸ਼ੇਵਰ ਅਰਬੀ PDF/Excel ਰਿਪੋਰਟਾਂ ਤਿਆਰ ਕੀਤੀਆਂ।",
    "exp1_intro": "ਕੰਪਨੀ ਵਿੱਚ ਮੇਰੇ ਸਮੇਂ ਦੌਰਾਨ, ਮੈਂ ਬ੍ਰਾਂਚਾਂ ਅਤੇ ਕਰਮਚਾਰੀਆਂ ਦੁਆਰਾ ਰੋਜ਼ਾਨਾ ਵਰਤੇ ਜਾਣ ਵਾਲੇ ਪੂਰੇ ਸਾਫਟਵੇਅਰ ਸਿਸਟਮ ਵਿਕਸਿਤ ਕੀਤੇ: ਇੱਕ ਸਪੋਰਟ ਟਿਕਟ ਮੈਨੇਜਮੈਂਟ ਸਿਸਟਮ, ਇੱਕ ਅੰਦਰੂਨੀ ਸਾਫਟਵੇਅਰ ਡਿਸਟ੍ਰੀਬਿਊਸ਼ਨ ਪਲੇਟਫਾਰਮ, ਅਤੇ ਇੱਕ ਵੱਡਾ-ਡਾਟਾ ਪ੍ਰੋਸੈਸਿੰਗ ਅਤੇ ਮਾਈਗ੍ਰੇਸ਼ਨ ਟੂਲ — ਨੈੱਟਵਰਕ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਨੂੰ ਡਿਜ਼ਾਈਨ ਕਰਨ ਅਤੇ ਦਸਤਾਵੇਜ਼ ਬਣਾਉਣ ਅਤੇ ਰੱਖ-ਰਖਾਅ ਅਤੇ ਹਾਰਡਵੇਅਰ ਕਾਰਜਾਂ ਨੂੰ ਸੰਭਾਲਣ ਦੇ ਨਾਲ।",
    "boycott_title": "🕊️ ਤਕਨੀਕੀ ਬਾਈਕਾਟ",
    "boycott_sub": "ਪੱਕਾ ਸਿਧਾਂਤ ਅਤੇ ਵਿਸ਼ਵਾਸ-ਆਧਾਰਿਤ ਰੁਖ",
    "boycott_badge": "ਸਿਧਾਂਤ ਅਤੇ ਰੁਖ਼",
    "boycott_p1": "ਇੱਕ <b>ਨੈੱਟਵਰਕ ਸਪੈਸ਼ਲਿਸਟ</b> ਹੋਣ ਦੇ ਨਾਤੇ, ਮੈਂ <b>ਸਿਸਕੋ</b> ਦਾ ਬਾਈਕਾਟ ਕਰਦਾ ਹਾਂ ਕਿਉਂਕਿ ਉਹਨਾਂ ਦੀ ਡੂੰਘੀ ਸ਼ਮੂਲੀਅਤ ਅਤੇ ਪੈਗੰਬਰਾਂ ਦੇ ਕਾਤਲਾਂ ਅਤੇ ਜ਼ੁਲਮ ਕਰਨ ਵਾਲਿਆਂ ਲਈ ਸਮਰਥਨ ਹੈ। ਸਿਸਕੋ ਤੋਂ ਪ੍ਰਮਾਣਿਤ ਪ੍ਰਮਾਣ ਪੱਤਰ ਰੱਖਣ ਦੇ ਬਾਵਜੂਦ, ਮੈਂ ਅੱਲ੍ਹਾ ਦੀ ਖ਼ਾਤਰ ਉਹਨਾਂ ਨੂੰ ਖੁਸ਼ੀ ਨਾਲ ਤਿਆਗ ਦਿੰਦਾ ਹਾਂ। ਜੋ ਕੋਈ ਵੀ ਮੇਰੇ ਮੁਸਲਮਾਨ ਭਰਾਵਾਂ ਨੂੰ ਨੁਕਸਾਨ ਪਹੁੰਚਾਉਂਦਾ ਹੈ, ਮੈਂ ਆਪਣੇ ਨਿੱਜੀ ਹਿੱਤਾਂ ਦੀ ਕੀਮਤ 'ਤੇ ਵੀ ਤਿਆਗ ਦੇਵਾਂਗਾ - ਕਿਉਂਕਿ ਸਾਡਾ ਰੋਜ਼ੀ-ਰੋਟੀ ਅੱਲ੍ਹਾ 'ਤੇ ਹੈ, ਜੋ ਆਤਮ-ਨਿਰਭਰ, ਪ੍ਰਸ਼ੰਸਾਯੋਗ ਹੈ।",
    "boycott_p2": "<b>ਮੈਂ ਇਹਨਾਂ ਕਾਰਪੋਰੇਸ਼ਨਾਂ ਦਾ ਬਾਈਕਾਟ ਕਰਦਾ ਹਾਂ, ਪਰ ਅਸੀਂ ਇਸ ਤੋਂ ਵੱਧ ਤੋਂ ਵੱਧ ਲਾਭ ਕਿਵੇਂ ਲੈ ਸਕਦੇ ਹਾਂ?</b><br>ਇੱਕ ਕੰਪਨੀ ਵਿੱਚ ਕੰਮ ਕਰਦੇ ਹੋਏ ਜਿੱਥੇ ਮੈਂ ਡੇਟਾਬੇਸ ਨੂੰ ਤੈਨਾਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕੀਤੀ, ਮੈਂ ਉਹਨਾਂ ਦਾ ਸਮਰਥਨ ਨਾ ਕਰਨਾ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ <b>Oracle</b> ਨੂੰ ਤੈਨਾਤ ਕਰਨ ਜਾਂ ਵਰਤਣ ਤੋਂ ਪਰਹੇਜ਼ ਕੀਤਾ। ਜੇ ਕੋਈ ਮਾਮੂਲੀ ਜਿਹੀ ਗਲਤੀ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਹ ਉਸ ਤੋਂ ਸਿੱਖਦੇ ਹਨ; ਜਿੰਨਾ ਚਿਰ ਮੇਰਾ ਕਿਸੇ ਵੀ ਫਰਮ ਵਿੱਚ ਕੋਈ ਹੱਥ ਜਾਂ ਤਕਨੀਕੀ ਪ੍ਰਭਾਵ ਹੈ, ਮੈਂ ਸਿਰਫ ਉਹ ਤਕਨਾਲੋਜੀਆਂ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹਾਂ ਜੋ ਸਾਡੇ ਭਰਾਵਾਂ ਦਾ ਖੂਨ ਵਹਾਉਣ ਵਾਲਿਆਂ ਦਾ ਸਮਰਥਨ ਨਹੀਂ ਕਰਦੀਆਂ, ਅਤੇ ਮੇਰਾ ਪਾਲਣ-ਪੋਸ਼ਣ ਅੱਲ੍ਹਾ ਉੱਤੇ ਹੈ।",
    "boycott_p3": "ਅਤੇ ਅੱਲ੍ਹਾ ਦੀ ਪ੍ਰਸ਼ੰਸਾ ਕਰੋ, ਅੱਜ ਹਰ ਤਕਨਾਲੋਜੀ ਦਾ ਇੱਕ ਸੁਤੰਤਰ ਅਤੇ ਸੁਤੰਤਰ ਵਿਕਲਪ ਹੈ.. ਅਤੇ ਤੁਸੀਂ ਇਸ ਅਸਥਾਈ ਜੀਵਨ ਤੋਂ ਚਲੇ ਜਾਓਗੇ (ਇਸ ਲਈ ਅੱਲ੍ਹਾ ਤੋਂ ਡਰੋ)।",
    "cisco_title": "ਸਿਸਕੋ",
