    "oracle_desc": "ਕਾਰਪੋਰੇਟ ਪੇਚੀਦਗੀ ਦਾ ਦਸਤਾਵੇਜ਼ੀਕਰਨ, ਅਤੇ ਓਪਨ-ਸੋਰਸ ਵਿਕਲਪਾਂ (ਜਿਵੇਂ ਕਿ PostgreSQL ਅਤੇ MariaDB) ਲਈ ਵਚਨਬੱਧਤਾ:",
    "boycott_tip": "<b>ਮਜ਼ਬੂਰ ਲੋਕਾਂ ਲਈ ਸਲਾਹ:</b> ਜੇਕਰ ਕਿਸੇ ਨੂੰ ਬਾਈਕਾਟ ਕੀਤੀ ਇਕਾਈ ਤੋਂ ਕੋਈ ਉਤਪਾਦ ਖਰੀਦਣ ਲਈ ਮਜਬੂਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਜਿਸ ਕੋਲ ਕੋਈ ਵਿਕਲਪ ਉਪਲਬਧ ਨਹੀਂ ਹੈ, ਤਾਂ ਇਸਨੂੰ <b>ਸੈਕੰਡ-ਹੈਂਡ/ਵਰਤਿਆ</b> ਖਰੀਦੋ ਤਾਂ ਕਿ ਕੰਪਨੀ ਨੂੰ ਜ਼ੀਰੋ ਨਵਾਂ ਮੁਨਾਫ਼ਾ ਪ੍ਰਾਪਤ ਹੋਵੇ। ਅੱਲ੍ਹਾ ਦੀ ਉਸਤਤ ਹੋਵੇ ਅਤੇ ਅਸੀਂ ਉਸ ਉੱਤੇ ਭਰੋਸਾ ਕਰਦੇ ਹਾਂ।",
