    "proj_desc": "GitHub 'ਤੇ ਪ੍ਰਕਾਸ਼ਿਤ ਅਸਲ, ਮੁਕੰਮਲ ਹੋਏ ਪ੍ਰੋਜੈਕਟ — ਐਂਟਰਪ੍ਰਾਈਜ਼ ਮੈਨੇਜਮੈਂਟ ਸਿਸਟਮ ਤੋਂ ਲੈ ਕੇ ਡੈਸਕਟੌਪ ਅਤੇ ਮੋਬਾਈਲ ਉਤਪਾਦਕਤਾ ਸਾਧਨਾਂ ਤੱਕ।",
