    "casedesk_desc": "ਸ਼ਾਖਾਵਾਂ ਅਤੇ ਕਰਮਚਾਰੀਆਂ ਲਈ ਸੰਪੂਰਨ ਹੈਲਪ ਡੈਸਕ ਸਿਸਟਮ: ਔਫਲਾਈਨ-ਪਹਿਲਾ ਕਲਾਉਡ ਸਿੰਕ, ਇੰਟਰਐਕਟਿਵ KPI ਵਿਸ਼ਲੇਸ਼ਣ ਡੈਸ਼ਬੋਰਡ, ਅਰਬੀ PDF/ਐਕਸਲ ਰਿਪੋਰਟਾਂ, ਸਮਾਰਟ ਟਿਕਟ ਆਟੋ-ਫਿਲ, ਅਤੇ WhatsApp ਸੂਚਨਾਵਾਂ।",
    "ratil_sub": "ਰਿਟੇਲ ਪ੍ਰੋ → ਓਡੂ ERP ਡਾਟਾ ਮਾਈਗ੍ਰੇਸ਼ਨ",
    "ratil_desc": "UI ਨੂੰ ਫ੍ਰੀਜ਼ ਕੀਤੇ ਬਿਨਾਂ ਸਮਾਰਟ ਕਲੀਨਿੰਗ ਐਲਗੋਰਿਦਮ ਅਤੇ ਪੈਰਲਲ ਪ੍ਰੋਸੈਸਿੰਗ (ਡਾਰਟ ਆਈਸੋਲੇਟਸ) ਦੇ ਨਾਲ <b>+715,463 ਗਾਹਕ ਰਿਕਾਰਡਾਂ</b> ਨੂੰ ਪ੍ਰੋਸੈਸ ਅਤੇ ਸਾਫ਼ ਕੀਤਾ ਗਿਆ — 100% ਸ਼ੁੱਧਤਾ ਅਤੇ 95% ਘੱਟ ਮੈਨੂਅਲ ਮਾਈਗ੍ਰੇਸ਼ਨ ਸਮਾਂ।",
    "itsc_sub": "ਉੱਦਮਾਂ ਲਈ ਅੰਦਰੂਨੀ ਸਾਫਟਵੇਅਰ ਵੰਡ ਪਲੇਟਫਾਰਮ",
    "itsc_desc": "ਕੰਪਨੀ ਨੈਟਵਰਕ ਦੇ ਅੰਦਰ ਪ੍ਰਵਾਨਿਤ ਸੌਫਟਵੇਅਰ ਵੰਡਣ ਲਈ ਐਂਟਰਪ੍ਰਾਈਜ਼ ਐਪ: ਲਾਈਵ ਪ੍ਰਗਤੀ (ਡੀਓ) ਦੇ ਨਾਲ ਡਾਉਨਲੋਡ ਮੈਨੇਜਰ, ਐਨੀਮੇਟਡ ਬੈਜ ਦੇ ਨਾਲ ਆਟੋਮੈਟਿਕ ਅਪਡੇਟ ਖੋਜ, ਅਰਬੀ/ਅੰਗਰੇਜ਼ੀ ਸਹਾਇਤਾ ਅਤੇ ਡਾਰਕ ਮੋਡ (ਮਟੀਰੀਅਲ 3)।",
    "tpc_sub": "ਵੀਡੀਓ ਵੰਡਣਾ — Electron.js + FFmpeg",
    "tpc_desc": "ਆਟੋਮੈਟਿਕ GPU ਖੋਜ ਅਤੇ ਇੱਕ ਆਧੁਨਿਕ ਗਲਾਸਮੋਰਫਿਜ਼ਮ UI ਦੇ ਨਾਲ, ਸਟ੍ਰੀਮ ਕਾਪੀ ਦੁਆਰਾ 100% ਨੁਕਸਾਨ ਰਹਿਤ ਗੁਣਵੱਤਾ 'ਤੇ ਵਿਡੀਓਜ਼ (1/2/3 ਮਿੰਟ ਜਾਂ ਅੱਧੇ ਹਿੱਸੇ) ਨੂੰ ਵੰਡਣ ਲਈ ਡੈਸਕਟੌਪ ਐਪ। ਵਿੰਡੋਜ਼, ਲੀਨਕਸ ਅਤੇ ਮੈਕੋਸ 'ਤੇ ਚੱਲਦਾ ਹੈ।",
    "ts_sub": "ਟਾਈਪਿੰਗ ਸਪੀਡ ਟ੍ਰੇਨਰ — Electron.js",
    "ts_desc": "ਪੂਰੀ RTL ਸਹਾਇਤਾ (ਅਰਬੀ/ਹਿਬਰੂ/ਫ਼ਾਰਸੀ), ਵਿਸਤ੍ਰਿਤ WPM ਅਤੇ ਸ਼ੁੱਧਤਾ ਅੰਕੜੇ, ਮਾਸਪੇਸ਼ੀ ਮੈਮੋਰੀ, ਗਲੋਬਲ ਸ਼ਾਰਟਕੱਟ ਅਤੇ ਸਿਸਟਮ ਟਰੇ ਬਣਾਉਣ ਲਈ ਗਲਤੀ 'ਤੇ ਜ਼ਬਰਦਸਤੀ ਸਟਾਪ ਦੇ ਨਾਲ ਕ੍ਰਾਸ-ਪਲੇਟਫਾਰਮ ਟਾਈਪਿੰਗ ਟ੍ਰੇਨਰ।",
    "nui_sub": "ਐਂਡਰਾਇਡ ਲਾਂਚਰ — ਕੋਟਲਿਨ + ਜੇਟਪੈਕ ਕੰਪੋਜ਼",
    "nui_desc": "MVVM ਆਰਕੀਟੈਕਚਰ ਅਤੇ ਰੂਮ DB ਦੇ ਨਾਲ ਆਧੁਨਿਕ ਐਂਡਰੌਇਡ ਲਾਂਚਰ: ਬਿਲਟ-ਇਨ ਹਿਜਰੀ/ਗ੍ਰੇਗੋਰੀਅਨ ਕੈਲੰਡਰ, ਹੋਮ-ਸਕ੍ਰੀਨ ਨੋਟਸ, ਆਟੋਮੈਟਿਕ ਐਪ ਵਰਗੀਕਰਨ, ਟ੍ਰੈਸ਼ ਬਿਨ, ਅਤੇ ਸੰਵੇਦਨਸ਼ੀਲ ਐਪਾਂ ਨੂੰ ਲੁਕਾਉਣਾ।",
