    "pomo_sub": "ਪੋਮੋਡੋਰੋ ਉਤਪਾਦਕਤਾ ਟਾਈਮਰ — ਫਲਟਰ",
    "pomo_desc": "ਪੋਮੋਡੋਰੋ ਤਕਨੀਕ ਨਾਲ ਕੰਮ/ਬ੍ਰੇਕ ਸੈਸ਼ਨ ਪ੍ਰਬੰਧਨ: ਅਨੁਕੂਲਿਤ ਰੋਜ਼ਾਨਾ ਅਤੇ ਹਫਤਾਵਾਰੀ ਟੀਚੇ, ਸਾਊਂਡ ਅਲਰਟ, ਮਲਟੀਪਲ ਥੀਮ, ਅਤੇ ਲੀਨਕਸ ਪੈਕੇਜ (Flatpak / .desktop) — 5 ਪਲੇਟਫਾਰਮਾਂ 'ਤੇ ਚੱਲਦਾ ਹੈ।",
