    "haris_sub": "YouTube ਸਮੱਗਰੀ ਫਿਲਟਰ ਅਤੇ ਫੋਕਸ ਐਕਸਟੈਂਸ਼ਨ — TypeScript + WXT",
    "haris_desc": "ਇੱਕ ਓਪਨ-ਸਰੋਤ, ਗੋਪਨੀਯਤਾ-ਪਹਿਲਾ ਕ੍ਰਾਸ-ਬ੍ਰਾਊਜ਼ਰ ਐਕਸਟੈਂਸ਼ਨ ਜੋ YouTube ਨੂੰ 40+ ਭਾਸ਼ਾਵਾਂ ਦਾ ਸਮਰਥਨ ਕਰਨ ਵਾਲੇ ਚੈਨਲ ਵ੍ਹਾਈਟਲਿਸਟਿੰਗ, ਸ਼ਾਰਟਸ ਬਲੌਕਰ ਅਤੇ ਸਥਾਨਕ-ਪਹਿਲੇ ਆਰਕੀਟੈਕਚਰ ਦੇ ਨਾਲ ਇੱਕ ਸਾਫ਼, ਕੇਂਦਰਿਤ ਸਿੱਖਣ ਦੇ ਮਾਹੌਲ ਵਿੱਚ ਬਦਲਦਾ ਹੈ।",
    "miqyas_sub": "ਐਪ ਆਈਕਨ ਸੇਫ-ਜ਼ੋਨ ਸਟੂਡੀਓ ਅਤੇ ਸਟੋਰ ਮੌਕਅਪ — ਫਲਟਰ",
    "miqyas_desc": "ਗੂਗਲ ਪਲੇ ਅਤੇ ਐਪ ਸਟੋਰ ਲਈ ਲਾਈਵ ਮਲਟੀ-ਡਿਵਾਈਸ ਮੌਕਅਪ ਪ੍ਰੀਵਿਊ ਅਤੇ ਸਵੈਚਲਿਤ ਸਟੋਰ ਸਕ੍ਰੀਨਸ਼ਾਟ ਜਨਰੇਟਰ ਦੀ ਵਿਸ਼ੇਸ਼ਤਾ ਵਾਲੇ ਸਾਰੇ ਪਲੇਟਫਾਰਮਾਂ ਵਿੱਚ 66×66 ਸੁਰੱਖਿਅਤ ਜ਼ੋਨ ਦੇ ਅੰਦਰ ਐਪ ਆਈਕਨਾਂ ਨੂੰ ਸਹੀ ਢੰਗ ਨਾਲ ਅਲਾਈਨ ਕਰਨ ਲਈ ਡਿਵੈਲਪਰਾਂ ਲਈ ਇੰਟਰਐਕਟਿਵ ਸਟੂਡੀਓ।",
    "mufarrigh_sub": "ਸਪ੍ਰਾਈਟ ਸ਼ੀਟ ਐਕਸਟਰੈਕਟਰ ਅਤੇ ਬੈਕਗ੍ਰਾਊਂਡ ਰਿਮੂਵਰ — ਫਲਟਰ + ਡਾਰਟ ਵਿਜ਼ਨ",
    "mufarrigh_desc": "ਇੱਕ ਸ਼ੁੱਧ-ਡਾਰਟ ਇੰਜਣ, BFS ਫਲੱਡ-ਫਿਲ, ਅਤੇ ਅਨੁਕੂਲ 3-ਪੈਨ UI ਅਤੇ ਬੈਚ ਨਿਰਯਾਤ ਦੇ ਨਾਲ ਪਾੜੇ ਦੇ ਖਾਤਮੇ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹੋਏ ਸਪ੍ਰਾਈਟ ਸ਼ੀਟਾਂ ਨੂੰ ਕੱਟਣ ਅਤੇ ਪਿਛੋਕੜ ਨੂੰ ਹਟਾਉਣ ਲਈ ਸਮਾਰਟ ਡੈਸਕਟਾਪ ਅਤੇ ਮੋਬਾਈਲ ਟੂਲ।",
    "tips_small": "ਗਾਈਡਾਂ, ਸੂਝ ਅਤੇ ਹੱਲ",
    "tips_title": "💡 ਤਕਨੀਕੀ ਸੁਝਾਅ ਅਤੇ ਹੱਲ",
    "tips_desc": "ਵਿਹਾਰਕ ਗਾਈਡਾਂ, ਸਮੱਸਿਆ-ਨਿਪਟਾਰਾ ਕਰਨ ਦੀ ਸੂਝ, ਅਤੇ ਆਟੋਮੇਸ਼ਨ ਟੂਲ ਵਿਕਾਸ ਅਤੇ ਸਿਸਟਮ ਪ੍ਰਸ਼ਾਸਨ ਦੇ ਦੌਰਾਨ ਪ੍ਰਾਪਤ ਕੀਤੇ ਗਏ ਹਨ।",
    "tip1_badge": "ਫਲਟਰ ਬਿਲਡ ਚੇਤਾਵਨੀ ਅਤੇ ਠੀਕ ਕਰੋ",
    "tip1_title": "ਸੰਸਕਰਣ ਵਿਵਾਦਾਂ ਨੂੰ ਰੋਕਣ ਲਈ ਜਾਵਾ ਐਕਸਟੈਂਸ਼ਨ ਲਈ ਗ੍ਰੇਡਲ ਦੀ ਸਹੀ ਵਰਤੋਂ",
    "tip1_desc": "ਤੁਹਾਡੇ IDE (VS Code / Antigravity) ਵਿੱਚ <b>Gradle for Java</b> ਐਕਸਟੈਂਸ਼ਨ ਨੂੰ ਸਮਰੱਥ ਕਰਦੇ ਸਮੇਂ, ਜੇਕਰ ਤੁਹਾਡੇ <b>Flutter</b> ਪ੍ਰੋਜੈਕਟ ਵਿੱਚ ਇੱਕ ਤੋਂ ਵੱਧ Gradle ਸੰਸਕਰਣ ਜਾਂ ਮੋਡੀਊਲ ਹਨ, ਤਾਂ ਐਕਸਟੈਂਸ਼ਨ ਹਰੇਕ ਨੂੰ ਸੁਤੰਤਰ ਰੂਪ ਵਿੱਚ ਖੋਜਣ ਅਤੇ ਬਣਾਉਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦਾ ਹੈ। ਇਹ ਸੰਸਕਰਣ ਬੇਮੇਲ ਤਰੁੱਟੀਆਂ ਨੂੰ ਟਰਿੱਗਰ ਕਰ ਸਕਦਾ ਹੈ (ਉਦਾਹਰਨ ਲਈ <code>ਨਿਊਨਤਮ ਸਮਰਥਿਤ ਗ੍ਰੇਡਲ ਸੰਸਕਰਣ 9.6.0 ਹੈ। ਮੌਜੂਦਾ ਸੰਸਕਰਣ 9.4.0</code> ਹੈ) ਅਤੇ ਬਿਲਡ ਅਸਫਲਤਾਵਾਂ ਦਾ ਕਾਰਨ ਬਣ ਸਕਦਾ ਹੈ। ਸਿਫ਼ਾਰਿਸ਼ ਕੀਤੀ ਪਹੁੰਚ ਸਮਰਥਿਤ ਵਰਕਸਪੇਸਾਂ ਲਈ ਐਕਸਟੈਂਸ਼ਨ ਨੂੰ ਘੇਰ ਰਹੀ ਹੈ ਜਾਂ ਫਲਟਰ ਸਬ-ਡਾਇਰੈਕਟਰੀਆਂ ਲਈ ਆਟੋਮੈਟਿਕ ਡੂੰਘੀ ਪ੍ਰੋਜੈਕਟ ਖੋਜ ਨੂੰ ਅਯੋਗ ਕਰ ਰਹੀ ਹੈ।",
    "tip2_badge": "ਲੀਨਕਸ ਆਟੋਮੇਸ਼ਨ ਟੂਲ",
    "tip2_sub": "ਲੀਨਕਸ ਆਟੋਮੇਸ਼ਨ ਟੂਲ — Bash + Arch Linux",
    "tip2_title": "ਆਰਕ ਲੀਨਕਸ ਲਈ ਫਲਟਰ ਇੰਸਟੌਲਰ — ਆਟੋਮੇਟਿਡ SDK ਸੈੱਟਅੱਪ",
    "tip2_desc": "ਬਾਸ਼ ਸਕ੍ਰਿਪਟ ਜੋ ਆਰਕ ਲੀਨਕਸ 'ਤੇ ਨਵੀਨਤਮ ਸਥਿਰ ਫਲਟਰ SDK ਨੂੰ ਸਥਾਪਿਤ ਕਰਨ ਲਈ ਸਵੈਚਾਲਤ ਕਰਦੀ ਹੈ: ਆਟੋਮੈਟਿਕ ਹੀ ਅਧਿਕਾਰਤ ਸਰੋਤ ਤੋਂ ਨਵੀਨਤਮ ਰੀਲੀਜ਼ ਲਿਆਉਂਦੀ ਹੈ, ਤਿੰਨ ਸ਼ੈੱਲਾਂ (ਬਾਸ਼, Zsh, ਅਤੇ ਫਿਸ਼) ਵਿੱਚ ਵਾਤਾਵਰਣ ਵੇਰੀਏਬਲਾਂ ਨੂੰ ਕੌਂਫਿਗਰ ਕਰਦੀ ਹੈ, ਅਤੇ ਇੱਕ ਕਦਮ ਵਿੱਚ <code>archlinux-java</code> ਦੁਆਰਾ ਨਵੀਨਤਮ OpenJDK ਨੂੰ ਡਿਫੌਲਟ ਵਜੋਂ ਸੈੱਟ ਕਰਦੀ ਹੈ।",
