    "exp_small": "ڪم جو تجربو",
    "exp_title": "💼 موجوده نوڪري",
    "exp1_title": "آئي ٽي سپورٽ / سسٽم اسسٽنٽ - آئي ٽي سپورٽ ۽ سسٽم اسسٽنٽ",
    "exp1_co": "المجاره ڪمپني",
    "exp1_period": "فيبروري 2026 - آگسٽ 2026",
    "exp1_li1": "ڊزائين ڪيل ۽ ترقي يافته <b>CaseDesk</b>، شاخن ۽ ملازمن لاءِ سپورٽ ٽڪيٽ مئنيجمينٽ سسٽم — آف لائن-فرسٽ آرڪيٽيڪچر دوئي ڊيٽابيس سان (مقامي Hive + ڪلائوڊ ذريعي PHP REST APIs).",
    "exp1_li2": "ترقي ڪئي <b>IT سافٽ ويئر سينٽر</b> ايپ ڪمپني جي نيٽ ورڪ اندر منظور ٿيل سافٽ ويئر ورهائڻ لاءِ خودڪار تازه ڪاري جي ڳولا ۽ هڪ سمارٽ ڊائون لوڊ مئنيجر سان.",
    "exp1_li3": "ٺهيل <b>RatilConvert</b>، جيڪو پروسيس ڪيو ۽ صاف ڪيو <b>+715,463 ڪسٽمر ريڪارڊز</b> ريٽيل پرو کان ۽ انهن کي 100٪ مطابقت سان Odoo ERP ڏانهن برآمد ڪيو - دستي لڏپلاڻ جو وقت 95٪ گهٽايو.",
    "exp1_li4": "draw.io استعمال ڪندي ڪمپني جي فزيڪل نيٽ ورڪ ڊاگرام ٺاهيو، بشمول سرور ڊسٽريبيوشن، فائر وال، ڪور سوئچ، ۽ ڊپارٽمينٽ سوئچز، مڪمل نيٽ ورڪ دستاويزن سان.",
    "exp1_li5": "سار سنڀال ۽ هارڊويئر جا ڪم، تجزيا ڪيا KPIs ذريعي انٽرويو ڊيش بورڊ، ۽ ٺاهيل پروفيشنل عربي PDF/Excel رپورٽون.",
    "exp1_intro": "ڪمپني ۾ منهنجي وقت دوران، مون مڪمل سافٽ ويئر سسٽم ٺاهيا جيڪي روزانو شاخن ۽ ملازمن پاران استعمال ڪيا ويندا آهن: هڪ سپورٽ ٽڪيٽ مينيجمينٽ سسٽم، هڪ اندروني سافٽ ويئر ڊسٽري بيوشن پليٽ فارم، ۽ هڪ وڏو ڊيٽا پروسيسنگ ۽ لڏپلاڻ وارو اوزار — گڏوگڏ نيٽ ورڪ انفراسٽرڪچر کي ڊزائين ڪرڻ ۽ دستاويز ڪرڻ ۽ سار سنڀال ۽ هارڊويئر جا ڪم سنڀالڻ.",
    "boycott_title": "🕊️ ٽيڪنيڪل بائيڪاٽ",
    "boycott_sub": "مضبوط اصول ۽ ايمان جي بنياد تي موقف",
    "boycott_badge": "اصول ۽ موقف",
    "boycott_p1": "هڪ <b>نيٽ ورڪ اسپيشلسٽ</b> جي حيثيت سان، مان ان جو بائيڪاٽ ڪريان ٿو <b>سِسڪو</b> جو انهن جي گستاخي ۽ انبياءَ جي قاتلن ۽ ظالمن جي حمايت جي ڪري. سسڪو کان تصديق ٿيل سندون رکڻ جي باوجود، مان خوشيءَ سان الله جي واسطي انهن کي ڇڏي ڏيان ٿو. جيڪو به منهنجي مسلمان ڀائرن کي ايذاءُ پهچائيندو ته مان پنهنجي ذاتي مفادن جي ڪري به ان کي ڇڏي ڏيندس، ڇو ته اسان جو رزق الله تعاليٰ تي آهي، جيڪو بي پرواهه ۽ ساراهيل آهي.",
    "boycott_p2": "<b>آئون انهن ڪارپوريشنن جو بائيڪاٽ ڪريان ٿو، پر اسان ان مان وڌ ۾ وڌ فائدو ڪيئن ٿا حاصل ڪريون؟</b><br>جڏهن مون هڪ ڪمپني ۾ ڪم ڪيو جتي مون ڊيٽابيسس کي ترتيب ڏيڻ ۾ مدد ڪئي، مون <b>Oracle</b> کي ان جي مدد ڪرڻ کي يقيني بڻائڻ يا استعمال ڪرڻ کان پاسو ڪيو. جيڪڏهن ڪو معمولي غلطي ڪري ٿو، ته اهي ان مان سکندا آهن؛ جيستائين منهنجو ڪنهن به فرم ۾ هٿ يا ٽيڪنيڪل اثر آهي، مان صرف ٽيڪنالاجي استعمال ڪريان ٿو جيڪي اسان جي ڀائرن جو رت وهائڻ وارن جي مدد نه ڪن، ۽ منهنجو رزق الله تي آهي.",
    "boycott_p3": "۽ الحمد لله، اڄڪلهه هر ٽيڪنالاجي جو هڪ آزاد ۽ خودمختيار متبادل آهي.. ۽ توهان هن وقتي زندگي مان نڪري ويندا (پوءِ الله کان ڊڄو).",
