    "haris_desc": "هڪ کليل-ذريعو، رازداري-پهريون ڪراس-براؤزر ايڪسٽينشن جيڪو يوٽيوب کي هڪ صاف، مرڪوز سکيا واري ماحول ۾ تبديل ڪري ٿو چينل وائيٽ لسٽنگ، شارٽس بلاڪر، ۽ مقامي-پهرين آرڪيٽيڪچر سان 40+ ٻولين جي مدد سان.",
