    "tip1_desc": "جڏهن توهان جي IDE (VS Code / Antigravity) ۾ <b>Gradle for Java</b> ايڪسٽينشن کي فعال ڪيو وڃي، جيڪڏهن توهان جي <b>Flutter</b> پروجيڪٽ ۾ ڪيترائي Gradle ورجن يا ماڊل شامل آهن، ته ايڪسٽينشن ڪوشش ڪري ٿي ته هر هڪ کي آزاديءَ سان دريافت ڪرڻ ۽ ٺاهڻ جي. هي نسخو جي ميلاپ جي غلطين کي ٽرگر ڪري سگهي ٿو (مثال طور <code>گهٽ ۾ گهٽ سپورٽ ٿيل گرڊل ورزن 9.6.0 آهي. موجوده ورزن 9.4.0 آهي</code>) ۽ تعمير ناڪامي جو سبب بڻجن ٿا. تجويز ڪيل طريقه معاون ڪم جي جڳهن ڏانهن توسيع کي اسڪوپ ڪري رهيو آهي يا فلٽر سب ڊاريڪٽريز لاءِ خودڪار ڊيپ پروجيڪٽ دريافت کي غير فعال ڪرڻ.",
