    "boycott_p1": "एक <b>नेटवर्क विशेषज्ञ</b> के रूप में, मैं पैगंबरों और उत्पीड़कों के हत्यारों के प्रति उनकी गहरी मिलीभगत और समर्थन के कारण <b>सिस्को</b> का बहिष्कार करता हूं। सिस्को से प्रमाणित प्रमाण-पत्र रखने के बावजूद, मैं अल्लाह की खातिर ख़ुशी से उन्हें त्याग देता हूँ। जो कोई भी मेरे मुस्लिम भाइयों को नुकसान पहुंचाएगा, मैं अपने व्यक्तिगत हितों की कीमत पर भी त्याग कर दूंगा - क्योंकि हमारा भरण-पोषण आत्मनिर्भर, प्रशंसनीय अल्लाह पर है।",
    "boycott_p2": "<b>मैं इन निगमों का बहिष्कार करता हूं, लेकिन हम इससे अधिकतम लाभ कैसे उठा सकते हैं?</b><br>एक ऐसी कंपनी में काम करते समय जहां मैंने डेटाबेस तैनात करने में मदद की, मैंने उन्हें समर्थन न देना सुनिश्चित करने के लिए <b>Oracle</b> को तैनात करने या उपयोग करने से परहेज किया। यदि कोई थोड़ी सी भी गलती करता है, तो वे उससे सीखते हैं; जब तक किसी फर्म में मेरा हाथ है या तकनीकी प्रभाव है, मैं केवल उन प्रौद्योगिकियों का उपयोग करता हूं जो हमारे भाइयों का खून बहाने वालों का समर्थन नहीं करते हैं, और मेरा भरण-पोषण अल्लाह पर है।",
    "boycott_p3": "और अल्लाह की स्तुति करो, आज हर तकनीक का एक स्वतंत्र और स्वतंत्र विकल्प है.. और इस क्षणभंगुर जीवन से तुम चले जाओगे (इसलिए अल्लाह से डरो)।",
