    "lm_desc": "बिना किसी इनपुट वीडियो के एनिमेटेड टेक्स्ट वॉटरमार्क के साथ MP4 वीडियो जेनरेट करता है: पूर्ण डायक्रिटिक्स समर्थन के साथ उच्च निष्ठा पर फ़्लटर कैनवस इंजन के साथ प्रस्तुत अरबी पाठ, एंड्रॉइड और विंडोज पर एफएफएमपीईजी के माध्यम से निर्यात किया जाता है।",
