    "rom1_desc": "इवोल्यूशन एक्स लेयर, कस्टम कर्नेल ट्यूनिंग और डिवाइस ट्री, एचएएल फिक्स और कैमरा सेटअप और Xiaomi हार्डवेयर पर पिक्सेल अनुभव के साथ स्रोत से पूर्ण AOSP बिल्ड।",
    "rom2_desc": "एओएसपी एंड्रॉइड 16 इन्फिनिटी एक्स सुविधाओं, कर्नेल और डिवाइस ट्री ट्यूनिंग, और विक्रेता ब्लॉब और एचएएल प्रबंधन के साथ स्रोत से निर्मित होता है।",
    "rom3_desc": "PixelOS कर्नेल संकलन, डिवाइस ट्री सेटअप और विक्रेता ब्लॉब निष्कर्षण के साथ स्रोत से निर्मित होता है - मोटोरोला हार्डवेयर पर एक साफ पिक्सेल अनुभव।",
    "rom4_desc": "Google सेवाओं (GApps) के बिना वेनिला बिल्ड - एक ही डिवाइस पर 100% शुद्ध AOSP अनुभव।",
    "rom4_tag3": "कोई GApps नहीं",
    "rom5_desc": "Moto G54 5G के लिए आधिकारिक LineageOS 23.2 ROM का रखरखाव और निर्माण - नियमित सुरक्षा अपडेट के साथ एक स्थिर, हल्का ओपन-सोर्स ROM।",
