    "haris_sub": "YouTube सामग्री फ़िल्टर और फ़ोकस एक्सटेंशन - टाइपस्क्रिप्ट + WXT",
    "haris_desc": "एक ओपन-सोर्स, गोपनीयता-प्रथम क्रॉस-ब्राउज़र एक्सटेंशन जो यूट्यूब को चैनल व्हाइटलिस्टिंग, शॉर्ट्स ब्लॉकर और 40+ भाषाओं का समर्थन करने वाले स्थानीय-प्रथम आर्किटेक्चर के साथ एक स्वच्छ, केंद्रित सीखने के माहौल में बदल देता है।",
    "miqyas_sub": "ऐप आइकन सेफ-ज़ोन स्टूडियो और स्टोर मॉकअप - फ़्लटर",
    "miqyas_desc": "सभी प्लेटफार्मों पर 66×66 सुरक्षित क्षेत्र के भीतर ऐप आइकन को सटीक रूप से संरेखित करने के लिए डेवलपर्स के लिए इंटरैक्टिव स्टूडियो, जिसमें लाइव मल्टी-डिवाइस मॉकअप पूर्वावलोकन और Google Play और ऐप स्टोर के लिए स्वचालित स्टोर स्क्रीनशॉट जनरेटर शामिल है।",
    "mufarrigh_sub": "स्प्राइट शीट एक्सट्रैक्टर और बैकग्राउंड रिमूवर - फ़्लटर + डार्ट विज़न",
    "mufarrigh_desc": "प्योर-डार्ट इंजन, बीएफएस फ्लड-फिल और अनुकूली 3-फलक यूआई और बैच निर्यात के साथ गैप इरोशन का उपयोग करके स्प्राइट शीट को स्लाइस करने और पृष्ठभूमि को हटाने के लिए स्मार्ट डेस्कटॉप और मोबाइल टूल।",
    "tips_small": "मार्गदर्शिकाएँ, अंतर्दृष्टि और समाधान",
    "tips_title": "💡तकनीकी युक्तियाँ और समाधान",
    "tips_desc": "विकास और सिस्टम प्रशासन के दौरान प्राप्त व्यावहारिक मार्गदर्शिकाएँ, समस्या निवारण अंतर्दृष्टि और स्वचालन उपकरण।",
    "tip1_badge": "स्पंदन निर्माण चेतावनी और समाधान",
    "tip1_title": "संस्करण विरोधों को रोकने के लिए जावा एक्सटेंशन के लिए ग्रैडल का सही उपयोग",
    "tip1_desc": "आपके आईडीई (वीएस कोड / एंटीग्रेविटी) में <b>ग्रैडल फॉर जावा</b> एक्सटेंशन को सक्षम करते समय, यदि आपके <b>फ़्लटर</b> प्रोजेक्ट में कई ग्रैडल संस्करण या मॉड्यूल हैं, तो एक्सटेंशन प्रत्येक को स्वतंत्र रूप से खोजने और बनाने का प्रयास करता है। यह संस्करण बेमेल त्रुटियों को ट्रिगर कर सकता है (उदाहरण के लिए <कोड>न्यूनतम समर्थित ग्रैडल संस्करण 9.6.0 है। वर्तमान संस्करण 9.4.0 है</कोड>) और बिल्ड विफलताओं का कारण बन सकता है। अनुशंसित दृष्टिकोण समर्थित कार्यस्थानों तक विस्तार का दायरा बढ़ाना या फ़्लटर उपनिर्देशिकाओं के लिए स्वचालित गहरी परियोजना खोज को अक्षम करना है।",
    "tip2_badge": "लिनक्स स्वचालन उपकरण",
    "tip2_sub": "लिनक्स स्वचालन उपकरण - बैश + आर्क लिनक्स",
    "tip2_title": "आर्क लिनक्स के लिए फ़्लटर इंस्टालर - स्वचालित एसडीके सेटअप",
    "tip2_desc": "बैश स्क्रिप्ट जो आर्क लिनक्स पर नवीनतम स्थिर फ़्लटर एसडीके को स्थापित करने को स्वचालित करती है: स्वचालित रूप से आधिकारिक स्रोत से नवीनतम रिलीज़ प्राप्त करती है, तीन शेल (बैश, ज़ेडश और फिश) में पर्यावरण चर को कॉन्फ़िगर करती है, और एक चरण में <कोड>आर्चलिनक्स-जावा</कोड> के माध्यम से नवीनतम ओपनजेडीके को डिफ़ॉल्ट के रूप में सेट करती है।",
    "tip_img_tag": "📸 एक्सटेंशन और त्रुटि स्क्रीनशॉट",
    "tip_vid_tag": "🎬 प्रदर्शन वीडियो",
