    "oracle_desc": "കോർപ്പറേറ്റ് സങ്കീർണ്ണത രേഖപ്പെടുത്തുകയും ഓപ്പൺ സോഴ്‌സ് ഇതരമാർഗ്ഗങ്ങൾ (PostgreSQL, MariaDB എന്നിവ പോലുള്ളവ) സ്വീകരിക്കുകയും ചെയ്യുന്നു:",
    "boycott_tip": "<b>നിർബന്ധിതർക്കുള്ള ഉപദേശം:</b> ബഹിഷ്‌ക്കരിച്ച ഒരു സ്ഥാപനത്തിൽ നിന്ന് ഒരു ഉൽപ്പന്നം വാങ്ങാൻ ആരെങ്കിലും നിർബന്ധിതനാകുകയാണെങ്കിൽ, അത് <b>സെക്കൻഡ് ഹാൻഡ് / യൂസ്ഡ്</b> വാങ്ങുക, അങ്ങനെ കമ്പനിക്ക് പുതിയ ലാഭം പൂജ്യമാകും. അല്ലാഹുവിന് സ്തുതിയും അവനിൽ ഞങ്ങൾ ആശ്രയിക്കുന്നു.",
