    "casedesk_sub": "ഐടി പിന്തുണ ടിക്കറ്റ് മാനേജ്മെൻ്റ് സിസ്റ്റം - ഫ്ലട്ടർ ഡെസ്ക്ടോപ്പ്",
    "casedesk_desc": "ബ്രാഞ്ചുകൾക്കും ജീവനക്കാർക്കുമുള്ള ഹെൽപ്പ് ഡെസ്‌ക് സംവിധാനം പൂർത്തിയാക്കുക: ഓഫ്‌ലൈൻ-ആദ്യ ക്ലൗഡ് സമന്വയം, ഇൻ്ററാക്ടീവ് കെപിഐ അനലിറ്റിക്‌സ് ഡാഷ്‌ബോർഡ്, അറബിക് PDF/Excel റിപ്പോർട്ടുകൾ, സ്മാർട്ട് ടിക്കറ്റ് ഓട്ടോഫിൽ, വാട്ട്‌സ്ആപ്പ് അറിയിപ്പുകൾ.",
