    "haris_sub": "YouTube ഉള്ളടക്ക ഫിൽട്ടറും ഫോക്കസ് വിപുലീകരണവും - ടൈപ്പ്സ്ക്രിപ്റ്റ് + WXT",
    "haris_desc": "ചാനൽ വൈറ്റ്‌ലിസ്റ്റിംഗ്, ഷോർട്ട്സ് ബ്ലോക്കർ, 40+ ഭാഷകളെ പിന്തുണയ്ക്കുന്ന ലോക്കൽ ഫസ്റ്റ് ആർക്കിടെക്ചർ എന്നിവ ഉപയോഗിച്ച് YouTube-നെ വൃത്തിയുള്ളതും കേന്ദ്രീകൃതവുമായ പഠന അന്തരീക്ഷമാക്കി മാറ്റുന്ന ഒരു ഓപ്പൺ സോഴ്‌സ്, സ്വകാര്യത-ആദ്യ ക്രോസ്-ബ്രൗസർ വിപുലീകരണം.",
    "miqyas_sub": "ആപ്പ് ഐക്കൺ സേഫ് സോൺ സ്റ്റുഡിയോ & സ്റ്റോർ മോക്കപ്പുകൾ - ഫ്ലട്ടർ",
    "miqyas_desc": "എല്ലാ പ്ലാറ്റ്‌ഫോമുകളിലും 66×66 സേഫ് സോണിനുള്ളിൽ ആപ്പ് ഐക്കണുകൾ കൃത്യമായി വിന്യസിക്കാൻ ഡവലപ്പർമാർക്കുള്ള ഇൻ്ററാക്ടീവ് സ്റ്റുഡിയോ, തത്സമയ മൾട്ടി-ഡിവൈസ് മോക്കപ്പ് പ്രിവ്യൂവും Google Play, App Store എന്നിവയ്‌ക്കായുള്ള ഓട്ടോമേറ്റഡ് സ്റ്റോർ സ്‌ക്രീൻഷോട്ട് ജനറേറ്ററും ഫീച്ചർ ചെയ്യുന്നു.",
    "mufarrigh_sub": "സ്‌പ്രൈറ്റ് ഷീറ്റ് എക്‌സ്‌ട്രാക്‌ടറും ബാക്ക്‌ഗ്രൗണ്ട് റിമൂവറും - ഫ്ലട്ടർ + ഡാർട്ട് വിഷൻ",
    "mufarrigh_desc": "ശുദ്ധമായ ഡാർട്ട് എഞ്ചിൻ, BFS ഫ്ലഡ്-ഫിൽ, അഡാപ്റ്റീവ് 3-പേൻ UI, ബാച്ച് എക്‌സ്‌പോർട്ട് എന്നിവ ഉപയോഗിച്ച് സ്‌പ്രൈറ്റ് ഷീറ്റുകൾ മുറിക്കുന്നതിനും പശ്ചാത്തലങ്ങൾ നീക്കം ചെയ്യുന്നതിനുമുള്ള സ്മാർട്ട് ഡെസ്‌ക്‌ടോപ്പും മൊബൈൽ ടൂളും.",
    "tips_small": "വഴികാട്ടികളും സ്ഥിതിവിവരക്കണക്കുകളും പരിഹാരങ്ങളും",
    "tips_title": "💡 സാങ്കേതിക നുറുങ്ങുകളും പരിഹാരങ്ങളും",
    "tips_desc": "വികസനത്തിലും സിസ്റ്റം അഡ്മിനിസ്ട്രേഷനിലും നേടിയ പ്രായോഗിക ഗൈഡുകൾ, ട്രബിൾഷൂട്ടിംഗ് സ്ഥിതിവിവരക്കണക്കുകൾ, ഓട്ടോമേഷൻ ടൂളുകൾ.",
    "tip1_badge": "ഫ്ലട്ടർ ബിൽഡ് മുന്നറിയിപ്പ് & പരിഹരിക്കുക",
    "tip1_title": "പതിപ്പ് വൈരുദ്ധ്യങ്ങൾ തടയുന്നതിന് Java വിപുലീകരണത്തിനായുള്ള Gradle-ൻ്റെ ശരിയായ ഉപയോഗം",
    "tip1_desc": "നിങ്ങളുടെ IDE-ൽ (VS കോഡ് / ആൻ്റിഗ്രാവിറ്റി) <b>Java-നുള്ള Gradle</b> വിപുലീകരണം പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ, നിങ്ങളുടെ <b>Flutter</b> പ്രോജക്റ്റിൽ ഒന്നിലധികം Gradle പതിപ്പുകളോ മൊഡ്യൂളുകളോ അടങ്ങിയിട്ടുണ്ടെങ്കിൽ, ഓരോന്നും സ്വതന്ത്രമായി കണ്ടെത്താനും നിർമ്മിക്കാനും വിപുലീകരണം ശ്രമിക്കുന്നു. ഇത് പതിപ്പിൻ്റെ പൊരുത്തക്കേട് പിശകുകൾ (ഉദാ. <code>കുറഞ്ഞ പിന്തുണയുള്ള Gradle പതിപ്പ് 9.6.0 ആണ്. നിലവിലെ പതിപ്പ് 9.4.0</code>) പ്രവർത്തനക്ഷമമാക്കുകയും ബിൽഡ് പരാജയങ്ങൾക്ക് കാരണമാവുകയും ചെയ്യും. പിന്തുണയ്‌ക്കുന്ന വർക്ക്‌സ്‌പെയ്‌സുകളിലേക്കുള്ള വിപുലീകരണം സ്‌കോപ്പ് ചെയ്യുകയോ ഫ്ലട്ടർ സബ്‌ഡയറക്‌ടറികൾക്കായി സ്വയമേവയുള്ള ആഴത്തിലുള്ള പ്രോജക്‌റ്റ് കണ്ടെത്തൽ പ്രവർത്തനരഹിതമാക്കുകയോ ആണ് ശുപാർശ ചെയ്യുന്ന സമീപനം.",
    "tip2_badge": "ലിനക്സ് ഓട്ടോമേഷൻ ടൂൾ",
    "tip2_sub": "Linux ഓട്ടോമേഷൻ ടൂൾ — Bash + Arch Linux",
    "tip2_title": "ആർച്ച് ലിനക്സിനുള്ള ഫ്ലട്ടർ ഇൻസ്റ്റാളർ - ഓട്ടോമേറ്റഡ് SDK സജ്ജീകരണം",
    "tip2_desc": "Arch Linux-ൽ ഏറ്റവും പുതിയ സ്ഥിരതയുള്ള Flutter SDK ഇൻസ്റ്റാൾ ചെയ്യുന്നത് ഓട്ടോമേറ്റ് ചെയ്യുന്ന ബാഷ് സ്‌ക്രിപ്റ്റ്: ഔദ്യോഗിക ഉറവിടത്തിൽ നിന്നും ഏറ്റവും പുതിയ റിലീസ് സ്വയമേവ ലഭ്യമാക്കുന്നു, മൂന്ന് ഷെല്ലുകളിൽ (Bash, Zsh, Fish) എൻവയോൺമെൻ്റ് വേരിയബിളുകൾ കോൺഫിഗർ ചെയ്യുന്നു, കൂടാതെ <code>archlinux-java</code> വഴി ഏറ്റവും പുതിയ OpenJDK സ്ഥിരസ്ഥിതിയായി സജ്ജീകരിക്കുന്നു.",
    "tip_img_tag": "📸 വിപുലീകരണവും പിശക് സ്ക്രീൻഷോട്ടും",
