    "contact_small": "பேசலாம்",
    "contact_title": "📬 என்னை தொடர்பு கொள்ளவும்",
    "contact_desc": "IT ஆதரவு, அமைப்புகள் மற்றும் பயன்பாட்டு மேம்பாடு ஆகியவற்றில் வேலை வாய்ப்புகள் திறக்கப்பட்டுள்ளன.",
    "contact_email": "மின்னஞ்சல்",
    "contact_phone": "தொலைபேசி",
    "contact_cv": "CV ஐப் பதிவிறக்கவும்",
    "view_github": "GitHub இல் காண்க →",
    "nav_tips": "தொழில்நுட்ப குறிப்புகள்",
    "haris_sub": "YouTube உள்ளடக்க வடிகட்டி & ஃபோகஸ் நீட்டிப்பு - டைப்ஸ்கிரிப்ட் + WXT",
    "haris_desc": "சேனல் அனுமதிப்பட்டியல், ஷார்ட்ஸ் பிளாக்கர் மற்றும் 40+ மொழிகளை ஆதரிக்கும் லோக்கல் ஃபர்ஸ்ட் ஆர்கிடெக்சர் மூலம் YouTubeஐ சுத்தமான, கவனம் செலுத்தும் கற்றல் சூழலாக மாற்றும் திறந்த மூல, தனியுரிமை முதல் குறுக்கு உலாவி நீட்டிப்பு.",
    "miqyas_sub": "பயன்பாட்டு ஐகான் பாதுகாப்பான-மண்டல ஸ்டுடியோ & ஸ்டோர் மொக்கப்கள் — படபடப்பு",
    "miqyas_desc": "டெவலப்பர்களுக்கான ஊடாடும் ஸ்டுடியோ, எல்லா தளங்களிலும் 66×66 பாதுகாப்பான மண்டலத்திற்குள் ஆப்ஸ் ஐகான்களை துல்லியமாக சீரமைக்க, இதில் நேரடி பல சாதன மொக்கப் முன்னோட்டம் மற்றும் Google Play மற்றும் App Store க்கான தானியங்கு ஸ்டோர் ஸ்கிரீன்ஷாட் ஜெனரேட்டர் ஆகியவை இடம்பெற்றுள்ளன.",
    "mufarrigh_sub": "ஸ்ப்ரைட் ஷீட் எக்ஸ்ட்ராக்டர் & பேக்ரவுண்ட் ரிமூவர் - ஃப்ளட்டர் + டார்ட் விஷன்",
    "mufarrigh_desc": "ஸ்மார்ட் டெஸ்க்டாப் & மொபைல் டூல் ஸ்ப்ரைட் ஷீட்களை ஸ்லைஸ் செய்யவும், ப்யூர்-டார்ட் இன்ஜின், BFS ஃப்ளட்-ஃபில் மற்றும் பேட்ச் எக்ஸ்போர்ட்டுடன் அடாப்டிவ் 3-பேன் UI மற்றும் பேட்ச் ஏற்றுமதியைப் பயன்படுத்தி பின்னணியை அகற்றவும்.",
    "tips_small": "வழிகாட்டிகள், நுண்ணறிவு மற்றும் தீர்வுகள்",
    "tips_title": "💡 தொழில்நுட்ப குறிப்புகள் மற்றும் தீர்வுகள்",
    "tips_desc": "மேம்பாடு மற்றும் அமைப்பு நிர்வாகத்தின் போது பெறப்பட்ட நடைமுறை வழிகாட்டிகள், சரிசெய்தல் நுண்ணறிவு மற்றும் ஆட்டோமேஷன் கருவிகள்.",
    "tip1_badge": "Flutter Build Warning & Fix",
    "tip1_title": "பதிப்பு முரண்பாடுகளைத் தடுக்க Java நீட்டிப்புக்கான Gradle இன் சரியான பயன்பாடு",
    "tip1_desc": "உங்கள் IDE (VS Code / Antigravity) இல் <b>Gradle for Java</b> நீட்டிப்பை இயக்கும் போது, ​​உங்கள் <b>Flutter</b> திட்டத்தில் பல Gradle பதிப்புகள் அல்லது தொகுதிகள் இருந்தால், நீட்டிப்பு ஒவ்வொன்றையும் தனித்தனியாகக் கண்டறிந்து உருவாக்க முயற்சிக்கும். இது பதிப்பு பொருந்தாத பிழைகளைத் தூண்டலாம் (எ.கா. <code>குறைந்தபட்ச ஆதரிக்கப்படும் Gradle பதிப்பு 9.6.0. தற்போதைய பதிப்பு 9.4.0</code>) மற்றும் உருவாக்கத் தோல்விகளை ஏற்படுத்தும். பரிந்துரைக்கப்பட்ட அணுகுமுறையானது, ஆதரிக்கப்படும் பணியிடங்களுக்கு நீட்டிப்பைக் கண்டறிவது அல்லது ஃப்ளட்டர் துணை அடைவுகளுக்கான தானியங்கி ஆழமான திட்டக் கண்டுபிடிப்பை முடக்குவது.",
    "tip2_badge": "லினக்ஸ் ஆட்டோமேஷன் கருவி",
    "tip2_sub": "லினக்ஸ் ஆட்டோமேஷன் கருவி — பாஷ் + ஆர்ச் லினக்ஸ்",
    "tip2_title": "Arch Linux க்கான Flutter Installer — தானியங்கு SDK அமைப்பு",
    "tip2_desc": "Arch Linux இல் சமீபத்திய நிலையான Flutter SDK ஐ நிறுவுவதை தானியங்குபடுத்தும் Bash ஸ்கிரிப்ட்: அதிகாரப்பூர்வ மூலத்திலிருந்து தானாகவே புதிய வெளியீட்டைப் பெறுகிறது, மூன்று ஷெல்களில் (Bash, Zsh மற்றும் Fish) சூழல் மாறிகளை உள்ளமைக்கிறது மற்றும் <code>archlinux-java</code> வழியாக சமீபத்திய OpenJDK ஐ இயல்புநிலையாக அமைக்கிறது.",
    "tip_img_tag": "📸 நீட்டிப்பு & பிழை ஸ்கிரீன்ஷாட்",
    "tip_vid_tag": "🎬 ஆர்ப்பாட்ட வீடியோ",
