    "contact_small": "మాట్లాడుకుందాం",
    "contact_title": "📬 నన్ను సంప్రదించండి",
    "contact_desc": "IT మద్దతు, సిస్టమ్‌లు మరియు యాప్ డెవలప్‌మెంట్‌లో ఉద్యోగ అవకాశాలకు తెరవండి.",
    "contact_email": "ఇమెయిల్",
