    "contact_cv": "CVని డౌన్‌లోడ్ చేయండి",
    "view_github": "GitHub →లో వీక్షించండి",
    "nav_tips": "సాంకేతిక చిట్కాలు",
    "haris_sub": "YouTube కంటెంట్ ఫిల్టర్ & ఫోకస్ పొడిగింపు — టైప్‌స్క్రిప్ట్ + WXT",
    "haris_desc": "ఛానెల్ వైట్‌లిస్టింగ్, షార్ట్‌ల బ్లాకర్ మరియు 40+ భాషలకు మద్దతిచ్చే లోకల్-ఫస్ట్ ఆర్కిటెక్చర్‌తో యూట్యూబ్‌ను క్లీన్, ఫోకస్డ్ లెర్నింగ్ ఎన్విరాన్‌మెంట్‌గా మార్చే ఓపెన్ సోర్స్, గోప్యత-ఫస్ట్ క్రాస్-బ్రౌజర్ ఎక్స్‌టెన్షన్.",
    "miqyas_sub": "యాప్ చిహ్నం సేఫ్-జోన్ స్టూడియో & స్టోర్ మాక్‌అప్‌లు — ఫ్లట్టర్",
    "miqyas_desc": "అన్ని ప్లాట్‌ఫారమ్‌లలో 66×66 సేఫ్ జోన్‌లోని యాప్ చిహ్నాలను ఖచ్చితంగా సమలేఖనం చేయడానికి డెవలపర్‌ల కోసం ఇంటరాక్టివ్ స్టూడియో, లైవ్ మల్టీ-డివైస్ మాకప్ ప్రివ్యూ మరియు Google Play మరియు App Store కోసం ఆటోమేటెడ్ స్టోర్ స్క్రీన్‌షాట్ జెనరేటర్.",
    "mufarrigh_sub": "స్ప్రైట్ షీట్ ఎక్స్‌ట్రాక్టర్ & బ్యాక్‌గ్రౌండ్ రిమూవర్ — ఫ్లట్టర్ + డార్ట్ విజన్",
    "mufarrigh_desc": "ప్యూర్-డార్ట్ ఇంజిన్, BFS ఫ్లడ్-ఫిల్ మరియు అడాప్టివ్ 3-పేన్ UI మరియు బ్యాచ్ ఎగుమతితో గ్యాప్ ఎరోషన్‌ని ఉపయోగించి స్ప్రైట్ షీట్‌లను స్లైస్ చేయడానికి మరియు బ్యాక్‌గ్రౌండ్‌లను తీసివేయడానికి స్మార్ట్ డెస్క్‌టాప్ & మొబైల్ సాధనం.",
    "tips_small": "మార్గదర్శకాలు, అంతర్దృష్టులు & పరిష్కారాలు",
    "tips_title": "💡 సాంకేతిక చిట్కాలు & పరిష్కారాలు",
    "tips_desc": "డెవలప్‌మెంట్ మరియు సిస్టమ్స్ అడ్మినిస్ట్రేషన్ సమయంలో పొందిన ప్రాక్టికల్ గైడ్‌లు, ట్రబుల్షూటింగ్ అంతర్దృష్టులు మరియు ఆటోమేషన్ సాధనాలు.",
    "tip1_badge": "ఫ్లట్టర్ బిల్డ్ హెచ్చరిక & పరిష్కరించండి",
    "tip1_title": "సంస్కరణ వైరుధ్యాలను నివారించడానికి Java పొడిగింపు కోసం Gradle యొక్క సరైన ఉపయోగం",
    "tip1_desc": "మీ IDE (VS కోడ్ / యాంటీగ్రావిటీ)లో <b>Java కోసం Gradle</b> పొడిగింపును ప్రారంభించినప్పుడు, మీ <b>Flutter</b> ప్రాజెక్ట్ బహుళ గ్రేడిల్ వెర్షన్‌లు లేదా మాడ్యూల్‌లను కలిగి ఉన్నట్లయితే, పొడిగింపు ప్రతి ఒక్కటి స్వతంత్రంగా కనుగొని నిర్మించడానికి ప్రయత్నిస్తుంది. ఇది సంస్కరణ సరిపోలని లోపాలను ప్రేరేపిస్తుంది (ఉదా. <code>కనీస మద్దతు ఉన్న గ్రేడిల్ వెర్షన్ 9.6.0. ప్రస్తుత వెర్షన్ 9.4.0</code>) మరియు బిల్డ్ వైఫల్యాలకు కారణమవుతుంది. సిఫార్సు చేయబడిన విధానం మద్దతు ఉన్న వర్క్‌స్పేస్‌లకు పొడిగింపును స్కోప్ చేయడం లేదా ఫ్లట్టర్ సబ్ డైరెక్టరీల కోసం ఆటోమేటిక్ డీప్ ప్రాజెక్ట్ డిస్కవరీని నిలిపివేయడం.",
    "tip2_badge": "Linux ఆటోమేషన్ సాధనం",
    "tip2_sub": "Linux ఆటోమేషన్ సాధనం — Bash + Arch Linux",
    "tip2_title": "ఆర్చ్ లైనక్స్ కోసం ఫ్లట్టర్ ఇన్‌స్టాలర్ — ఆటోమేటెడ్ SDK సెటప్",
    "tip2_desc": "ఆర్చ్ లైనక్స్‌లో తాజా స్థిరమైన ఫ్లట్టర్ SDKని ఇన్‌స్టాల్ చేయడాన్ని ఆటోమేట్ చేసే బాష్ స్క్రిప్ట్: అధికారిక మూలం నుండి స్వయంచాలకంగా సరికొత్త విడుదలను పొందుతుంది, మూడు షెల్‌లలో (Bash, Zsh మరియు Fish) ఎన్విరాన్‌మెంట్ వేరియబుల్‌లను కాన్ఫిగర్ చేస్తుంది మరియు <code>archlinux-java</code> ద్వారా తాజా OpenJDKని డిఫాల్ట్‌గా సెట్ చేస్తుంది.",
    "tip_img_tag": "📸 పొడిగింపు & ఎర్రర్ స్క్రీన్‌షాట్",
