    "exp1_period": "Febraayo 2026 - Ogosto 2026",
    "exp1_li1": "Naqshadeeyey oo la horumariyey <b>CaseDesk</b>, nidaamka maaraynta tigidhada taageerada laamaha iyo shaqaalaha - Qaab-dhismeedka Offline-First oo leh xog-ururin (Hive + daruur maxalli ah oo loo sii marayo PHP REST APIs).",
    "exp1_li2": "Waxa la sameeyay <b>IT Software Center</b> abka si loogu qaybiyo software la ansixiyey gudaha shabakadda shirkadda oo leh ogaanshaha cusboonaysiinta tooska ah iyo maamulaha soo dejinta smart.",
    "exp1_li3": "La dhisay <b>RatilConvert</b>, kaas oo farsameeyay oo nadiifiyay <b>+715,463 diiwaanka macaamiisha</b> ee Tafaariiqda Pro oo u dhoofisay iyaga oo 100% waafaqsan Odoo ERP - gooyay wakhtiga socdaalka gacanta 95%.",
    "exp1_li4": "Naqshadeeyay jaantuska shabakadda jirka ee shirkadda iyadoo la adeegsanayo draw.io, oo ay ku jiraan qaybinta server-ka, dab-damiska, furaha muhiimka ah, iyo furayaasha waaxaha, oo wata dukumeenti shabakadeed buuxa.",
    "exp1_li5": "Dayactirka iyo hawlaha qalabka, lagu falanqeeyay KPI-yada iyada oo loo marayo dashboards is-dhexgal ah, oo la soo saaray warbixinno Carabi ah oo PDF/Excel ah.",
    "exp1_intro": "Muddadii aan joogay shirkadda, waxaan sameeyay nidaamyo software oo dhamaystiran oo ay isticmaalaan maalin kasta laamaha iyo shaqaaluhu: nidaamka maaraynta tigidhada taageerada, madal qaybinta software-ka gudaha, iyo farsamaynta xogta weyn iyo qalabka socdaalka - oo ay weheliso naqshadaynta iyo diiwaangelinta kaabayaasha shabakada iyo maaraynta dayactirka & hawlaha qalabka.",
    "boycott_title": "🕊️ Qaadacidda Farsamada",
    "boycott_sub": "Mabda'a Adag & Mowqifka Ku Salaysan Iimaanka",
    "boycott_badge": "Mabda'a & Mawqifka",
    "boycott_p1": "Anigoo ah<b>ku takhasusay shabakada</b>, waxaan qaadacay <b>Cisco</b> sababtoo ah ka qaybqaadashadooda qoto dheer iyo taageerada ay u hayaan gacan-ku-dhiiglayaasha nebiyada iyo daalimiinta. In kasta oo aan haysto shahaadooyin shahaado ah oo Cisco ah, waxaan si farxad leh uga tanaasulay Allaah dartiis. Ciddii dhib u geysata walaalahayga muslimiinta ah waan ka tagayaa xitaa aniga oo dantayda gaarka ah ku fushanaya – arsaaqadeennu waxay u sugnaatay Eebbaha isku filan ee la mahadiyo.",
    "boycott_p2": "<b>Waan qaadacay shirkadahan, laakiin sidee ayaynu u kordhin karnaa faa'iidada tan?</b><br>Intii aan ka shaqaynayey shirkad aan ka caawiyay in la geeyo xogta macluumaadka, waxaan ka fogaaday in aan geeyo ama isticmaalo <b>Oracle</b> si aan u hubiyo in aanan taageerin. Haddii uu qofku khalad yar sameeyo, wax buu ka bartaa; Inta aan gacan ama farsamo ku leeyahay shirkad kasta, waxaan isticmaalaa oo kaliya tignoolajiyada aan u hiilin kuwa daadinaya dhiigga walaalaheen, arsaaqadayduna waxay u sugnaatay Allaah.",
    "boycott_p3": "Alxamdullilah, maanta tignoolajiyad kastaa waxay haysataa beddelka xorta ah oo madax bannaan.. noloshan dagdaga ah ayaad ka baxaysaa (ee Alle ka cabso).",
    "cisco_title": "Cisco",
    "cisco_sub": "Kaabayaasha isku xidhka & Qalabka",
