    "ms_desc": "Mawqifka taariikhiga ah ee uu istaagay injineer software Ibtehal Abu Al-Saad oo ka soo horjeeda dhibka, oo uu caddaynayo:",
    "oracle_title": "Oracle",
    "oracle_sub": "Databases & Enterprise Cloud",
    "oracle_desc": "Diiwaangelinta dhibka shirkadaha, iyo u heellanaanta beddelka ilo-furan (sida PostgreSQL iyo MariaDB):",
    "boycott_tip": "<b>Talo ku socota kuwa lagu qasbay:</b> Haddii qof lagu qasbo inuu ka iibsado alaab hay'ad la qaadacay oo aan lahayn beddel kale, iibso <b>gacanta labaad / la isticmaalo</b> si shirkadu u hesho eber faa'iido cusub. Alxamdulilaah, isagaan talo saaranay.",
    "proj_small": "Portfolio",
    "proj_title": "🛠️ Mashaariicda Software-ka",
    "proj_desc": "Mashruuc dhab ah, oo dhammaystiran oo lagu daabacay GitHub - laga bilaabo nidaamyada maaraynta ganacsiga ilaa qalabka wax soo saarka miisaska iyo mobilada.",
    "grp_company": "🏢 Mashaariicda Shirkada Almajarah",
