    "grp_personal_cnt": "9 mashruuc",
    "casedesk_sub": "Nidaamka maaraynta tigidhada taageerada IT-Flutter Desktop",
    "casedesk_desc": "Nidaamka Miiska Caawinta oo dhameystiran oo loogu talagalay laamaha iyo shaqaalaha: Khadka tooska ah-isku-xirka daruuraha koowaad, dashboard-ka falanqaynta KPI ee is-dhexgalka, warbixinnada PDF/Excel ee Carabiga, tigidhka is-buuxinta smart, iyo ogeysiisyada WhatsApp.",
    "ratil_sub": "Tafaariiqda Pro → Odoo ERP xogta socdaalka",
    "ratil_desc": "La habeeyey oo la nadiifiyey <b>+715,463 diiwaanka macaamiisha</b> oo wata algorithms nadiifinta smart iyo habaynta barbar socota (Dart Isolates) iyada oo aan la qaboojin UI - 100% sax ah iyo 95% ka yar wakhtiga socdaalka gacanta.",
    "itsc_sub": "Madal qaybinta software gudaha ee shirkadaha",
    "itsc_desc": "App-ka ganacsiga ee qaybinta software la ansixiyay ee gudaha shabakada shirkada: soo dejinta maareeyaha horumarka tooska ah leh (Dio), ogaanshaha tooska ah ee cusbooneysiinta oo leh calaamad fiiqan, taageero Carabi/Ingiriisi iyo qaab mugdi ah (Qalabka 3).",
    "tpc_sub": "Fiidiyowga kala qaybsanaanta - Electron.js + FFmpeg",
    "tpc_desc": "App-ka Desktop-ka ee fiidiyoowga loo qaybiyo (1/2/3 daqiiqo ama kala badh) 100% tayo la'aan iyadoo loo sii marayo Stream Copy, oo leh ogaanshaha GPU toos ah iyo Glassmorphism UI oo casri ah. Ku shaqeeya Windows, Linux iyo macOS.",
    "ts_sub": "Tababaraha xawaaraha teeb - Electron.js",
    "ts_desc": "Tababaraha qorida iskutallaabta ah oo leh taageero buuxda oo RTL ah (Carabi/Cibraaniga/Faaris), WPM faahfaahsan iyo tirakoob sax ah, joojinta qasabka ah ee qaladka si loo dhiso xusuusta muruqa, gaabyada caalamiga ah iyo saxanka nidaamka.",
    "nui_sub": "Soosaaraha Android - Kotlin + Jetpack Compose",
    "nui_desc": "Soo saare Android casri ah oo leh qaab dhismeedka MVVM iyo Qolka DB: ku dhex dhisan Hijri/Gregorian kalandarka, qoraalada shaashadda guriga, kala soocida abka tooska ah, qashinka qashinka, iyo qarinta abka xasaasiga ah.",
    "r30_sub": "Mushaharka & maamulka miisaaniyada - Flutter",
    "r30_desc": "Smart Offline-Barnaamijka miisaaniyada koowaad: qaybinta tooska ah 50/30/20, miisaaniyad maalmeed firfircoon, caqabadaha kaydinta, qaybta samafalka, jaantusyada (fl_chart), iyo jadwalka maaliyadeed ee bilaha ah - lix goobood oo la taageeray.",
    "pomo_sub": "Saacadaha wax soo saarka Pomodoro - Flutter",
    "pomo_desc": "Maareynta fadhiga shaqada / nasashada ee farsamada Pomodoro: yoolalka maalinlaha ah iyo toddobaadlaha ah ee la beddeli karo, ogeysiisyada dhawaaqa, mowduucyo badan, iyo xirmooyinka Linux (Flatpak / .desktop) - waxay ku shaqeeyaan aaladaha 5.",
    "lm_sub": "Soosaaraha muuqaalka biyaha-biyoodka - Flutter + FFmpeg",
    "lm_desc": "Waxay soo saartaa fiidiyowyada MP4 oo leh calaamad qoraal ah oo firfircoon iyada oo aan wax fiidiyoow ah la gelin: Qoraal Carabi ah oo lagu sameeyay matoorka Flutter Canvas oo daacadnimo sare leh oo leh taageero cod-bixin buuxda, oo laga dhoofiyo FFmpeg Android iyo Windows.",
    "roms_small": "Nidaamyada Hawlaha",
    "roms_title": "🤖 Dhisida Android ROM-yada gaarka ah ee laga keenay Isha",
    "roms_desc": "AOSP ROM oo buuxa waxa uu ka dhisaa isha iyada oo la hagaajinayo kernel, habaynta geedaha aaladaha, iyo maaraynta blob iibiyaha.",
    "rom1_desc": "AOSP buuxa waxay ka dhisaysaa isha lakabka Evolution X, hagaajinta kernel-ka caadiga ah iyo geedka aaladda, hagaajinta HAL iyo habaynta kamarada, iyo khibrad Pixel ee qalabka Xiaomi.",
    "rom2_desc": "AOSP Android 16 waxay ka dhistaa isha oo leh astaamo Infinity X, hagaajinta geedaha kernel iyo aaladaha, iyo blob iibiyaha & maamulka HAL.",
    "rom3_desc": "PixelOS waxay ka dhistaa isha ay ka kooban tahay kernel-ka, habaynta geedaha aaladaha iyo soo saarista blob iibiyaha - khibrad Pixel oo nadiif ah oo ku saabsan qalabka Motorola.",
    "rom4_desc": "Vanilla waxay dhistaan ​​adeegyo Google la'aan ah (GApps) - waayo-aragnimo 100% AOSP saafi ah isla aaladda.",
    "rom4_tag3": "Ma jiro GApps",
    "rom5_desc": "Joogteynta iyo dhisida LineageOS 23.2 ROM-ka rasmiga ah ee Moto G54 5G - ROM deggan, miisaan-fudud leh oo leh cusboonaysiinta amniga joogtada ah.",
