    "haris_sub": "Shaandheynta Mawduuca YouTube & Fidinta Diirada-saarista - TypeScript + WXT",
    "haris_desc": "Isha furan, xog-ururinta-koowaad ee fidinta browserka kaaso u badala YouTube jawi waxbarasho oo nadiif ah, diirada saaraya oo leh kanaalka cadaynta, Shorts blocker, iyo qaab dhismeedka kowaad ee maxaliga ah ee taageeraya 40+ luqadood.",
    "miqyas_sub": "Astaanta App-ka nabdoon-soon istuudiyaha & maaweelada dukaanka - Flutter",
    "miqyas_desc": "Istuudiyaha is dhex galka ah ee horumariyayaashu si ay si sax ah u waafajiyaan astaanta abka gudaha 66×66 ee aagga nabdoon ee dhammaan aaladaha, oo muujinaya horudhac qalabyo badan oo toos ah iyo soosaaraha shaashadda dukaanka Google Play iyo App Store.",
    "mufarrigh_sub": "Soosaaraha xaashida Sprite & ka saarida asalka - Flutter + Dart Vision",
    "mufarrigh_desc": "Miiska casriga ah & aaladda mobilada si loo jeexjeexo xaashida sprite oo meesha looga saaro asalka iyadoo la adeegsanayo matoor-Dart saafi ah, BFS Flood-Fill, iyo nabaadguurka faraqa ee leh 3-pane UI iyo dhoofinta dufcaddii.",
    "tips_small": "Tilmaamo, aragtiyo & xalal",
    "tips_title": "💡 Talooyin Farsamo & Xal",
    "tips_desc": "Tilmaamo wax ku ool ah, aragtiyaha cilad-raadinta, iyo aaladaha otomaatiga ah ee la helay intii lagu jiray horumarinta iyo nidaamka maamulka.",
    "tip1_badge": "Digniin Dhis Flutter & Hagaajin",
    "tip1_title": "Sax isticmaalka Gradle ee fidinta Java si looga hortago isku dhacyada nooca",
    "tip1_desc": "Markaad awood u siiso <b>Gradle for Java</b> kordhinta IDE gaaga (VS Code / Antigravity), haddii mashruucaaga <b>Flutter</b> ka kooban yahay noocyo badan oo Gradle ah ama qaybo, kordhintu waxay isku daydaa inay ogaato oo mid walba si madaxbanaan u dhisto. Tani waxay kicin kartaa khaladaadka is-bar-barashada nooca (tusaale <code>Nooca Gradle ee ugu yar ee la taageeray waa 9.6.0. Nooca hadda jira waa 9.4.0</code>) oo wuxuu keenaa guuldarrooyin dhismo. Habka lagu taliyay waa in lagu balaadhiyo fidinta goobaha shaqada ee la taageeray ama la curyaamiyo daahfurka mashruuca qoto dheer ee tooska ah ee buug-hoosaadka Flutter.",
    "tip2_badge": "Qalabka Automation Linux",
    "tip2_sub": "Qalabka otomaatiga Linux - Bash + Arch Linux",
    "tip2_title": "Rakibaadaha Flutter ee Arch Linux - Dejinta SDK Automated",
    "tip2_desc": "Qoraalka Bash oo otomaatig u ah rakibidda Flutter SDK-kii ugu dambeeyay ee Arch Linux: si toos ah u soo saarta sii deynta cusub ee isha rasmiga ah, waxay dejisaa doorsoomayaasha deegaanka ee saddexda qolof (Bash, Zsh, iyo Fish), oo dejinaya OpenJDK-gii ugu dambeeyay iyada oo loo sii marayo <code>archlinux-java </code>hal tallaabo.",
