    "name_ar": "Hossam Hassan Majrashi",
    "role": "Kwararre na hanyar sadarwa • Flutter & Mai Haɓaka App na Electron • Tallafin IT & Tsarin",
    "lead": "Ina gina ainihin hanyoyin magance software da ake amfani da su yau da kullun a cikin wuraren aiki: tsarin sarrafa tikiti, manyan kayan aikin sarrafa bayanai (+715K records), aikace-aikacen samarwa, da cikakken Android ROM yana ginawa daga tushe. Na juya matsalolin fasaha zuwa kayan aikin software masu inganci.",
    "cta_projects": "🚀 Duba ayyukana",
