    "exp_small": "Gwanintan aiki",
    "exp_title": "💼 Aiki na yanzu",
    "exp1_title": "Tallafin IT / Mataimakin Tsarin - Tallafin IT & Mataimakin Tsarin",
    "exp1_co": "Kamfanin Almajarah",
    "exp1_period": "Fabrairu 2026 - Agusta 2026",
    "exp1_li1": "An ƙirƙira da haɓaka <b>CaseDesk</b>, tsarin kula da tikitin tallafi don rassa da ma'aikata - Tsarin gine-gine na kan layi-First tare da bayanan bayanai biyu (Hive + girgije ta gida ta PHP REST APIs).",
    "exp1_li2": "Ƙirƙirar <b>Cibiyar Software na IT</b> ƙa'idar don rarraba ingantaccen software a cikin hanyar sadarwar kamfani tare da gano sabuntawa ta atomatik da mai sarrafa zazzagewa mai wayo.",
    "exp1_li3": "An gina <b>RatilConvert</b>, wanda aka sarrafa da kuma tsaftace <b>+715,463 bayanan abokin ciniki</b> daga Retail Pro kuma ya fitar da su tare da dacewa 100% zuwa Odoo ERP - yanke lokacin ƙaura na hannu da kashi 95%.",
    "exp1_li4": "Ƙaddamar da zane na cibiyar sadarwar jiki ta kamfanin ta amfani da draw.io, ciki har da rarraba uwar garke, Firewall, maɓallin mahimmanci, da maɓallai na sashen, tare da cikakkun takardun hanyar sadarwa.",
    "exp1_li5": "Ayyukan kulawa da kayan masarufi, an bincika KPIs ta hanyar dashboards, da kuma samar da ƙwararrun rahoton Larabci PDF/Excel.",
    "exp1_intro": "A lokacin da nake a kamfanin, na haɓaka cikakken tsarin software da ake amfani da su yau da kullum ta hanyar rassan da ma'aikata: tsarin kula da tikitin tallafi, tsarin rarraba software na ciki, da kuma babban kayan aiki na sarrafa bayanai & ƙaura - tare da tsarawa da kuma tattara kayan aikin cibiyar sadarwa da kula da kulawa & ayyuka na hardware.",
    "boycott_title": "🕊️ Kauracewa Fasaha",
    "boycott_sub": "Ƙarfafa Ƙa'idar & Matsayi Mai Imani",
    "boycott_badge": "Ka'ida & Matsayi",
    "boycott_p1": "A matsayina na kwararre a harkar sadarwa, na kauracewa <b>Cisco</b> saboda tsananin hadin kai da goyon bayansu ga masu kashe annabawa da azzalumai. Duk da riƙe takaddun shaida daga Cisco, na yi watsi da su da farin ciki saboda Allah. Duk wanda ya cutar da ’yan uwana Musulmi, zan barranta ko da biyan bukatuna ne – domin arzikinmu ya tabbata ga Allah, Mawadaci, Abin godiya.",
    "boycott_p2": "<b>Na kauracewa wadannan kamfanoni, amma ta yaya za mu kara amfana daga wannan?</b><br>Lokacin da nake aiki a kamfani inda na taimaka wajen tura bayanan bayanai, na guji tura ko amfani da <b>Oracle</b> don tabbatar da rashin tallafa musu. Idan mutum ya yi dan kuskure kadan sai ya koyi darasi; Matukar ina da hannu ko fasaha a kowane kamfani, ina amfani ne kawai da fasahar da ba za ta tallafa wa masu zubar da jinin 'yan uwanmu ba, kuma arziki na ya tabbata ga Allah.",
    "boycott_p3": "Kuma godiya ta tabbata ga Allah, a yau kowace fasaha tana da zabin 'yanci da zaman kanta.. kuma daga wannan rayuwa mai gushewa za ku fita (don haka ku ji tsoron Allah).",
