    "ratil_sub": "Retail Pro → Odoo ERP bayanan ƙaura",
    "ratil_desc": "An sarrafa kuma an tsaftace <b>+715,463 bayanan abokin ciniki</b> tare da tsaftataccen algorithms da sarrafa layi daya (Dart Isolates) ba tare da daskare UI ba - 100% daidaito da 95% ƙasa da lokacin ƙaura na hannu.",
    "itsc_sub": "Dandalin rarraba software na ciki don kamfanoni",
    "itsc_desc": "Aikace-aikacen kasuwanci don rarraba ingantaccen software a cikin hanyar sadarwar kamfani: mai sarrafa saukarwa tare da ci gaba kai tsaye (Dio), gano sabuntawa ta atomatik tare da lamba mai rai, tallafin Larabci / Ingilishi da yanayin duhu (Material 3).",
    "tpc_sub": "Rarraba bidiyo - Electron.js + FFmpeg",
    "tpc_desc": "Aikace-aikacen Desktop don raba bidiyo (minti 1/2/3 ko rabi) a 100% rashin inganci ta hanyar kwafin Stream, tare da gano GPU ta atomatik da UI na Glassmorphism na zamani. Yana aiki akan Windows, Linux da macOS.",
    "ts_sub": "Mai horar da saurin bugawa - Electron.js",
    "ts_desc": "Mai ba da horo na buga dandamali tare da cikakken tallafin RTL (Larabci / Ibrananci / Farisa), cikakken WPM da ƙididdiga daidaito, tilasta tsayawa kan kuskure don gina ƙwaƙwalwar tsoka, gajerun hanyoyin duniya da tiren tsarin.",
    "nui_sub": "Mai ƙaddamar da Android - Kotlin + Jetpack Compose",
    "nui_desc": "Mai ƙaddamar da Android na zamani tare da gine-ginen MVVM da ɗakin DB: ginanniyar kalandar Hijri/Gregorian, bayanin kula na allo, rarraba aikace-aikacen atomatik, kwandon shara, da ɓoye ƙa'idodi masu mahimmanci.",
    "r30_sub": "Albashi & Gudanar da kasafin kuɗi - Flutter",
    "r30_desc": "Smart Offline-Kafin kasafin kuɗi na farko: rarraba 50/30/20 atomatik, kasafin kuɗi na yau da kullun, ƙalubalen tanadi, sashin sadaka, sigogi (fl_chart), da kalanda na kuɗi na wata-wata - dandamali masu tallafi shida.",
    "pomo_sub": "Pomodoro mai ƙididdige ƙima - Flutter",
    "pomo_desc": "Gudanar da zaman aiki / hutu tare da fasaha na Pomodoro: wanda za'a iya daidaitawa yau da kullun da burin mako-mako, faɗakarwar sauti, jigogi da yawa, da fakitin Linux (Flatpak / .desktop) - yana gudana akan dandamali na 5.",
    "lm_sub": "Generator bidiyo mai alamar ruwa - Flutter + FFmpeg",
    "lm_desc": "Yana haifar da bidiyo na MP4 tare da alamar ruwa mai rairayi ba tare da kowane bidiyon shigar da shi ba: Rubutun Larabci da aka yi tare da injin Flutter Canvas a babban aminci tare da cikakken tallafin diacritic, fitarwa ta FFmpeg akan Android da Windows.",
    "roms_small": "Tsarukan Aiki",
    "roms_title": "🤖 Gina Custom Android ROMs daga Tushen",
    "roms_desc": "Cikakken AOSP ROM yana ginawa daga tushe tare da gyaran kernel, saitin bishiyar na'ura, da sarrafa kullin mai siyarwa.",
    "rom1_desc": "Cikakken ginawa na AOSP daga tushe tare da Layer Evolution X, gyaran kernel na al'ada da bishiyar na'ura, gyaran HAL da saitin kyamara, da ƙwarewar Pixel akan kayan aikin Xiaomi.",
    "rom2_desc": "AOSP Android 16 yana ginawa daga tushe tare da fasalin Infinity X, kernel da gyaran bishiyar na'ura, da mai siyarwa & sarrafa HAL.",
    "rom3_desc": "PixelOS yana ginawa daga tushe tare da tarin kwaya, saitin bishiyar na'ura da cirewar mai siyarwa - gogewar Pixel mai tsabta akan kayan aikin Motorola.",
    "rom4_desc": "Gina Vanilla ba tare da sabis na Google ba (GApps) - ƙwarewar AOSP mai tsabta 100% akan na'urar iri ɗaya.",
