    "miqyas_sub": "App icon safe-zone studio & store ba'a - Flutter",
    "miqyas_desc": "Studio mai mu'amala don masu haɓakawa don daidaita gumakan app daidai a cikin yankin aminci na 66 × 66 a duk faɗin duk dandamali, yana nuna samfoti na izgili na na'urori da yawa da janareta na hoto mai sarrafa kansa don Google Play da Store Store.",
    "mufarrigh_sub": "Mai cire takarda Sprite & mai cire bango - Flutter + Dart Vision",
    "mufarrigh_desc": "Smart tebur & kayan aiki ta hannu don yanki zanen gadon sprite da cire bango ta amfani da injin-Dart mai tsafta, Cika Ambaliyar BFS, da yashewar gibi tare da 3-pane UI mai daidaitawa da fitar da tsari.",
