    "tips_desc": "Jagorori masu amfani, abubuwan gano matsala, da kayan aikin sarrafa kansa da aka samu yayin haɓakawa da sarrafa tsarin.",
    "tip1_badge": "Gargadi Gina Flutter & Gyara",
    "tip1_title": "Daidaita amfani da Gradle don haɓaka Java don hana rikice-rikicen sigar",
    "tip1_desc": "Lokacin kunna tsawo <b>Gradle don Java</b> a cikin IDE ɗinku (VS Code / Antigravity), idan aikin <b>Flutter</b> ɗinku ya ƙunshi nau'ikan Gradle da yawa ko kayayyaki, haɓaka yana ƙoƙarin ganowa da gina kowane ɗayan kansa. Wannan na iya haifar da kurakuran rashin daidaituwa na sigar (misali <code>Sigar Gradle mafi ƙarancin tallafi shine 9.6.0. Sigar na yanzu shine 9.4.0</code>) kuma yana haifar da gazawar ginin. Hanyar da aka ba da shawarar ita ce keɓance tsawaita zuwa wuraren aiki masu goyan baya ko kuma hana gano zurfin aikin atomatik don ƙananan kundiyoyin Flutter.",
