    "tip2_title": "Mai sakawa Flutter don Arch Linux - Saitin SDK Mai sarrafa kansa",
    "tip2_desc": "Rubutun Bash wanda ke sarrafa shigar da ingantaccen Flutter SDK akan Arch Linux: yana ɗaukar sabon sabon saki ta atomatik daga tushen hukuma, yana daidaita masu canjin yanayi a cikin harsashi uku (Bash, Zsh, da Kifi), kuma ya saita sabon OpenJDK azaman tsoho ta hanyar <code>archlinux-java</code>a mataki ɗaya.",
