    "exp1_li1": "Iliyoundwa na kutengenezwa <b>CaseDesk</b>, mfumo wa usaidizi wa usimamizi wa tikiti kwa matawi na wafanyikazi - Usanifu wa Nje ya Mtandao wa Kwanza wenye hifadhidata mbili (Hive + wingu la ndani kupitia API za PHP REST).",
    "exp1_li2": "Imetengeneza programu ya <b>Kituo cha Programu cha IT</b> ili kusambaza programu iliyoidhinishwa ndani ya mtandao wa kampuni yenye utambuzi wa sasisho otomatiki na kidhibiti mahiri cha upakuaji.",
