    "exp1_li4": "Ilibuni mchoro wa mtandao halisi wa kampuni kwa kutumia draw.io, ikijumuisha usambazaji wa seva, ngome, swichi ya msingi na swichi za idara, pamoja na hati kamili za mtandao.",
    "exp1_li5": "Ilishughulikia kazi za urekebishaji na maunzi, ilichanganua KPIs kupitia dashibodi shirikishi, na kutoa ripoti za kitaalamu za Kiarabu za PDF/Excel.",
    "exp1_intro": "Wakati nikiwa kwenye kampuni, nilitengeneza mifumo kamili ya programu inayotumiwa kila siku na matawi na wafanyikazi: mfumo wa usaidizi wa usimamizi wa tikiti, jukwaa la usambazaji wa programu ya ndani, na zana kubwa ya kuchakata na kuhamisha data - kando ya kubuni na kuweka kumbukumbu za miundombinu ya mtandao na kushughulikia matengenezo na kazi za maunzi.",
    "boycott_title": "🕊️ Kususia kiufundi",
    "boycott_sub": "Kanuni Imara & Msimamo Unaotegemea Imani",
    "boycott_badge": "Kanuni na Msimamo",
    "boycott_p1": "Kama <b> mtaalamu wa mtandao</b>, ninasusia <b>Cisco</b> kwa sababu ya ushirikiano wao wa kina na usaidizi kwa wauaji wa manabii na wakandamizaji. Licha ya kushikilia sifa zilizoidhinishwa kutoka kwa Cisco, ninafurahi kuzikana kwa ajili ya Mwenyezi Mungu. Mwenye kuwadhulumu ndugu zangu Waislamu, mimi nitamkataa hata kwa kugharimu maslahi yangu binafsi - kwani riziki yetu iko kwa Mwenyezi Mungu, Mwenye kujitosha, Mwenye kusifiwa.",
    "boycott_p2": "<b>Nimesusia mashirika haya, lakini tutanufaika vipi kutokana na hili?</b><br>Nilipokuwa nikifanya kazi katika kampuni ambayo nilisaidia kusambaza hifadhidata, niliepuka kupeleka au kutumia <b>Oracle</b> ili kuhakikisha kuwa siyaungi mkono. Ikiwa mtu atafanya kosa kidogo, anajifunza kutoka kwake; maadamu nina mkono au ushawishi wa kiufundi katika kampuni yoyote, mimi hutumia tu teknolojia ambazo haziungi mkono wale wanaomwaga damu ya ndugu zetu, na riziki yangu iko kwa Mwenyezi Mungu.",
    "boycott_p3": "Na sifa njema ni za Mwenyezi Mungu, leo kila teknolojia ina mbadala huru na huru.",
