    "tip1_badge": "Onyo la Kujenga Flutter & Rekebisha",
    "tip1_title": "Matumizi sahihi ya Gradle kwa kiendelezi cha Java ili kuzuia migongano ya matoleo",
    "tip1_desc": "Unapowasha kiendelezi cha <b>Gradle for Java</b> katika IDE yako (VS Code / Antigravity), ikiwa mradi wako wa <b>Flutter</b> una matoleo au moduli nyingi za Gradle, kiendelezi hujaribu kugundua na kuunda kila moja kivyake. Hii inaweza kusababisha hitilafu za kutolingana kwa toleo (k.m. <code>Toleo la chini kabisa linalotumika Gradle ni 9.6.0. Toleo la sasa ni 9.4.0</code>) na kusababisha kushindwa kwa muundo. Mbinu inayopendekezwa ni kuongeza kiendelezi kwa nafasi za kazi zinazotumika au kuzima ugunduzi wa kina kiotomatiki wa mradi kwa saraka ndogo za Flutter.",
    "tip2_badge": "Zana ya Uendeshaji ya Linux",
