    "boycott_p2": "<b>Mən bu korporasiyaları boykot edirəm, lakin biz bundan maksimum fayda necə əldə edə bilərik?</b><br>Məlumat bazalarının yerləşdirilməsinə kömək etdiyim şirkətdə işləyərkən, onları dəstəkləməmək üçün <b>Oracle</b> tətbiq etməkdən və ya istifadə etməkdən qaçdım. Biri cüzi bir səhv etsə, ondan dərs çıxar; nə qədər ki, hər hansı firmada əlim və ya texniki təsirim var, mən ancaq qardaşlarımızın qanını tökənlərə dəstək verməyən texnologiyalardan istifadə edirəm və mənim ruzim Allah üzərindədir.",
