    "exp1_li1": "Dizayn va ishlab chiqilgan <b>CaseDesk</b>, filiallar va xodimlar uchun chiptalarni boshqarish tizimini qo'llab-quvvatlash — Ikkilamchi ma'lumotlar bazasiga ega Offline-First arxitekturasi (PHP REST API orqali mahalliy Hive + bulut).",
    "exp1_li2": "Yangilanishlarni avtomatik aniqlash va aqlli yuklab olish menejeri bilan kompaniya tarmog'ida tasdiqlangan dasturiy ta'minotni tarqatish uchun <b>IT dasturiy ta'minot markazi</b> ilovasi ishlab chiqildi.",
    "exp1_li3": "Retail Pro-dan <b>+715 463 mijoz yozuvlarini</b> qayta ishlagan va tozalagan <b>RatilConvert</b> qurilgan va ularni Odoo ERP ga 100% moslik bilan eksport qilgan — qo‘lda ko‘chirish vaqtini 95% ga qisqartirgan.",
    "exp1_li4": "Dra.io yordamida kompaniyaning jismoniy tarmoq diagrammasini ishlab chiqdi, jumladan server taqsimoti, xavfsizlik devori, asosiy kalit va bo'lim kalitlari, to'liq tarmoq hujjatlari bilan.",
    "exp1_li5": "Texnik xizmat ko'rsatish va apparat vazifalarini bajardi, interaktiv boshqaruv paneli orqali KPI tahlil qildi va professional arabcha PDF/Excel hisobotlarini yaratdi.",
    "exp1_intro": "Kompaniyadagi faoliyatim davomida men filiallar va xodimlar tomonidan har kuni qo‘llaniladigan to‘liq dasturiy ta’minot tizimlarini ishlab chiqdim: qo‘llab-quvvatlash chiptalarini boshqarish tizimi, ichki dasturiy ta’minotni tarqatish platformasi va katta ma’lumotlarni qayta ishlash va ko‘chirish vositasi – tarmoq infratuzilmasini loyihalash va hujjatlashtirish hamda texnik xizmat ko‘rsatish va apparat vazifalarini bajarish bilan bir qatorda.",
    "boycott_title": "🕊️ Texnik boykot",
