    "boycott_badge": "Prinsip va pozitsiya",
    "boycott_p1": "<b>tarmoq mutaxassisi</b> sifatida, men Cisco</b>ni ularning chuqur sherikligi va payg'ambarlar va zolimlarning qotillarini qo'llab-quvvatlagani uchun boykot qilaman. Cisco tomonidan tasdiqlangan ishonchnomaga ega bo'lishimga qaramay, men Alloh uchun ulardan mamnuniyat bilan voz kechaman. Kim musulmon birodarlarimga yomonlik qilsa, men o'zimning shaxsiy manfaatim hisobiga ham undan voz kechaman, chunki bizning rizqimiz o'zi befoyda va maqtovga loyiq Allohning zimmasidadir.",
    "boycott_p2": "<b>Men bu korporatsiyalarga boykot qilaman, lekin bundan qanday qilib maksimal foyda olamiz?</b><br>Maʼlumotlar bazalarini joylashtirishga yordam bergan kompaniyada ishlaganimda, ularni qoʻllab-quvvatlamaslik uchun <b>Oracle</b>ni joylashtirishdan yoki undan foydalanishdan qochdim. Agar kimdir ozgina xato qilsa, undan saboq oladi; har qanday firmada qoʻlim yoki texnik taʼsirim bor ekan, men faqat birodarlarimizning qonini toʻkayotganlarni qoʻllab-quvvatlamaydigan texnologiyalardan foydalanaman, mening rizqim esa Allohgadir.",
    "boycott_p3": "Allohga hamdlar bo'lsinki, bugungi kunda har bir texnologiyaning erkin va mustaqil muqobili bor.. va siz bu o'tkinchi hayotdan ketasiz (Allohdan qo'rqing).",
