    "ratil_sub": "Chakana savdo Pro → Odoo ERP ma'lumotlarini ko'chirish",
    "ratil_desc": "Aqlli tozalash algoritmlari va parallel ishlov berish (Dart Isolates) bilan <b>+715 463 ta mijoz yozuvi</b> qayta ishlangan va tozalangan — 100% aniqlik va 95% kamroq qo‘lda ko‘chirish vaqti.",
    "itsc_sub": "Korxonalar uchun ichki dasturiy ta'minotni tarqatish platformasi",
    "itsc_desc": "Tasdiqlangan dasturiy ta'minotni kompaniya tarmog'i ichida tarqatish uchun korporativ ilova: jonli progress bilan yuklab olish menejeri (Dio), animatsiya nishoni bilan avtomatik yangilanishni aniqlash, arabcha/inglizcha qo'llab-quvvatlash va qorong'u rejim (3-material).",
    "tpc_sub": "Videoni ajratish — Electron.js + FFmpeg",
    "tpc_desc": "Stream Copy orqali videolarni (1/2/3 daqiqa yoki yarmini) 100% yoʻqotishsiz sifatda, avtomatik GPU aniqlash va zamonaviy Glassmorphism UI bilan ajratish uchun ish stoli ilovasi. Windows, Linux va macOS tizimlarida ishlaydi.",
    "ts_sub": "Yozish tezligi treneri — Electron.js",
    "ts_desc": "To'liq RTL qo'llab-quvvatlashi (arabcha/ibroniycha/forscha), batafsil WPM va aniqlik statistikasi, mushak xotirasini yaratish uchun xatoni majburiy to'xtatish, global yorliqlar va tizim tepsisi bilan o'zaro platformali yozish treneri.",
    "nui_sub": "Android ishga tushirgichi — Kotlin + Jetpack Compose",
    "nui_desc": "MVVM arxitekturasi va Room DB bilan zamonaviy Android ishga tushirgichi: oʻrnatilgan hijriy/grigoriy taqvimi, uy ekranidagi qaydlar, ilovalarni avtomatik turkumlashtirish, axlat qutisi va nozik ilovalarni yashirish.",
    "r30_sub": "Ish haqi va byudjetni boshqarish - Flutter",
    "r30_desc": "Smart Offline-First byudjet ilovasi: avtomatik 50/30/20 taqsimoti, dinamik kundalik byudjet, tejash muammolari, xayriya bo'limi, jadvallar (fl_chart) va oylik moliyaviy taqvim - oltita qo'llab-quvvatlanadigan platformalar.",
    "pomo_sub": "Pomodoro unumdorligi taymer - Flutter",
    "pomo_desc": "Pomodoro texnikasi bilan ish/tanaffus sessiyasini boshqarish: sozlanishi mumkin bo'lgan kundalik va haftalik maqsadlar, ovozli ogohlantirishlar, bir nechta mavzular va Linux paketlari (Flatpak / .desktop) — 5 ta platformada ishlaydi.",
    "lm_sub": "Suv belgisi video generatori - Flutter + FFmpeg",
    "lm_desc": "Hech qanday video kiritishsiz jonlantirilgan matnli moybo'yoqli MP4 videolarni yaratadi: Flutter Canvas dvigateli yordamida yuqori aniqlikdagi arabcha matn to'liq diakritik qo'llab-quvvatlanadi, Android va Windows tizimlarida FFmpeg orqali eksport qilinadi.",
    "roms_small": "Operatsion tizimlar",
    "roms_title": "🤖 Manbadan maxsus Android ROM-larni yaratish",
    "roms_desc": "To'liq AOSP ROM yadroni sozlash, qurilma daraxtini sozlash va sotuvchi bloklarini boshqarish bilan manbadan quriladi.",
    "rom1_desc": "Evolution X qatlami, maxsus yadro sozlash va qurilma daraxti, HAL tuzatishlari va kamerani sozlash va Xiaomi uskunasida Pixel tajribasi bilan manbadan toʻliq AOSP tuziladi.",
    "rom2_desc": "AOSP Android 16 manbadan Infinity X xususiyatlari, yadro va qurilma daraxtini sozlash, sotuvchi blob va HAL boshqaruvi bilan yaratilgan.",
    "rom3_desc": "PixelOS yadro kompilyatsiyasi, qurilma daraxtini sozlash va sotuvchi bloblarini ajratib olish bilan manbadan qurilgan — Motorola apparatida toza Pixel tajribasi.",
    "rom4_desc": "Vanilla Google xizmatlarisiz (GApps) yaratish — xuddi shu qurilmada 100% sof AOSP tajribasi.",
