    "miqyas_sub": "Ilova belgisi xavfsiz zona studiyasi va doʻkon maketlari — Flutter",
    "miqyas_desc": "Dasturchilar uchun barcha platformalarda 66×66 xavfsiz zonada ilova piktogrammalarini toʻgʻri tekislash uchun interaktiv studiya, Google Play va App Store uchun jonli koʻp qurilma maketini oldindan koʻrish va avtomatlashtirilgan doʻkon skrinshoti generatorini oʻz ichiga oladi.",
