    "mufarrigh_desc": "Sof Dart dvigateli, BFS Flood-Fill va adaptiv 3 panelli UI va ommaviy eksport bilan bo‘shliq eroziyasi yordamida sprite varaqlarini kesish va fonni olib tashlash uchun aqlli ish stoli va mobil vosita.",
    "tips_small": "Qo'llanmalar, tushunchalar va echimlar",
    "tips_title": "💡 Texnik maslahatlar va yechimlar",
    "tips_desc": "Amaliy qo'llanmalar, muammolarni bartaraf etish bo'yicha tushunchalar va ishlab chiqish va tizimlarni boshqarish jarayonida olingan avtomatlashtirish vositalari.",
    "tip1_badge": "Flutter Build ogohlantirish va tuzatish",
    "tip1_title": "Versiya ziddiyatlarini oldini olish uchun Java kengaytmasi uchun Gradle-dan to'g'ri foydalanish",
    "tip1_desc": "IDE-da <b>Java uchun Gradle</b> kengaytmasi yoqilganda (VS Code / Antigravity), agar sizning <b>Flutter</b> loyihangizda bir nechta Gradle versiyalari yoki modullari boʻlsa, kengaytma har birini mustaqil ravishda topishga va yaratishga harakat qiladi. Bu versiyaning mos kelmasligi xatolarini keltirib chiqarishi mumkin (masalan, <code>Minimal qoʻllab-quvvatlanadigan Gradle versiyasi 9.6.0. Joriy versiya 9.4.0</code>) va tuzilishdagi nosozliklarga olib kelishi mumkin. Tavsiya etilgan yondashuv qo'llab-quvvatlanadigan ish joylariga kengaytmani kengaytirish yoki Flutter kichik kataloglari uchun avtomatik chuqur loyihani ochishni o'chirishdir.",
    "tip2_badge": "Linuxni avtomatlashtirish vositasi",
    "tip2_sub": "Linuxni avtomatlashtirish vositasi - Bash + Arch Linux",
    "tip2_title": "Arch Linux uchun Flutter o'rnatuvchisi - Avtomatlashtirilgan SDK-ni sozlash",
    "tip2_desc": "Arch Linux-da so'nggi barqaror Flutter SDK-ni o'rnatishni avtomatlashtiradigan Bash skripti: rasmiy manbadan avtomatik ravishda eng yangi versiyani oladi, uchta qobiq (Bash, Zsh va Fish) bo'ylab muhit o'zgaruvchilarini sozlaydi va bir qadamda <code>archlinux-java</code> orqali eng so'nggi OpenJDK-ni sukut bo'yicha o'rnatadi.",
