    "exp1_li1": "Жобаланған және әзірленген <b>CaseDesk</b>, филиалдар мен қызметкерлерге арналған қолдау билеттерін басқару жүйесі — қос дерекқоры бар Offline-First архитектурасы (PHP REST API арқылы жергілікті Hive + бұлт).",
    "exp1_li2": "Жаңартуларды автоматты түрде анықтау және смарт жүктеу менеджері бар компания желісінің ішінде бекітілген бағдарламалық құралды тарату үшін <b>IT бағдарламалық қамтамасыз ету орталығы</b> қолданбасы әзірленді.",
    "exp1_li3": "Құрылған <b>RatilConvert</b>, ол Retail Pro-дан <b>+715 463 тұтынушы жазбасын</b> өңдеп, тазалады және оларды Odoo ERP жүйесіне 100% үйлесімділікпен экспорттады — қолмен тасымалдау уақытын 95%-ға қысқартты.",
    "exp1_li4": "Толық желі құжаттамасы бар серверді тарату, брандмауэр, негізгі қосқыш және бөлім қосқыштарын қоса, draw.io арқылы компанияның физикалық желі диаграммасын жасады.",
    "exp1_li5": "Техникалық қызмет көрсету және аппараттық құралдар тапсырмаларын орындады, интерактивті бақылау тақталары арқылы KPI талдады және кәсіби арабша PDF/Excel есептерін жасады.",
    "exp1_intro": "Компанияда жұмыс істеген уақытымда мен филиалдар мен қызметкерлер күнделікті қолданатын толық бағдарламалық жүйелерді әзірледім: қолдау билеттерін басқару жүйесі, ішкі бағдарламалық құралды тарату платформасы және үлкен деректерді өңдеу және тасымалдау құралы — желілік инфрақұрылымды жобалау және құжаттау, техникалық қызмет көрсету және аппараттық құралдар тапсырмаларын өңдеумен қатар.",
