    "boycott_sub": "Қатты қағида және сенімге негізделген ұстаным",
    "boycott_badge": "Принцип және ұстаным",
    "boycott_p1": "<b>желі маманы</b> ретінде мен <b>Cisco</b>-ға олардың терең қатысы бар және пайғамбарлар мен залымдарды өлтірушілерге қолдау көрсеткені үшін бойкот жарияладым. Cisco компаниясының сертификаты бар болса да, Алла разылығы үшін олардан қуана бас тартамын. Кімде-кім мұсылман бауырларыма зиян тигізсе, мен өз мүддем үшін болса да одан бас тартамын, өйткені біздің ризық-несібеміз – Ешкім, Мақтауға лайық Аллаға тән.",
