    "tip1_desc": "IDE жүйесінде <b>Gradle for Java</b> кеңейтімін қосқанда (VS Code / Antigravity), егер <b>Flutter</b> жобаңызда бірнеше Gradle нұсқалары немесе модульдері болса, кеңейтім әрқайсысын дербес ашуға және құруға әрекет жасайды. Бұл нұсқаның сәйкес келмеуі қателерін тудыруы мүмкін (мысалы: <code>Қолдау көрсетілетін ең аз Gradle нұсқасы - 9.6.0. Ағымдағы нұсқа - 9.4.0</code>) және құрастыру сәтсіздігін тудыруы мүмкін. Ұсынылған тәсіл - қолдау көрсетілетін жұмыс кеңістігіне кеңейтуді анықтау немесе Flutter ішкі каталогтары үшін автоматты терең жобаны табуды өшіру.",
