    "exp1_li3": "Курулган <b>RatilConvert</b>, ал Retail Pro'дон <b>+715,463 кардар жазууларын</b> иштетип, тазалап, аларды Odoo ERPге 100% шайкештик менен экспорттогон — кол менен көчүрүү убактысын 95% кыскартты.",
    "exp1_li4": "Компаниянын физикалык тармак диаграммасын draw.io аркылуу, анын ичинде серверди бөлүштүрүү, брандмауэр, негизги коммутатор жана бөлүмдөрдүн коммутаторлору, толук тармак документтери менен иштелип чыккан.",
    "exp1_li5": "Тейлөө жана аппараттык камсыздоо тапшырмаларын аткарды, интерактивдүү панелдер аркылуу KPIлерди талдады жана кесиптик арабча PDF/Excel отчетторун түздү.",
    "exp1_intro": "Компанияда иштеген убакта мен филиалдар жана кызматкерлер тарабынан күн сайын колдонулуучу толук программалык системаларды иштеп чыктым: колдоо билеттерин башкаруу тутуму, ички программалык камсыздоону бөлүштүрүү платформасы жана чоң маалыматтарды иштетүү жана миграция куралы — тармактык инфраструктураны долбоорлоо жана документтештирүү жана техникалык тейлөө жана аппараттык тапшырмаларды аткаруу менен бирге.",
    "boycott_title": "🕊️ Техникалык бойкот",
