    "boycott_badge": "Принцип жана позиция",
    "boycott_p1": "<b>тармак адиси</b> катары мен <b>Cisco</b>га алардын терең шериктештигинен жана пайгамбарларды жана залимдерди өлтүрүүчүлөрдү колдогондугу үчүн бойкот кылам. Cisco компаниясынын сертификаттары бар экенине карабай, Алланын ыраазычылыгы үчүн алардан баш тартам. Кимде-ким мусулман бир туугандарыма жамандык кылса, мен өзүмдүн жеке кызыкчылыгым үчүн болсо да андан баш тартам, анткени биздин ырыскыбыз Зат Зат, Мактоого татыктуу Аллахка таандык.",
    "boycott_p2": "<b>Мен бул корпорацияларга бойкот кылам, бирок мындан кантип максималдуу пайда алабыз?</b><br>Мен маалымат базаларын жайылтууга жардам берген компанияда иштеп жүргөндө, аларды колдоого албаш үчүн <b>Oracle</b>ди жайылтуудан же колдонуудан качтым. Кимдир бирөө кичине ката кетирсе, андан сабак алат; кандайдыр бир фирмада колум же техникалык таасири бар болсо, мен бир туугандарыбыздын канын төккөндөрдү колдобогон технологияларды гана колдоном жана менин ырыскым Аллага таандык.",
    "boycott_p3": "Аллахка чексиз мактоолор болсун, бүгүнкү күндө ар бир технологиянын эркин жана өз алдынча альтернативасы бар.. жана силер бул өткүр жашоодон кетесиңер (Аллахтан корккула).",
