    "oracle_title": "Oracle",
    "oracle_sub": "Маалымат базалары жана Enterprise Cloud",
    "oracle_desc": "Корпоративдик шериктикти документтештирүү жана ачык булактуу альтернативаларды колдонуу (мисалы, PostgreSQL жана MariaDB):",
    "boycott_tip": "<b>Мажбурлангандар үчүн кеңеш:</b> Эгерде кимдир-бирөө бойкотко кабылган уюмдан альтернатива жок товарды сатып алууга аргасыз болсо, аны <b>экинчи колдо / колдонулган</b> сатып алыңыз, ошондо компания жаңы пайдага нөлгө жетет. Аллахка мактоолор болсун жана Ага тобокел кылабыз.",
