    "proj_title": "🛠️ Программалык камсыздоо долбоорлору",
    "proj_desc": "GitHub сайтында жарыяланган реалдуу, аяктаган долбоорлор — ишкананы башкаруу тутумдарынан баштап, иш такта жана мобилдик өндүрүмдүүлүк куралдарына чейин.",
