    "grp_personal_cnt": "9 долбоор",
    "casedesk_sub": "IT колдоо билет башкаруу системасы — Flutter Desktop",
    "casedesk_desc": "Филиалдар жана кызматкерлер үчүн толук Help Desk системасы: Offline-First булут синхрондоштуруу, интерактивдүү KPI аналитика тактасы, арабча PDF/Excel отчеттору, акылдуу билетти автоматтык түрдө толтуруу жана WhatsApp эскертмелери.",
    "ratil_sub": "Чекене Pro → Odoo ERP маалыматтарды көчүрүү",
    "ratil_desc": "Акылдуу тазалоо алгоритмдери жана параллелдүү иштетүү (Dart Isolates) менен <b>+715 463 кардар жазуусу</b> иштетилип жана тазаланды — 100% тактык жана кол менен көчүрүү убактысы 95% аз.",
    "itsc_sub": "Ишканалар үчүн программалык камсыздоону бөлүштүрүү платформасы",
    "itsc_desc": "Компания тармагында бекитилген программалык камсыздоону жайылтуу үчүн Enterprise колдонмосу: жандуу прогресс менен жүктөө менеджери (Dio), анимацияланган бейджик менен жаңыртууларды автоматтык түрдө аныктоо, арабча/англисче колдоо жана караңгы режим (3-материал).",
    "tpc_sub": "Видеону бөлүү — Electron.js + FFmpeg",
    "tpc_desc": "Stream Copy аркылуу 100% жоготуусуз сапатта видеолорду (1/2/3 мүнөт же жарым) бөлүү үчүн десктоп колдонмосу, автоматтык GPU аныктоо жана заманбап Glassmorphism UI менен. Windows, Linux жана macOS системаларында иштейт.",
    "ts_sub": "Терүү ылдамдыгы тренери — Electron.js",
    "ts_desc": "Толук RTL колдоосу менен (арабча/ивритче/персче), деталдуу WPM жана тактык статистикасы, булчуң эс тутумун куруу үчүн катаны мажбурлап токтотуу, глобалдык жарлыктарды жана тутум тактасы менен кайчылаш платформа терүү тренери.",
    "nui_sub": "Android ишке киргизгич — Kotlin + Jetpack Compose",
    "nui_desc": "MVVM архитектурасы жана Room DB менен заманбап Android ишке киргизгичи: орнотулган хижрий/григориан календары, үй экранындагы жазуулар, колдонмолорду автоматтык түрдө категориялаштыруу, таштанды челектери жана сезимтал колдонмолорду жашыруу.",
    "r30_sub": "Эмгек акы жана бюджетти башкаруу — Flutter",
    "r30_desc": "Smart Offline-First бюджет колдонмосу: автоматтык түрдө 50/30/20 бөлүштүрүү, динамикалык күнүмдүк бюджет, үнөмдөө көйгөйлөрү, кайрымдуулук бөлүмү, диаграммалар (fl_chart) жана айлык каржы календары — алты колдоого алынган платформа.",
    "pomo_sub": "Помодоро өндүрүмдүүлүк таймери — Флуттер",
    "pomo_desc": "Pomodoro техникасы менен иштөө/тыныгуу сессиясын башкаруу: ыңгайлаштырылган күнүмдүк жана жумалык максаттар, үн эскертүүлөрү, бир нече темалар жана Linux пакеттери (Flatpak / .desktop) — 5 платформада иштейт.",
    "lm_sub": "Суу белгисинин видео генератору — Flutter + FFmpeg",
    "lm_desc": "Эч кандай видео киргизбестен анимациялык текст суу белгиси менен MP4 видеолорду жаратат: Flutter Canvas кыймылдаткычы менен жогорку тактыкта ​​берилген арабча текст, толук диакритика колдоосу менен, Android жана Windows'до FFmpeg аркылуу экспорттолот.",
    "roms_small": "Операциялык системалар",
    "roms_title": "🤖 Булактан Ыңгайлаштырылган Android ROM'ларын түзүү",
    "roms_desc": "Толук AOSP ROM булактан өзөктү жөндөө, түзмөк дарагын орнотуу жана сатуучунун blob башкаруусу менен түзүлөт.",
    "rom1_desc": "Evolution X катмары, өзөктү ыңгайлаштыруу жана түзмөк дарагы, HAL оңдоолору жана камераны орнотуу жана Xiaomi аппараттык жабдыктарындагы Pixel тажрыйбасы менен толук AOSP булактан түзүлөт.",
    "rom2_desc": "AOSP Android 16 булактан Infinity X функциялары, ядро ​​жана түзмөк дарагын жөндөө, сатуучу блоб жана HAL башкаруусу менен түзүлөт.",
    "rom3_desc": "PixelOS булактан түзүлүп, ядро ​​компиляциясы, түзмөк дарагынын жөндөөлөрү жана сатуучунун блб чыгаруусу — Motorola жабдыктарындагы таза Pixel тажрыйбасы.",
    "rom4_desc": "Vanilla Google кызматтарынсыз түзүлөт (GApps) — бир эле түзмөктө 100% таза AOSP тажрыйбасы.",
    "rom4_tag3": "GApps жок",
