    "haris_sub": "YouTube Мазмун чыпкасы жана Фокус кеңейтүүсү — TypeScript + WXT",
    "haris_desc": "YouTube'ду каналдын ак тизмеси, Shorts бөгөттөөчүсү жана 40+ тилди колдогон жергиликтүү биринчи архитектурасы менен таза, багытталган окуу чөйрөсүнө айландырган ачык булактуу, купуялык үчүн биринчи кайчылаш браузер кеңейтүүсү.",
    "miqyas_sub": "Колдонмонун сөлөкөтү коопсуз аймак студиясы жана макеттер дүкөнү — Flutter",
    "miqyas_desc": "Иштеп чыгуучулар үчүн интерактивдүү студия бардык платформалардагы 66×66 коопсуз зонасында колдонмонун иконкаларын так тегиздөө үчүн, Google Play жана App Store үчүн жандуу көп түзмөктүн макетін алдын ала көрүү жана автоматташтырылган дүкөн скриншоту генератору.",
    "mufarrigh_sub": "Спрайт барагын чыгаруучу жана фон тазалоочу — Flutter + Dart Vision",
    "mufarrigh_desc": "Таза Dart кыймылдаткычы, BFS Flood-Fill жана адаптацияланган 3 панелдүү UI жана партия экспорту менен боштук эрозиясынын жардамы менен спрайт барактарын кесүү жана фонду алып салуу үчүн акылдуу иш тактасы жана мобилдик курал.",
    "tips_small": "Гиддер, түшүнүктөр жана чечимдер",
    "tips_title": "💡 Техникалык кеңештер жана чечимдер",
    "tips_desc": "Иштеп чыгууда жана тутумдарды башкарууда алынган практикалык колдонмолор, көйгөйлөрдү аныктоо боюнча түшүнүктөр жана автоматташтыруу куралдары.",
    "tip1_badge": "Flutter Build Warning & Fix",
    "tip1_title": "Версиялардын кагылышуусун алдын алуу үчүн Gradle for Java кеңейтүүсүн туура колдонуу",
    "tip1_desc": "IDE'иңизде <b>Gradle for Java</b> кеңейтүүсүн иштеткенде (VS Code / Antigravity), эгерде <b>Flutter</b> долбооруңуз бир нече Gradle версияларын же модулдарын камтыса, кеңейтүү ар бирин өз алдынча таап, курууга аракет кылат. Бул версиянын дал келбеген каталарын (мисалы, <code>Миминалдуу колдоого алынган Gradle версиясы - 9.6.0. Учурдагы версиясы - 9.4.0</code>) жана курууда каталарды жаратышы мүмкүн. Сунушталган ыкма - бул колдоого алынган жумушчу мейкиндиктерге кеңейтүүнү аныктоо же Flutter подкаталогдору үчүн долбоордун автоматтык түрдө терең ачылышын өчүрүү.",
    "tip2_badge": "Linux автоматташтыруу куралы",
    "tip2_sub": "Linux автоматташтыруу куралы — Bash + Arch Linux",
    "tip2_title": "Arch Linux үчүн Flutter орнотуучусу — Автоматташтырылган SDK орнотуу",
    "tip2_desc": "Arch Linux'та эң акыркы туруктуу Flutter SDK орнотууну автоматташтырган Bash скрипти: расмий булактан эң жаңы релизди автоматтык түрдө алып келет, үч кабык (Bash, Zsh жана Fish) боюнча чөйрө өзгөрмөлөрүн конфигурациялайт жана эң акыркы OpenJDK бир кадамда <code>archlinux-java</code> аркылуу демейки катары орнотот.",
