    "boycott_p2": "<b>Ja bojkotujem ove korporacije, ali kako da maksimiziramo korist od ovoga?</b><br>Dok sam radio u kompaniji u kojoj sam pomagao u postavljanju baza podataka, izbjegavao sam implementaciju ili korištenje <b>Oraclea</b> kako bih osigurao da ih ne podržavam. Ako neko napravi malu grešku, uči iz nje; sve dok imam ruku ili tehnički uticaj u bilo kojoj firmi, koristim samo tehnologije koje ne podržavaju one koji prolivaju krv naše braće, a moja je hrana na Allahu.",
    "boycott_p3": "I hvala Allahu, danas svaka tehnologija ima slobodnu i nezavisnu alternativu.. i iz ovog prolaznog života vi ćete otići (zato se bojte Allaha).",
