    "exp1_li5": "Выполнял задачи по техническому обслуживанию и оборудованию, анализировал ключевые показатели эффективности с помощью интерактивных панелей мониторинга и создавал профессиональные отчеты в формате PDF/Excel на арабском языке.",
    "exp1_intro": "За время работы в компании я разработал комплексные программные системы, которые ежедневно используются филиалами и сотрудниками: систему управления обращениями в службу поддержки, внутреннюю платформу распространения программного обеспечения и инструмент обработки и миграции больших данных, а также проектировал и документировал сетевую инфраструктуру, а также выполнял задачи по обслуживанию и оборудованию.",
    "boycott_title": "🕊️Технический бойкот",
