    "boycott_badge": "Принцип и позиция",
    "boycott_p1": "Как <b>сетевой специалист</b>, я бойкотирую <b>Cisco</b> из-за их глубокого соучастия и поддержки убийц пророков и угнетателей. Несмотря на то, что у меня есть сертификаты Cisco, я с радостью отказываюсь от них ради Аллаха. Я отрекусь от того, кто причинит вред моим братьям-мусульманам, даже в ущерб моим личным интересам, ибо наше пропитание – от Аллаха, Самодостаточного, Достохвального.",
    "boycott_p2": "<b>Я бойкотирую эти корпорации, но как нам получить от этого максимальную выгоду?</b><br>Работая в компании, где я помогал развертывать базы данных, я избегал развертывания или использования <b>Oracle</b>, чтобы не поддерживать их. Если кто-то совершает небольшую ошибку, он на этом учится; пока я имею руку или техническое влияние в какой-либо фирме, я использую только технологии, которые не поддерживают тех, кто проливает кровь наших братьев, и мое пропитание – на Аллахе.",
    "boycott_p3": "И хвала Аллаху, сегодня у каждой технологии есть свободная и независимая альтернатива... и из этой мимолетной жизни вы уйдете (так бойтесь Аллаха).",
