    "itsc_desc": "Корпоративное приложение для распространения одобренного программного обеспечения внутри сети компании: менеджер загрузок с отслеживанием прогресса в реальном времени (Dio), автоматическое обнаружение обновлений с анимированным значком, поддержка арабского/английского языков и темный режим (Материал 3).",
    "tpc_sub": "Разделение видео — Electron.js + FFmpeg",
    "tpc_desc": "Настольное приложение для разделения видео (1/2/3 минуты или половинки) со 100% качеством без потерь с помощью Stream Copy, с автоматическим определением графического процессора и современным пользовательским интерфейсом Glassmorphism. Работает на Windows, Linux и macOS.",
    "ts_sub": "Тренажер скорости набора текста — Electron.js",
    "ts_desc": "Кроссплатформенный тренажер набора текста с полной поддержкой RTL (арабский/иврит/персидский язык), подробной статистикой WPM и точности, принудительной остановкой при ошибке для наращивания мышечной памяти, глобальными ярлыками и системным треем.",
    "nui_sub": "Android-лаунчер — Kotlin + Jetpack Compose",
    "nui_desc": "Современная программа запуска Android с архитектурой MVVM и базой данных комнаты: встроенный календарь по хиджре/григорианскому календарю, заметки на главном экране, автоматическая категоризация приложений, корзина для мусора и скрытие конфиденциальных приложений.",
    "r30_sub": "Управление зарплатой и бюджетом — Flutter",
    "r30_desc": "Приложение Smart Offline-First Budget: автоматическое распределение 50/30/20, динамический ежедневный бюджет, проблемы сбережений, раздел благотворительности, диаграммы (fl_chart) и ежемесячный финансовый календарь — шесть поддерживаемых платформ.",
    "pomo_sub": "Таймер продуктивности Pomodoro — Flutter",
    "pomo_desc": "Управление сеансами работы/перерыва с помощью метода Pomodoro: настраиваемые ежедневные и еженедельные цели, звуковые оповещения, несколько тем и пакеты Linux (Flatpak / .desktop) — работает на 5 платформах.",
    "lm_sub": "Генератор видео водяных знаков — Flutter + FFmpeg",
    "lm_desc": "Генерирует видео в формате MP4 с анимированным текстовым водяным знаком без какого-либо входного видео: текст на арабском языке, визуализируемый с помощью механизма Flutter Canvas с высокой точностью и полной поддержкой диакритических знаков, экспортируется через FFmpeg на Android и Windows.",
    "roms_small": "Операционные системы",
    "roms_title": "🤖 Создание пользовательских прошивок Android из исходного кода",
    "roms_desc": "Полное ПЗУ AOSP собирается из исходного кода с настройкой ядра, настройкой дерева устройств и управлением BLOB-объектами поставщиков.",
    "rom1_desc": "Полная сборка AOSP из исходного кода со слоем Evolution X, пользовательской настройкой ядра и деревом устройств, исправлениями HAL и настройкой камеры, а также возможностями Pixel на оборудовании Xiaomi.",
    "rom2_desc": "AOSP Android 16 собран из исходного кода с функциями Infinity X, настройкой ядра и дерева устройств, а также управлением BLOB-объектами и HAL от поставщиков.",
    "rom3_desc": "Сборка PixelOS из исходного кода с компиляцией ядра, настройкой дерева устройств и извлечением BLOB-объектов поставщика — удобный интерфейс Pixel на оборудовании Motorola.",
    "rom4_desc": "Сборка Vanilla без сервисов Google (GApps) — 100 % чистый AOSP на том же устройстве.",
    "rom4_tag3": "Нет GApps",
    "rom5_desc": "Поддержка и создание официального прошивки LineageOS 23.2 для Moto G54 5G — стабильной, легкой прошивки с открытым исходным кодом с регулярными обновлениями безопасности.",
    "rom5_tag2": "Открытый исходный код",
    "rom5_tag3": "Обновления безопасности",
