    "haris_sub": "Расширение фильтра контента и фокуса YouTube — TypeScript + WXT",
    "haris_desc": "Кроссбраузерное расширение с открытым исходным кодом, обеспечивающее конфиденциальность, которое превращает YouTube в чистую, целенаправленную среду обучения с белым списком каналов, блокировщиком коротких видео и локальной архитектурой, поддерживающей более 40 языков.",
    "miqyas_sub": "Макеты студии и магазина безопасной зоны значка приложения — Flutter",
    "miqyas_desc": "Интерактивная студия для разработчиков, позволяющая точно выравнивать значки приложений в безопасной зоне размером 66×66 на всех платформах, с возможностью предварительного просмотра макета на нескольких устройствах и автоматическим генератором снимков экрана магазина для Google Play и App Store.",
    "mufarrigh_sub": "Средство извлечения листов спрайтов и удаления фона — Flutter + Dart Vision",
    "mufarrigh_desc": "Умный настольный и мобильный инструмент для нарезки листов спрайтов и удаления фона с использованием чистого движка Dart, BFS Flood-Fill и эрозии зазоров с адаптивным трехпанельным пользовательским интерфейсом и пакетного экспорта.",
    "tips_small": "Руководства, идеи и решения",
    "tips_title": "💡 Технические советы и решения",
    "tips_desc": "Практические руководства, сведения об устранении неполадок и инструменты автоматизации, полученные в ходе разработки и системного администрирования.",
    "tip1_badge": "Предупреждение и исправление сборки Flutter",
    "tip1_title": "Правильное использование расширения Gradle для Java для предотвращения конфликтов версий.",
    "tip1_desc": "Если при включении расширения <b>Gradle for Java</b> в вашей IDE (VS Code/Antigradity) ваш проект <b>Flutter</b> содержит несколько версий или модулей Gradle, расширение пытается обнаружить и собрать каждую из них независимо. Это может вызвать ошибки несоответствия версий (например, <code>Минимальная поддерживаемая версия Gradle — 9.6.0. Текущая версия — 9.4.0</code>) и вызвать сбои сборки. Рекомендуемый подход — ограничить расширение поддерживаемыми рабочими пространствами или отключить автоматическое глубокое обнаружение проектов для подкаталогов Flutter.",
    "tip2_badge": "Инструмент автоматизации Linux",
    "tip2_sub": "Инструмент автоматизации Linux — Bash + Arch Linux",
    "tip2_title": "Установщик Flutter для Arch Linux — автоматическая установка SDK",
    "tip2_desc": "Скрипт Bash, который автоматизирует установку последней стабильной версии Flutter SDK в Arch Linux: автоматически извлекает новейшую версию из официального источника, настраивает переменные среды в трех оболочках (Bash, Zsh и Fish) и устанавливает последнюю версию OpenJDK по умолчанию с помощью <code>archlinux-java</code> за один шаг.",
    "tip_img_tag": "📸 Скриншот расширения и ошибки",
    "tip_vid_tag": "🎬 Демонстрационное видео",
    "footer": "Дизайн и разработка: <b>Хосам Хасан Маджраши</b> © 2026 — Все проекты доступны на GitHub."
