    "exp1_li1": "Entworfen und entwickelt <b>CaseDesk</b>, ein Support-Ticket-Managementsystem für Filialen und Mitarbeiter – Offline-First-Architektur mit dualen Datenbanken (lokales Hive + Cloud über PHP-REST-APIs).",
