    "exp1_intro": "Während meiner Zeit im Unternehmen habe ich komplette Softwaresysteme entwickelt, die täglich von Niederlassungen und Mitarbeitern verwendet werden: ein Support-Ticket-Management-System, eine interne Software-Verteilungsplattform und ein Big-Data-Verarbeitungs- und Migrationstool – neben dem Entwurf und der Dokumentation der Netzwerkinfrastruktur und der Abwicklung von Wartungs- und Hardwareaufgaben.",
    "boycott_title": "🕊️ Technischer Boykott",
    "boycott_sub": "Feste Prinzipien und eine auf Glauben basierende Haltung",
    "boycott_badge": "Prinzip & Haltung",
    "boycott_p1": "Als <b>Netzwerkspezialist</b> boykottiere ich <b>Cisco</b> aufgrund ihrer tiefen Komplizenschaft und Unterstützung für die Mörder von Propheten und Unterdrückern. Obwohl ich zertifizierte Zertifizierungen von Cisco besitze, verzichte ich im Namen Allahs gerne darauf. Wer auch immer meinen muslimischen Brüdern Schaden zufügt, dem werde ich entsagen, auch auf Kosten meiner persönlichen Interessen – denn unser Lebensunterhalt liegt bei Allah, dem Selbstgenügsamen, dem Lobenswerten.",
    "boycott_p2": "<b>Ich boykottiere diese Unternehmen, aber wie können wir den größtmöglichen Nutzen daraus ziehen?</b><br>Während meiner Arbeit in einem Unternehmen, in dem ich bei der Bereitstellung von Datenbanken geholfen habe, habe ich es vermieden, <b>Oracle</b> bereitzustellen oder zu nutzen, um sicherzustellen, dass sie nicht unterstützt werden. Wenn man einen kleinen Fehler macht, lernt man daraus; Solange ich in einem Unternehmen tätig bin oder technischen Einfluss habe, verwende ich nur Technologien, die diejenigen nicht unterstützen, die das Blut unserer Brüder vergießen, und mein Lebensunterhalt liegt bei Allah.",
    "boycott_p3": "Und Lob gebührt Allah, heute gibt es für jede Technologie eine freie und unabhängige Alternative. Und aus diesem vergänglichen Leben werdet ihr scheiden (also fürchtet Allah).",
