    "boycott_tip": "<b>Ratschlag für Gezwungene:</b> Wenn jemand gezwungen ist, ein Produkt von einem boykottierten Unternehmen zu kaufen, ohne dass eine Alternative verfügbar ist, kaufen Sie es <b>gebraucht/gebraucht</b>, damit das Unternehmen keinen neuen Gewinn erzielt. Gepriesen sei Allah und auf Ihn vertrauen wir.",
