    "casedesk_desc": "Komplettes Helpdesk-System für Filialen und Mitarbeiter: Offline-First-Cloud-Synchronisierung, interaktives KPI-Analyse-Dashboard, arabische PDF-/Excel-Berichte, intelligentes automatisches Ausfüllen von Tickets und WhatsApp-Benachrichtigungen.",
    "ratil_sub": "Retail Pro → Odoo ERP-Datenmigration",
    "ratil_desc": "Verarbeitet und bereinigt <b>+715.463 Kundendatensätze</b> mit intelligenten Reinigungsalgorithmen und paralleler Verarbeitung (Dart Isolates), ohne die Benutzeroberfläche einzufrieren – 100 % Genauigkeit und 95 % weniger manuelle Migrationszeit.",
