    "tpc_sub": "Videoaufteilung – Electron.js + FFmpeg",
    "tpc_desc": "Desktop-App zum Teilen von Videos (1/2/3 Minuten oder Hälften) in 100 % verlustfreier Qualität über Stream Copy, mit automatischer GPU-Erkennung und einer modernen Glassmorphism-Benutzeroberfläche. Läuft unter Windows, Linux und macOS.",
    "ts_sub": "Tippgeschwindigkeitstrainer – Electron.js",
