    "r30_sub": "Gehalts- und Budgetverwaltung – Flutter",
    "r30_desc": "Intelligente Offline-First-Budget-App: automatische 50/30/20-Verteilung, dynamisches Tagesbudget, Sparherausforderungen, Wohltätigkeitsbereich, Diagramme (fl_chart) und ein monatlicher Finanzkalender – sechs unterstützte Plattformen.",
    "pomo_sub": "Pomodoro-Produktivitäts-Timer – Flutter",
    "pomo_desc": "Verwaltung von Arbeits-/Pausensitzungen mit der Pomodoro-Technik: anpassbare Tages- und Wochenziele, akustische Warnungen, mehrere Themen und Linux-Pakete (Flatpak / .desktop) – läuft auf 5 Plattformen.",
    "lm_sub": "Wasserzeichen-Videogenerator – Flutter + FFmpeg",
