    "haris_sub": "YouTube-Inhaltsfilter und Fokuserweiterung – TypeScript + WXT",
    "haris_desc": "Eine browserübergreifende Open-Source-Erweiterung, die den Datenschutz an erster Stelle steht und YouTube in eine saubere, fokussierte Lernumgebung mit Kanal-Whitelisting, Shorts-Blocker und Local-First-Architektur verwandelt, die mehr als 40 Sprachen unterstützt.",
