    "tip1_desc": "Wenn Sie die <b>Gradle für Java</b>-Erweiterung in Ihrer IDE (VS Code/Antigravity) aktivieren und Ihr <b>Flutter</b>-Projekt mehrere Gradle-Versionen oder -Module enthält, versucht die Erweiterung, jede einzeln zu erkennen und zu erstellen. Dies kann Versionskonfliktfehler auslösen (z. B. <code>Minimal unterstützte Gradle-Version ist 9.6.0. Aktuelle Version ist 9.4.0</code>) und Build-Fehler verursachen. Der empfohlene Ansatz besteht darin, die Erweiterung auf unterstützte Arbeitsbereiche zu beschränken oder die automatische Tiefenprojekterkennung für Flutter-Unterverzeichnisse zu deaktivieren.",
    "tip2_badge": "Linux-Automatisierungstool",
    "tip2_sub": "Linux-Automatisierungstool – Bash + Arch Linux",
    "tip2_title": "Flutter Installer für Arch Linux – Automatisiertes SDK-Setup",
    "tip2_desc": "Bash-Skript, das die Installation des neuesten stabilen Flutter SDK unter Arch Linux automatisiert: ruft automatisch die neueste Version von der offiziellen Quelle ab, konfiguriert Umgebungsvariablen über drei Shells (Bash, Zsh und Fish) und legt das neueste OpenJDK als Standard über <code>archlinux-java</code> in einem Schritt fest.",
    "tip_img_tag": "📸 Erweiterungs- und Fehler-Screenshot",
