    "casedesk_sub": "Sistema de gerenciamento de tickets de suporte de TI — Flutter Desktop",
    "casedesk_desc": "Sistema completo de Help Desk para filiais e funcionários: sincronização off-line na nuvem, painel interativo de análise de KPI, relatórios em PDF/Excel em árabe, preenchimento automático de tickets inteligentes e notificações do WhatsApp.",
