    "ts_desc": "Treinador de digitação multiplataforma com suporte RTL completo (árabe/hebraico/persa), WPM detalhado e estatísticas de precisão, parada forçada em caso de erro para construir memória muscular, atalhos globais e bandeja do sistema.",
