    "pomo_desc": "Gerenciamento de sessões de trabalho/pausa com a técnica Pomodoro: metas diárias e semanais personalizáveis, alertas sonoros, temas múltiplos e pacotes Linux (Flatpak / .desktop) — roda em 5 plataformas.",
    "lm_sub": "Gerador de vídeo de marca d’água – Flutter + FFmpeg",
    "lm_desc": "Gera vídeos MP4 com marca d'água de texto animado sem qualquer entrada de vídeo: texto árabe renderizado com mecanismo Flutter Canvas em alta fidelidade com suporte completo a diacríticos, exportado via FFmpeg no Android e Windows.",
