    "tip1_badge": "Aviso e correção do Flutter Build",
    "tip1_title": "Uso correto da extensão Gradle para Java para evitar conflitos de versão",
    "tip1_desc": "Ao ativar a extensão <b>Gradle for Java</b> em seu IDE (VS Code/Antigravity), se seu projeto <b>Flutter</b> contiver diversas versões ou módulos do Gradle, a extensão tentará descobrir e criar cada um deles de forma independente. Isso pode desencadear erros de incompatibilidade de versão (por exemplo, <code>A versão mínima suportada do Gradle é 9.6.0. A versão atual é 9.4.0</code>) e causar falhas de compilação. A abordagem recomendada é definir o escopo da extensão para espaços de trabalho compatíveis ou desabilitar a descoberta automática profunda de projetos para subdiretórios Flutter.",
