    "boycott_p1": "作为一名<b>网络专家</b>，我抵制<b>思科</b>，因为他们与杀害先知和压迫者的凶手有着深厚的共谋和支持。尽管拥有思科的认证证书，但我很乐意为了安拉而放弃它们。无论谁伤害我的穆斯林兄弟，我都会放弃，甚至不惜牺牲我的个人利益——因为我们的生计在于自给自足、值得赞美的安拉。",
    "boycott_p2": "<b>我抵制这些公司，但我们如何从中最大化利益？</b><br>在我帮助部署数据库的公司工作时，我避免部署或使用 <b>Oracle</b> 以确保不支持它们。如果一个人犯了一个小错误，他们会从中吸取教训；只要我在任何公司有影响力或技术影响力，我只使用那些不支持那些让我们兄弟流血的人的技术，我的寄托在于真主。",
    "boycott_p3": "赞美真主，今天每一种技术都有一个自由和独立的替代方案……你将从这短暂的生命中离开（所以敬畏真主）。",
