    "ts_desc": "跨平台打字训练器，具有完整的 RTL 支持（阿拉伯语/希伯来语/波斯语）、详细的 WPM 和准确性统计数据、错误时强制停止以建立肌肉记忆、全局快捷方式和系统托盘。",
    "nui_sub": "Android 启动器 — Kotlin + Jetpack Compose",
    "nui_desc": "具有 MVVM 架构和 Room DB 的现代 Android 启动器：内置 Hijri/Gregorian 日历、主屏幕注释、自动应用程序分类、垃圾箱和隐藏敏感应用程序。",
    "r30_sub": "薪资和预算管理——Flutter",
    "r30_desc": "智能离线优先预算应用程序：自动 50/30/20 分配、动态每日预算、储蓄挑战、慈善部分、图表 (fl_chart) 和每月财务日历 - 六个支持的平台。",
    "pomo_sub": "番茄工作效率计时器 — Flutter",
    "pomo_desc": "使用番茄工作法进行工作/休息会话管理：可定制的每日和每周目标、声音警报、多个主题和 Linux 软件包 (Flatpak / .desktop) — 在 5 个平台上运行。",
    "lm_sub": "水印视频生成器——Flutter + FFmpeg",
    "lm_desc": "无需任何输入视频即可生成带有动画文本水印的 MP4 视频：使用 Flutter Canvas 引擎以高保真度渲染阿拉伯文本，并提供完整的变音符号支持，通过 Android 和 Windows 上的 FFmpeg 导出。",
    "roms_small": "操作系统",
    "roms_title": "🤖 从源代码构建自定义 Android ROM",
    "roms_desc": "完整的 AOSP ROM 从源代码构建，具有内核调整、设备树设置和供应商 blob 管理。",
    "rom1_desc": "完整的 AOSP 从源代码构建，包括 Evolution X 层、自定义内核调整和设备树、HAL 修复和相机设置，以及小米硬件上的 Pixel 体验。",
    "rom2_desc": "AOSP Android 16 从源代码构建，具有 Infinity X 功能、内核和设备树调整以及供应商 blob 和 HAL 管理。",
    "rom3_desc": "PixelOS 通过内核编译、设备树设置和供应商 blob 提取从源代码构建 - 在摩托罗拉硬件上提供干净的 Pixel 体验。",
    "rom4_desc": "无需 Google 服务 (GApps) 的 Vanilla 构建 — 在同一设备上获得 100% 纯 AOSP 体验。",
    "rom4_tag3": "没有 GApps",
    "rom5_desc": "维护和构建 Moto G54 5G 的官方 LineageOS 23.2 ROM - 一个稳定、轻量级的开源 ROM，并定期进行安全更新。",
    "rom5_tag2": "开源",
    "rom5_tag3": "安全更新",
