    "nav_tips": "技术提示",
    "haris_sub": "YouTube 内容过滤器和焦点扩展 — TypeScript + WXT",
    "haris_desc": "一款开源、隐私至上的跨浏览器扩展，可将 YouTube 转变为干净、专注的学习环境，具有频道白名单、Shorts 拦截器和支持 40 多种语言的本地优先架构。",
    "miqyas_sub": "应用程序图标安全区工作室和商店模型 — Flutter",
    "miqyas_desc": "交互式工作室供开发人员在所有平台的 66×66 安全区域内准确对齐应用程序图标，具有实时多设备模型预览和适用于 Google Play 和 App Store 的自动商店屏幕截图生成器。",
    "mufarrigh_sub": "精灵表提取器和背景去除器 - Flutter + Dart Vision",
    "mufarrigh_desc": "智能桌面和移动工具，使用纯 Dart 引擎、BFS Flood-Fill 和间隙侵蚀以及自适应 3 窗格 UI 和批量导出来切割精灵表并删除背景。",
    "tips_small": "指南、见解和解决方案",
    "tips_title": "💡 技术提示和解决方案",
