    "tip1_badge": "Flutter 构建警告和修复",
    "tip1_title": "正确使用Gradle for Java扩展防止版本冲突",
    "tip1_desc": "在 IDE（VS Code/Antigravity）中启用 <b>Gradle for Java</b> 扩展时，如果您的 <b>Flutter</b> 项目包含多个 Gradle 版本或模块，则该扩展会尝试独立发现和构建每个版本或模块。这可能会触发版本不匹配错误（例如，<code>支持的最低 Gradle 版本为 9.6.0。当前版本为 9.4.0</code>）并导致构建失败。推荐的方法是将扩展范围限定为支持的工作区或禁用 Flutter 子目录的自动深度项目发现。",
    "tip2_badge": "Linux自动化工具",
    "tip2_sub": "Linux 自动化工具 — Bash + Arch Linux",
    "tip2_title": "适用于 Arch Linux 的 Flutter 安装程序 — 自动 SDK 设置",
    "tip2_desc": "Bash 脚本可在 Arch Linux 上自动安装最新稳定的 Flutter SDK：自动从官方来源获取最新版本，跨三个 shell（Bash、Zsh 和 Fish）配置环境变量，并通过 <code>archlinux-java</code> 一步将最新的 OpenJDK 设置为默认值。",
    "tip_img_tag": "📸 扩展和错误截图",
