    "exp1_period": "2026 年 2 月 — 2026 年 8 月",
    "exp1_li1": "設計和開發了 <b>CaseDesk</b>，這是一個面向分支機構和員工的支援票證管理系統 - 具有雙資料庫的離線優先架構（本地 Hive + 透過 PHP REST API 的雲端）。",
