    "exp1_li3": "建置了 <b>RatilConvert</b>，它可以處理和清理 Retail Pro 中的 <b>+715,463 則客戶記錄</b>，並將其以 100% 相容性匯出到 Odoo ERP - 將手動遷移時間縮短 95%。",
