    "exp1_li5": "處理維護和硬體任務，透過互動式儀表板分析 KPI，並產生專業的阿拉伯語 PDF/Excel 報告。",
    "exp1_intro": "在公司任職期間，我開發了分支機構和員工日常使用的完整軟體系統：支援票證管理系統、內部軟體分發平台以及大數據處理和遷移工具，同時設計和記錄網路基礎設施以及處理維護和硬體任務。",
    "boycott_title": "🕊️ 科技抵制",
