    "boycott_badge": "原則與立場",
    "boycott_p1": "身為<b>網路專家</b>，我抵制<b>思科</b>，因為他們與殺害先知和壓迫者的兇手有著深厚的共謀和支持。儘管擁有思科的認證證書，但我很樂意為了安拉而放棄它們。無論誰傷害我的穆斯林兄弟，我都會放棄，甚至不惜犧牲我的個人利益──因為我們的生計在於自給自足、值得讚美的安拉。",
    "boycott_p2": "<b>我抵制這些公司，但我們如何從中最大化利益？ </b><br>在我幫助部署資料庫的公司工作時，我避免部署或使用 <b>Oracle</b> 以確保不支援它們。如果一個人犯了一個小錯誤，他們會從中學習；只要我在任何公司有影響力或技術影響力，我只使用那些不支持那些讓我們兄弟流血的人的技術，我的寄託在於真主。",
    "boycott_p3": "讚美真主，今天每一種技術都有一個自由和獨立的替代方案……你將從這短暫的生命中離開（所以敬畏真主）。",
