    "boycott_p2": "<b>私はこれらの企業をボイコットしますが、そこから得られる利益を最大化するにはどうすればよいですか?</b><br>データベースの導入を支援した会社で働いていた間、私はそれらをサポートしないようにするために <b>Oracle</b> の導入や利用を避けていました。わずかな間違いを犯しても、そこから学びます。私がどの企業でも技術的影響力を持っている限り、私は同胞の血を流した者たちを支援しない技術のみを使用します。私の養分はアッラーにあります。",
