    "ratil_sub": "Retail Pro → Odoo ERP データ移行",
    "ratil_desc": "スマート クリーニング アルゴリズムと並列処理 (Dart Isolates) により、UI をフリーズさせることなく <b>+715,463 件の顧客レコード</b> を処理およびクリーニングしました。精度は 100%、手動移行時間は 95% 短縮されました。",
    "itsc_sub": "企業向け社内ソフトウェア配布プラットフォーム",
    "itsc_desc": "社内ネットワーク内で承認されたソフトウェアを配布するためのエンタープライズ アプリ: ライブ進行状況を備えたダウンロード マネージャー (Dio)、アニメーション バッジによる自動更新検出、アラビア語/英語のサポート、ダーク モード (資料 3)。",
    "tpc_sub": "ビデオ分割 — Electron.js + FFmpeg",
    "tpc_desc": "自動 GPU 検出と最新の Glassmorphism UI を備え、ストリーム コピー経由でビデオ (1/2/3 分または半分) を 100% ロスレス品質で分割するためのデスクトップ アプリです。 Windows、Linux、macOS 上で動作します。",
    "ts_sub": "タイピングスピードトレーナー — Electron.js",
    "ts_desc": "完全な RTL サポート (アラビア語/ヘブライ語/ペルシャ語)、詳細な WPM と精度の統計、筋記憶を構築するためのエラー時の強制停止、グローバル ショートカット、システム トレイを備えたクロスプラットフォームのタイピング トレーナー。",
    "nui_sub": "Android ランチャー — Kotlin + Jetpack Compose",
    "nui_desc": "MVVM アーキテクチャと Room DB を備えた最新の Android ランチャー: 組み込みのイスラム暦/グレゴリオ暦カレンダー、ホーム画面のメモ、アプリの自動分類、ゴミ箱、機密性の高いアプリの非表示。",
    "r30_sub": "給与と予算の管理 — Flutter",
    "r30_desc": "スマート オフライン - ファースト予算アプリ: 50/30/20 の自動配分、動的な日次予算、貯蓄チャレンジ、慈善セクション、チャート (fl_chart)、月次財務カレンダー - 6 つのプラットフォームがサポートされています。",
    "pomo_sub": "ポモドーロ生産性タイマー — Flutter",
    "pomo_desc": "ポモドーロ テクニックによる仕事/休憩セッション管理: カスタマイズ可能な毎日および毎週の目標、サウンド アラート、複数のテーマ、Linux パッケージ (Flatpak / .desktop) — 5 つのプラットフォームで実行します。",
    "lm_sub": "ウォーターマークビデオジェネレーター — Flutter + FFmpeg",
    "lm_desc": "入力ビデオなしで、アニメーション テキストの透かしを含む MP4 ビデオを生成します。アラビア語のテキストは、発音記号を完全にサポートし、Flutter Canvas エンジンで高忠実度でレンダリングされ、Android および Windows 上の FFmpeg 経由でエクスポートされます。",
    "roms_small": "オペレーティングシステム",
    "roms_title": "🤖 ソースからカスタム Android ROM を構築",
    "roms_desc": "完全な AOSP ROM は、カーネルのチューニング、デバイス ツリーのセットアップ、ベンダー BLOB 管理を使用してソースからビルドされます。",
    "rom1_desc": "Evolution X レイヤーを使用したソースからの完全な AOSP ビルド、カスタム カーネル チューニングとデバイス ツリー、HAL 修正とカメラ セットアップ、Xiaomi ハードウェアでの Pixel エクスペリエンス。",
    "rom2_desc": "AOSP Android 16 は、Infinity X 機能、カーネルとデバイス ツリーの調整、ベンダー BLOB と HAL 管理を備えたソースからビルドされます。",
    "rom3_desc": "PixelOS は、カーネル コンパイル、デバイス ツリー セットアップ、ベンダー BLOB 抽出を使用してソースからビルドされ、Motorola ハードウェア上でクリーンな Pixel エクスペリエンスを実現します。",
    "rom4_desc": "Google サービス (GApps) を含まないバニラ ビルド — 同じデバイス上で 100% 純粋な AOSP エクスペリエンス。",
