    "tip1_title": "バージョンの競合を防ぐための Gradle for Java 拡張機能の正しい使用方法",
    "tip1_desc": "IDE (VS Code / Antigravity) で <b>Gradle for Java</b> 拡張機能を有効にするとき、<b>Flutter</b> プロジェクトに複数の Gradle バージョンまたはモジュールが含まれている場合、拡張機能はそれぞれを個別に検出してビルドしようとします。これにより、バージョン不一致エラー (例: <code>サポートされる Gradle の最小バージョンは 9.6.0 です。現在のバージョンは 9.4.0 です</code>) がトリガーされ、ビルド失敗が発生する可能性があります。推奨されるアプローチは、サポートされているワークスペースに拡張機能の範囲を設定するか、Flutter サブディレクトリの自動詳細プロジェクト検出を無効にすることです。",
