    "exp1_li4": "전체 네트워크 문서와 함께 서버 배포, 방화벽, 코어 스위치 및 부서 스위치를 포함하여 draw.io를 사용하여 회사의 물리적 네트워크 다이어그램을 설계했습니다.",
    "exp1_li5": "유지 관리 및 하드웨어 작업을 처리하고, 대화형 대시보드를 통해 KPI를 분석하고, 전문적인 아랍어 PDF/Excel 보고서를 생성했습니다.",
    "exp1_intro": "회사에 근무하는 동안 저는 네트워크 인프라를 설계 및 문서화하고 유지 관리 및 하드웨어 작업을 처리하는 동시에 지점과 직원이 매일 사용하는 지원 티켓 관리 시스템, 내부 소프트웨어 배포 플랫폼, 빅 데이터 처리 및 마이그레이션 도구 등 완전한 소프트웨어 시스템을 개발했습니다.",
    "boycott_title": "🕊️ 기술 보이콧",
    "boycott_sub": "확고한 원칙과 신념에 기초한 자세",
    "boycott_badge": "원칙과 입장",
    "boycott_p1": "<b>네트워크 전문가</b>로서 저는 선지자와 압제자들을 죽이는 자들에 대한 그들의 깊은 공모와 지원으로 인해 <b>Cisco</b>를 보이콧합니다. Cisco에서 인증한 자격 증명을 보유하고 있음에도 불구하고 나는 알라를 위해 기꺼이 그 자격을 포기합니다. 나의 무슬림 형제들에게 해를 끼치는 사람이 누구든지 나의 개인적인 이익을 희생하더라도 나는 포기할 것입니다. 왜냐하면 우리의 생계는 자급자족하시고 찬양받으실 알라께 있기 때문입니다.",
    "boycott_p2": "<b>저는 이러한 기업을 보이콧합니다. 하지만 이로 인한 이익을 극대화하려면 어떻게 해야 합니까?</b><br>제가 데이터베이스 배포를 도운 회사에서 근무하는 동안 저는 해당 기업을 지원하지 않도록 <b>Oracle</b> 배포 또는 활용을 피했습니다. 약간의 실수를 해도 그로부터 교훈을 얻습니다. 내가 어느 회사에든 손이나 기술적 영향력을 갖고 있는 한 나는 우리 형제들의 피를 흘리는 자들을 지원하지 않는 기술만을 사용하며 나의 생계는 알라에게 있습니다.",
    "boycott_p3": "그리고 알라께 찬양을 돌리십시오. 오늘날 모든 기술에는 자유롭고 독립적인 대안이 있습니다. 그리고 당신은 이 찰나의 삶에서 떠날 것입니다(그래서 알라를 두려워하십시오).",
    "cisco_title": "시스코",
    "cisco_sub": "네트워킹 인프라 및 하드웨어",
    "cisco_desc": "Cisco의 공모에 대한 문서화된 증거 - 화살표를 사용하여 슬라이드를 탐색하십시오.",
    "ms_title": "마이크로소프트",
    "ms_sub": "시스템 및 클라우드 컴퓨팅",
    "ms_desc": "공모에 반대하는 소프트웨어 엔지니어 Ibtehal Abu Al-Saad의 역사적인 입장과 문서화된 증거:",
    "oracle_title": "신탁",
    "oracle_sub": "데이터베이스 및 엔터프라이즈 클라우드",
    "oracle_desc": "기업 공모를 문서화하고 오픈 소스 대안(예: PostgreSQL 및 MariaDB)을 약속합니다.",
    "boycott_tip": "<b>강요된 사람을 위한 조언:</b> 대안이 없는 불매 운동 대상 기업으로부터 제품을 구매해야 하는 경우 해당 제품을 <b>중고/중고</b> 구매하여 회사가 새로운 이익을 얻지 못하게 하세요. 알라를 찬양하며 우리는 그분을 의지합니다.",
    "proj_small": "포트폴리오",
    "proj_title": "🛠️ 소프트웨어 프로젝트",
    "proj_desc": "기업 관리 시스템부터 데스크톱 및 모바일 생산성 도구까지 GitHub에 게시된 실제 완성된 프로젝트입니다.",
    "grp_company": "🏢 Almajarah 회사 프로젝트",
    "grp_company_cnt": "프로젝트 3개",
    "grp_personal": "👤 개인 프로젝트 — GitHub에 게시",
    "grp_personal_cnt": "9개 프로젝트",
    "casedesk_sub": "IT 지원 티켓 관리 시스템 — Flutter Desktop",
    "casedesk_desc": "지점 및 직원을 위한 완벽한 헬프 데스크 시스템: 오프라인 우선 클라우드 동기화, 대화형 KPI 분석 대시보드, 아랍어 PDF/Excel 보고서, 스마트 티켓 자동 채우기 및 WhatsApp 알림.",
    "ratil_sub": "Retail Pro → Odoo ERP 데이터 마이그레이션",
    "ratil_desc": "스마트 정리 알고리즘과 병렬 처리(Dart Isolates)를 사용하여 UI를 동결하지 않고 <b>715,463개 이상의 고객 기록</b>을 처리하고 정리했습니다. 정확도는 100%, 수동 마이그레이션 시간은 95% 단축되었습니다.",
    "itsc_sub": "기업용 내부 소프트웨어 배포 플랫폼",
    "itsc_desc": "회사 네트워크 내부에 승인된 소프트웨어를 배포하기 위한 엔터프라이즈 앱: 실시간 진행률이 포함된 다운로드 관리자(Dio), 애니메이션 배지를 통한 자동 업데이트 감지, 아랍어/영어 지원 및 다크 모드(자료 3).",
    "tpc_sub": "비디오 분할 — Electron.js + FFmpeg",
    "tpc_desc": "자동 GPU 감지 및 최신 Glassmorphism UI를 갖춘 Stream Copy를 통해 100% 무손실 품질로 비디오(1/2/3분 또는 절반)를 분할하기 위한 데스크탑 앱입니다. Windows, Linux 및 macOS에서 실행됩니다.",
    "ts_sub": "타이핑 속도 트레이너 — Electron.js",
    "ts_desc": "완전한 RTL 지원(아랍어/히브리어/페르시아어), 상세한 WPM 및 정확도 통계, 근육 기억 구축을 위한 오류 발생 시 강제 중지, 전역 ​​단축키 및 시스템 트레이를 갖춘 크로스 플랫폼 타이핑 트레이너입니다.",
    "nui_sub": "Android 런처 — Kotlin + Jetpack Compose",
    "nui_desc": "MVVM 아키텍처 및 Room DB를 갖춘 최신 Android 런처: 내장 회교식/양력 달력, 홈 화면 메모, 자동 앱 분류, 휴지통, 민감한 앱 숨기기.",
    "r30_sub": "급여 및 예산 관리 — Flutter",
    "r30_desc": "스마트 오프라인 우선 예산 앱: 자동 50/30/20 배포, 동적 일일 예산, 저축 과제, 자선 섹션, 차트(fl_chart) 및 월별 재무 달력 — 6가지 지원 플랫폼.",
    "pomo_sub": "Pomodoro 생산성 타이머 — Flutter",
    "pomo_desc": "Pomodoro 기술을 사용한 작업/휴식 세션 관리: 사용자 정의 가능한 일일 및 주간 목표, 사운드 알림, 다양한 테마 및 Linux 패키지(Flatpak / .desktop) — 5개 플랫폼에서 실행됩니다.",
    "lm_sub": "워터마크 비디오 생성기 — Flutter + FFmpeg",
    "lm_desc": "입력 비디오 없이 애니메이션 텍스트 워터마크가 있는 MP4 비디오를 생성합니다. Android 및 Windows에서 FFmpeg를 통해 내보낸 전체 발음 구별 부호를 지원하는 Flutter Canvas 엔진을 사용하여 높은 정확도로 렌더링된 아랍어 텍스트입니다.",
    "roms_small": "운영 체제",
    "roms_title": "🤖 소스에서 맞춤형 Android ROM 구축",
    "roms_desc": "전체 AOSP ROM은 커널 튜닝, 기기 트리 설정, 공급업체 Blob 관리를 통해 소스에서 빌드됩니다.",
    "rom1_desc": "Evolution X 레이어, 사용자 지정 커널 조정 및 장치 트리, HAL 수정 및 카메라 설정, Xiaomi 하드웨어의 Pixel 경험을 통해 소스에서 전체 AOSP 빌드를 제공합니다.",
    "rom2_desc": "AOSP Android 16은 Infinity X 기능, 커널 및 기기 트리 조정, 공급업체 Blob 및 HAL 관리 기능을 갖춘 소스에서 빌드됩니다.",
    "rom3_desc": "커널 컴파일, 장치 트리 설정 및 공급업체 Blob 추출을 통해 소스에서 PixelOS를 빌드합니다. 이는 Motorola 하드웨어에서 깔끔한 Pixel 환경을 제공합니다.",
    "rom4_desc": "Google 서비스(GApps) 없이 바닐라 빌드 - 동일한 기기에서 100% 순수 AOSP 경험을 제공합니다.",
    "rom4_tag3": "GApp 없음",
    "rom5_desc": "정기적인 보안 업데이트가 포함된 안정적이고 가벼운 오픈 소스 ROM인 Moto G54 5G용 공식 LineageOS 23.2 ROM을 유지 관리하고 구축합니다.",
    "rom5_tag2": "오픈 소스",
    "rom5_tag3": "보안 업데이트",
