    "haris_sub": "YouTube 콘텐츠 필터 및 포커스 확장 — TypeScript + WXT",
    "haris_desc": "채널 허용 목록, Shorts 차단기, 40개 이상의 언어를 지원하는 로컬 우선 아키텍처를 통해 YouTube를 깔끔하고 집중적인 학습 환경으로 변화시키는 오픈소스, 개인 정보 보호 우선 크로스 브라우저 확장 프로그램입니다.",
    "miqyas_sub": "앱 아이콘 안전 지대 스튜디오 및 매장 모형 — Flutter",
    "miqyas_desc": "개발자가 모든 플랫폼에서 66×66 안전 지대 내에서 앱 아이콘을 정확하게 정렬할 수 있는 대화형 스튜디오로, Google Play 및 App Store용 실시간 다중 기기 모형 미리보기와 자동화된 스토어 스크린샷 생성기를 제공합니다.",
    "mufarrigh_sub": "스프라이트 시트 추출기 및 배경 제거기 — Flutter + Dart Vision",
    "mufarrigh_desc": "순수 Dart 엔진, BFS Flood-Fill, 적응형 3창 UI 및 일괄 내보내기를 통한 간격 침식을 사용하여 스프라이트 시트를 분할하고 배경을 제거하는 스마트 데스크톱 및 모바일 도구입니다.",
    "tips_small": "가이드, 통찰력 및 솔루션",
    "tips_title": "💡 기술 팁 및 솔루션",
    "tips_desc": "개발 및 시스템 관리 중에 얻은 실용 가이드, 문제 해결 통찰력 및 자동화 도구입니다.",
    "tip1_badge": "Flutter 빌드 경고 및 수정",
    "tip1_title": "버전 충돌을 방지하기 위해 Java 확장용 Gradle의 올바른 사용",
    "tip1_desc": "IDE(VS Code/Antigravity)에서 <b>Java용 Gradle</b> 확장을 활성화할 때 <b>Flutter</b> 프로젝트에 여러 Gradle 버전 또는 모듈이 포함되어 있는 경우 확장 프로그램은 각각을 독립적으로 검색하고 빌드하려고 시도합니다. 이로 인해 버전 불일치 오류(예: <code>지원되는 최소 Gradle 버전은 9.6.0입니다. 현재 버전은 9.4.0</code>)가 발생하고 빌드 오류가 발생할 수 있습니다. 권장되는 접근 방식은 지원되는 작업 영역으로 확장 범위를 지정하거나 Flutter 하위 디렉터리에 대한 자동 심층 프로젝트 검색을 비활성화하는 것입니다.",
    "tip2_badge": "Linux 자동화 도구",
    "tip2_sub": "Linux 자동화 도구 — Bash + Arch Linux",
    "tip2_title": "Arch Linux용 Flutter 설치 프로그램 — 자동화된 SDK 설정",
    "tip2_desc": "Arch Linux에 안정적인 최신 Flutter SDK 설치를 자동화하는 Bash 스크립트: 공식 소스에서 자동으로 최신 릴리스를 가져오고, 세 가지 셸(Bash, Zsh 및 Fish)에 걸쳐 환경 변수를 구성하고, <code>archlinux-java</code>를 통해 한 단계로 최신 OpenJDK를 기본값으로 설정합니다.",
    "tip_img_tag": "📸 확장 프로그램 및 오류 스크린샷",
    "tip_vid_tag": "🎬 시연 영상",
