    "exp1_li3": "<b>RatilConvert</b> çêkir, ku <b>+715,463 tomarên xerîdar</b> ji Retail Pro hilanî û paqij kir û bi 100% lihevhatina Odoo ERP re hinarde kir - dema koça bi destan ji sedî 95 kêm kir.",
    "exp1_li4": "Diagrama torê ya laşî ya pargîdaniyê bi karanîna draw.io, tevî belavkirina serverê, dîwarê agir, guheztina bingehîn, û guhezên beşê, bi belgeyên tevnvîsê ve hatî sêwirandin.",
    "exp1_li5": "Karên lênêrînê û hardware hilgirt, KPI-yên bi navgîniya tabloyên înteraktîf vekolandin, û raporên PDF/Excel yên erebî yên profesyonel çêkirin.",
    "exp1_intro": "Di dema min de li pargîdaniyê, min pergalên nermalavê yên bêkêmasî yên ku rojane ji hêla şax û karmendan ve têne bikar anîn pêşve xistin: pergalek rêveberiya bilêtê ya piştgiriyê, platformek belavkirina nermalava navxweyî, û amûrek hilberandin û koçberiyê ya mezin - digel sêwirandin û belgekirina binesaziya torê û birêvebirina karên parastin û hardware.",
    "boycott_title": "🕊️ Boykota Teknîkî",
    "boycott_sub": "Prensîba Fermî û Helwesta Bingeha Baweriyê",
    "boycott_badge": "Prensîb & Helwest",
    "boycott_p1": "Wek <b>pisporê torê</b>, ez <b>Cisco</b>yê boykot dikim ji ber hevkarî û piştgirîya wan a kûr ji kujerên pêxember û zaliman re. Tevî ku ez pêbaweriyên pejirandî ji Cisco digirim, ez ji bo xatirê Xwedê bi kêfxweşî dev ji wan berdidim. Kî zirarê bide birayên min ên misilman, ez ê ji ber berjewendiya xwe jî dev jê berdim, ji ber ku rizqê me li ser Xwedayê xwebexş û pesindar e.",
    "boycott_p2": "<b>Ez van pargîdaniyan boykot dikim, lê em ê çawa sûdê ji vê yekê zêde bikin?</b><br>Dema ku ez li pargîdaniyek xebitîm ku min alîkariya danîna databasan kir, min dev ji danîn û karanîna <b>Oracle</b>-yê berda da ku piştgirî nekim. Ger yek xeletiyek sivik bike, jê ders werdigire; Heya ku di her fîrmayekê de bandora min a destan an teknîkî hebe, ez tenê teknolojiyên ku bi xwîna birayên me dirijînin piştgirî nakim bikar tînim û rizqê min li ser Xwedê ye.",
    "boycott_p3": "Hemd ji Allah re, îro her teknolojiyek alternatîfek azad û serbixwe heye.. û hûnê ji vê jîyana demborî derkevin (îdî ji Xwedê bitirsin).",
    "cisco_title": "Cisco",
    "cisco_sub": "Binesaziya Tora & Hardware",
    "cisco_desc": "Delîlên belgekirî yên hevpariya Cisco - bi karanîna tîran di nav slaytan de rêve bibin:",
    "ms_title": "Microsoft",
    "ms_sub": "Pergal & Cloud Computing",
    "ms_desc": "Helwesta dîrokî ya endezyarê nermalavê Ibtehal Ebu Al-Saad li dijî hevkariyê, û delîlên belgekirî:",
    "oracle_title": "Oracle",
    "oracle_sub": "Databases & Enterprise Cloud",
    "oracle_desc": "Belgekirina tevkariya pargîdanî, û pabendbûna bi alternatîfên çavkaniya vekirî (wek PostgreSQL û MariaDB):",
    "boycott_tip": "<b>Şêwirmendî ji bo kesên mecbûrî:</b> Ger kesek neçar be ku hilberek ji saziyek boykotkirî bikire ku alternatîfek tune ye, wê bikire <b>destê duyemîn / bikar anîn</b> da ku pargîdanî qezenca nû ya sifir werbigire. Hemd ji Xweda re ye û em xwe dispêrin wî.",
    "proj_small": "Portfolio",
    "proj_title": "🛠️ Projeyên Nermalavê",
    "proj_desc": "Projeyên rastîn, qedandî yên ku li ser GitHub têne weşandin - ji pergalên rêveberiya pargîdaniyê bigire heya amûrên hilberîna sermaseyê û mobîl.",
    "grp_company": "🏢 Projeyên Pargîdaniya Almajarah",
    "grp_company_cnt": "3 proje",
    "grp_personal": "👤 Projeyên Kesane - Li GitHub têne weşandin",
    "grp_personal_cnt": "9 proje",
    "casedesk_sub": "Pergala rêveberiya bilêtê ya piştgiriya IT - Flutter Desktop",
    "casedesk_desc": "Pergala Maseya Alîkariyê ya bêkêmasî ya ji bo şax û karmendan: Hevdengkirina ewr a Offline-Yekemîn, tabloya analîtîka KPI-ya înteraktîf, raporên PDF/Excel-a Erebî, oto-dagirtina bilêta biaqil, û agahdariya WhatsApp.",
    "ratil_sub": "Retail Pro → Koçkirina daneya ERP Odoo",
    "ratil_desc": "Pêvajo û paqij kirin <b>+715,463 tomarên xerîdar</b> bi algorîtmayên paqijkirina jîr û pêvajoyek paralel (Dart Isolates) bêyî cemidandina UI - 100% rastbûn û 95% kêmtir dema koça destan.",
    "itsc_sub": "Platforma belavkirina nermalava navxweyî ji bo pargîdaniyan",
    "itsc_desc": "Serlêdana Enterprise ji bo belavkirina nermalava pejirandî di hundurê tora pargîdaniyê de: rêveberê dakêşanê bi pêşkeftina zindî (Dio), vedîtina nûvekirina otomatîkî bi nîşana anîmasyon, piştgirîya Erebî/Îngilîzî û moda tarî (Materyal 3).",
    "tpc_sub": "Parçebûna vîdyoyê - Electron.js + FFmpeg",
    "tpc_desc": "Serlêdana sermaseyê ji bo dabeşkirina vîdyoyan (1/2/3 hûrdem an nîv) bi 100% qalîteya bê windahî bi riya Stream Copy, bi tespîtkirina GPU-ya otomatîk û UI-ya Glassmorphismê ya nûjen. Li ser Windows, Linux û macOS-ê dixebite.",
    "ts_sub": "Rahênerê leza nivîsandinê - Electron.js",
    "ts_desc": "Rahênerê tîpguhêzkirina cross-platformê bi piştgiriya tam RTL (Erebî/Îbranî/Farisî), WPM û statîstîkên hûrgulî, bi zorê rawestandina xeletiyê ji bo avakirina bîranîna masûlkeyê, kurtebirên gerdûnî û pelika pergalê.",
    "nui_sub": "Destpêker Android - Kotlin + Jetpack Compose",
    "nui_desc": "Destpêkera nûjen a Android-ê bi mîmariya MVVM û DB-ya Odeyê: salnameya Hîcrî/Gregorî ya çêkirî, nîşeyên li ser ekrana malê, kategorîzekirina otomatîkî ya sepanê, çop û sepanên hesas vedişêrin.",
    "r30_sub": "Rêvebiriya mûçe û budceyê - Flutter",
    "r30_desc": "Serlêdana budceya Smart Offline-Yekemîn: belavkirina otomatîkî 50/30/20, budceya rojane ya dînamîkî, kêşeyên teserûfê, beşa xêrxwaziyê, nexşe (fl_chart), û salnameyek darayî ya mehane - şeş platformên piştgirî.",
    "pomo_sub": "Demjimêra hilberîna Pomodoro - Flutter",
    "pomo_desc": "Bi teknîka Pomodoro re rêveberiya danişînê kar/veqetîne: armancên rojane û heftane yên xwerû, hişyariyên deng, pir mijar, û pakêtên Linux (Flatpak / .desktop) - li ser 5 platforman dimeşîne.",
    "lm_sub": "Afirînerê vîdyoya Watermark - Flutter + FFmpeg",
    "lm_desc": "Vîdyoyên MP4 bi ava nîşana nivîsê ya anîmasyonî bêyî vîdyoyek têketinê çêdike: Nivîsa Erebî ya ku bi motora Flutter Canvas-ê bi pêbaweriya bilind ve bi piştgirîya bêkêmasî ya diyakrîtîk ve hatî çêkirin, bi FFmpeg-ê li ser Android û Windows-ê ve hatî şandin.",
    "roms_small": "Pergalên Xebatê",
    "roms_title": "🤖 Avakirina ROM-ên xwerû yên Android-ê ji Çavkaniyê",
    "roms_desc": "ROM-a tevahî ya AOSP ji çavkaniyê bi ahenga kernelê, sazkirina dara cîhazê, û rêveberiya blobê ya firoşkar ji çavkaniyê ava dike.",
    "rom1_desc": "AOSP-a tevahî ji çavkaniyê bi qata Evolution X, birêkûpêkkirina kernelê ya xwerû û dara cîhazê, rastkirina HAL û sazkirina kamerayê, û ezmûnek Pixel li ser hardware Xiaomi ji çavkaniyê ve hatî çêkirin.",
    "rom2_desc": "AOSP Android 16 ji çavkaniyê bi taybetmendiyên Infinity X, birêkûpêkkirina dara kernel û cîhazê, û blobên firoşkar û rêveberiya HAL-ê ji çavkaniyê ava dike.",
    "rom3_desc": "PixelOS ji çavkaniyê bi berhevkirina kernel, sazkirina dara cîhazê û derxistina blobên firoşkarê ji çavkaniyê ava dike - serpêhatiyek Pixel a paqij li ser hardware ya Motorola.",
    "rom4_desc": "Avakirina Vanilla bêyî karûbarên Google (GApps) - 100% ezmûnek AOSP ya paqij li ser heman cîhazê.",
    "rom4_tag3": "GApps tune",
    "rom5_desc": "Parastin û avakirina LineageOS 23.2 ROM-a fermî ya ji bo Moto G54 5G - ROM-ek çavkaniya vekirî ya sabît, sivik bi nûvekirinên ewlehiyê yên birêkûpêk.",
    "rom5_tag2": "Çavkaniya vekirî",
    "rom5_tag3": "Nûvekirinên Ewlekariyê",
