    "haris_sub": "Parzûna Naveroka YouTube & Berfirehkirina Focus - TypeScript + WXT",
    "haris_desc": "Pêşveçûnek gerok-çavkaniyek vekirî, yekem-nepenîtiyê ku YouTube-ê vediguherîne hawîrdorek fêrbûnê ya paqij û baldar bi navnîşa spî ya kanalê, astengkerên Kurtefîlman, û mîmariya yekem-ya herêmî ku 40+ zimanan piştgirî dike.",
    "miqyas_sub": "Îkona sepanê stûdyoya herêma ewle û mockupên hilanînê - Flutter",
    "miqyas_desc": "Studyoya înteraktîf ji bo pêşdebiran ku bi rasthatinî îkonên sepanê di nav devera ewle ya 66 × 66 de li seranserê hemî platforman li hev bikin, ku ji bo Google Play û App Store-ê pêşdîtinek mockup-a pir-cîhazek zindî û jeneratorê dîmenê dikana otomatîkî vedihewîne.",
    "mufarrigh_sub": "Derxistina pelê Sprite & rakirina paşîn - Flutter + Dart Vision",
    "mufarrigh_desc": "Amûra sermaseya zîrek û mobîl ku bi karanîna motorek Dart-Dart, BFS Flood-Fill, û erozyona valahiyê bi UI-ya 3-qane adapteyî û hinardekirina hevîrê pelên sprite perçe dike û paşxanan jê dike.",
    "tips_small": "Rêber, têgihiştin û çareserî",
    "tips_title": "💡 Serişteyên Teknîkî û Çareserî",
    "tips_desc": "Rêbernameyên pratîkî, nerînên çareserkirina pirsgirêkan, û amûrên otomasyonê yên ku di dema pêşkeftin û rêveberiya pergalê de hatine bidestxistin.",
    "tip1_badge": "Hişyarî û Rastkirina Flutter Build",
    "tip1_title": "Bikaranîna rast a Gradle ji bo dirêjkirina Java-yê ku pêşî li nakokiyên guhertoyê bigire",
    "tip1_desc": "Dema ku pêveka <b>Gradle ji bo Java</b> di IDE-ya xwe (VS Code / Antigravity) de çalak bike, heke projeya weya <b>Flutter</b> gelek guherto an modulên Gradle-yê hebin, pêvek hewl dide ku her yekê serbixwe kifş bike û ava bike. Ev dikare xeletiyên hevahengiya guhertoyê derxîne (mînak. <code> Guhertoya Gradle ya herî kêm 9.6.0 piştgirî ye. Guhertoya heyî 9.4.0</code> e) û bibe sedema têkçûna çêkirinê. Nêzîkatiya pêşniyarkirî berfirehkirina cîhên xebatê yên piştgirîkirî ye an jî neçalakkirina vedîtina projeya kûr a otomatîkî ji bo jêrderhênerên Flutter.",
    "tip2_badge": "Amûra Xweseriya Linux",
    "tip2_sub": "Amûra xweseriya Linux - Bash + Arch Linux",
    "tip2_title": "Installer Flutter ji bo Arch Linux - Sazkirina SDK-ya Xweser",
    "tip2_desc": "Skrîpta Bash ya ku sazkirina Flutter SDK-ya herî dawî ya stabîl li ser Arch Linux otomatîk dike: bixweber serbestberdana herî nû ji çavkaniya fermî digire, guhêrbarên hawîrdorê li sê pelan (Bash, Zsh, û Fish) mîheng dike, û OpenJDK-a herî dawî bi navgîniya <code>archlinux-java</code> di yek gavê de wekî xwerû destnîşan dike.",
    "tip_img_tag": "📸 Dîmena Berfireh & Çewtî",
