    "haris_sub": "YouTube સામગ્રી ફિલ્ટર અને ફોકસ એક્સ્ટેંશન — TypeScript + WXT",
    "haris_desc": "એક ઓપન-સોર્સ, ગોપનીયતા-પ્રથમ ક્રોસ-બ્રાઉઝર એક્સ્ટેંશન કે જે YouTube ને 40+ ભાષાઓને સપોર્ટ કરતી ચેનલ વ્હાઇટલિસ્ટિંગ, શોર્ટ્સ બ્લોકર અને સ્થાનિક-પ્રથમ આર્કિટેક્ચર સાથે સ્વચ્છ, કેન્દ્રિત શિક્ષણ વાતાવરણમાં પરિવર્તિત કરે છે.",
    "miqyas_sub": "એપ્લિકેશન આયકન સેફ-ઝોન સ્ટુડિયો અને સ્ટોર મોકઅપ્સ — ફ્લટર",
    "miqyas_desc": "Google Play અને App Store માટે લાઇવ મલ્ટિ-ડિવાઈસ મોકઅપ પ્રીવ્યૂ અને સ્વચાલિત સ્ટોર સ્ક્રીનશૉટ જનરેટર દર્શાવતા, તમામ પ્લેટફોર્મ પર 66×66 સેફ ઝોનની અંદર એપ આઇકોનને ચોક્કસ રીતે સંરેખિત કરવા વિકાસકર્તાઓ માટે ઇન્ટરેક્ટિવ સ્ટુડિયો.",
    "mufarrigh_sub": "સ્પ્રાઈટ શીટ એક્સ્ટ્રાક્ટર અને બેકગ્રાઉન્ડ રીમુવર — ફ્લટર + ડાર્ટ વિઝન",
    "mufarrigh_desc": "શુદ્ધ-ડાર્ટ એન્જિન, BFS ફ્લડ-ફિલ અને અનુકૂલનશીલ 3-પેન UI અને બેચ નિકાસ સાથે ગેપ ઇરોશનનો ઉપયોગ કરીને સ્પ્રાઈટ શીટ્સના ટુકડા કરવા અને બેકગ્રાઉન્ડને દૂર કરવા માટે સ્માર્ટ ડેસ્કટોપ અને મોબાઇલ ટૂલ.",
    "tips_small": "માર્ગદર્શિકાઓ, આંતરદૃષ્ટિ અને ઉકેલો",
    "tips_title": "💡 ટેક ટિપ્સ અને સોલ્યુશન્સ",
    "tips_desc": "પ્રાયોગિક માર્ગદર્શિકાઓ, મુશ્કેલીનિવારણ આંતરદૃષ્ટિ અને વિકાસ અને સિસ્ટમ વહીવટ દરમિયાન હસ્તગત ઓટોમેશન સાધનો.",
    "tip1_badge": "ફ્લટર બિલ્ડ ચેતવણી અને ઠીક કરો",
    "tip1_title": "સંસ્કરણ વિરોધાભાસને રોકવા માટે જાવા એક્સ્ટેંશન માટે ગ્રેડલનો યોગ્ય ઉપયોગ",
    "tip1_desc": "તમારા IDE (VS Code / Antigravity) માં <b>Gradle for Java</b> એક્સ્ટેંશનને સક્ષમ કરતી વખતે, જો તમારા <b>ફ્લટર</b> પ્રોજેક્ટમાં બહુવિધ ગ્રેડલ વર્ઝન અથવા મોડ્યુલ હોય, તો એક્સ્ટેંશન દરેકને સ્વતંત્ર રીતે શોધવા અને બનાવવાનો પ્રયાસ કરે છે. આ વર્ઝનની મેળ ખાતી ભૂલોને ટ્રિગર કરી શકે છે (દા.ત. <code>ન્યૂનતમ સપોર્ટેડ ગ્રેડલ વર્ઝન 9.6.0 છે. વર્તમાન વર્ઝન 9.4.0</code> છે) અને બિલ્ડ નિષ્ફળતાઓનું કારણ બને છે. ભલામણ કરેલ અભિગમ એ સપોર્ટેડ વર્કસ્પેસીસના એક્સ્ટેંશનને સ્કોપ કરી રહ્યો છે અથવા ફ્લટર સબડિરેક્ટરીઝ માટે સ્વચાલિત ડીપ પ્રોજેક્ટ શોધને અક્ષમ કરી રહ્યો છે.",
    "tip2_badge": "Linux ઓટોમેશન ટૂલ",
    "tip2_sub": "Linux ઓટોમેશન ટૂલ - Bash + Arch Linux",
    "tip2_title": "આર્ક લિનક્સ માટે ફ્લટર ઇન્સ્ટોલર — ઓટોમેટેડ SDK સેટઅપ",
    "tip2_desc": "Bash સ્ક્રિપ્ટ કે જે આર્ક Linux પર નવીનતમ સ્થિર ફ્લટર SDK ઇન્સ્ટોલ કરવાનું સ્વચાલિત કરે છે: આપમેળે સત્તાવાર સ્ત્રોતમાંથી નવીનતમ પ્રકાશન મેળવે છે, ત્રણ શેલ્સ (બાશ, Zsh અને માછલી) પર પર્યાવરણ ચલોને ગોઠવે છે, અને એક પગલામાં <code>archlinux-java</code> દ્વારા નવીનતમ OpenJDK ને ડિફોલ્ટ તરીકે સેટ કરે છે.",
    "tip_img_tag": "📸 એક્સ્ટેંશન અને એરર સ્ક્રીનશોટ",
