    "name_ar": "Hossam Hassan Majrashi",
    "role": "नेटवर्क स्पेशालिस्ट • फ्लटर आणि इलेक्ट्रॉन ॲप डेव्हलपर • IT सपोर्ट आणि सिस्टम्स",
    "lead": "मी कामाच्या वातावरणात दररोज वापरल्या जाणाऱ्या वास्तविक सॉफ्टवेअर सोल्यूशन्स तयार करतो: तिकीट व्यवस्थापन प्रणाली, बिग-डेटा प्रक्रिया साधने (+715K रेकॉर्ड), उत्पादकता ॲप्स आणि संपूर्ण Android ROM स्त्रोत पासून तयार करते. मी तांत्रिक समस्यांना प्रभावी सॉफ्टवेअर टूल्समध्ये बदलतो.",
    "cta_projects": "🚀 माझे प्रकल्प पहा",
