    "stat4": "समर्थन आणि प्रणालींमध्ये फील्ड अनुभवाचे महिने",
    "exp_small": "कामाचा अनुभव",
    "exp_title": "💼 सध्याची नोकरी",
    "exp1_title": "आयटी सपोर्ट / सिस्टम असिस्टंट — आयटी सपोर्ट आणि सिस्टम असिस्टंट",
    "exp1_co": "अल्माजराह कंपनी",
    "exp1_period": "फेब्रुवारी 2026 - ऑगस्ट 2026",
    "exp1_li1": "डिझाईन आणि विकसित <b>केसडेस्क</b>, शाखा आणि कर्मचाऱ्यांसाठी एक समर्थन तिकीट व्यवस्थापन प्रणाली — ड्युअल डेटाबेससह ऑफलाइन-फर्स्ट आर्किटेक्चर (PHP REST API द्वारे स्थानिक Hive + क्लाउड).",
    "exp1_li2": "ऑटोमॅटिक अपडेट डिटेक्शन आणि स्मार्ट डाउनलोड मॅनेजरसह कंपनी नेटवर्कमध्ये मंजूर सॉफ्टवेअर वितरित करण्यासाठी <b>IT सॉफ्टवेअर सेंटर</b> ॲप विकसित केले.",
    "exp1_li3": "बिल्ट <b>RatilConvert</b>, ज्याने रिटेल प्रो कडून <b>+715,463 ग्राहक रेकॉर्ड</b> प्रक्रिया आणि साफ केले आणि त्यांना Odoo ERP वर 100% सुसंगततेसह निर्यात केले — मॅन्युअल स्थलांतर वेळ 95% कमी करा.",
    "exp1_li4": "संपूर्ण नेटवर्क दस्तऐवजीकरणासह सर्व्हर वितरण, फायरवॉल, कोअर स्विच आणि डिपार्टमेंट स्विचेससह draw.io वापरून कंपनीचे भौतिक नेटवर्क आकृती डिझाइन केले.",
    "exp1_li5": "देखभाल आणि हार्डवेअर कार्ये हाताळली, परस्पर डॅशबोर्डद्वारे KPI चे विश्लेषण केले आणि व्यावसायिक अरबी PDF/Excel अहवाल व्युत्पन्न केले.",
    "exp1_intro": "माझ्या कंपनीत असताना, मी शाखा आणि कर्मचाऱ्यांद्वारे दररोज वापरल्या जाणाऱ्या संपूर्ण सॉफ्टवेअर सिस्टम विकसित केल्या: एक सपोर्ट तिकीट व्यवस्थापन प्रणाली, अंतर्गत सॉफ्टवेअर वितरण प्लॅटफॉर्म, आणि एक बिग-डेटा प्रक्रिया आणि स्थलांतर साधन — नेटवर्क पायाभूत सुविधांचे डिझाइन आणि दस्तऐवजीकरण आणि देखभाल आणि हार्डवेअर कार्ये हाताळण्यासोबत.",
    "boycott_title": "🕊️ तांत्रिक बहिष्कार",
    "boycott_sub": "ठाम तत्त्व आणि विश्वासावर आधारित भूमिका",
    "boycott_badge": "तत्त्व आणि भूमिका",
    "boycott_p1": "एक <b>नेटवर्क विशेषज्ञ</b> म्हणून, मी <b>Cisco</b> वर बहिष्कार टाकतो कारण ते संदेष्टे आणि अत्याचार करणाऱ्यांच्या मारेकऱ्यांना त्यांच्या सखोल सहभागामुळे आणि समर्थनामुळे. सिस्कोकडून प्रमाणित क्रेडेन्शियल्स असूनही, अल्लाहच्या फायद्यासाठी मी त्यांचा आनंदाने त्याग करतो. जो कोणी माझ्या मुस्लिम बांधवांना त्रास देईल, मी माझ्या वैयक्तिक हिताच्या खर्चावर देखील त्याग करीन - कारण आमचा उदरनिर्वाह अल्लाहवर आहे, जो स्वयंपूर्ण, स्तुत्य आहे.",
    "boycott_p2": "<b>मी या कॉर्पोरेशन्सवर बहिष्कार टाकतो, परंतु आम्ही याचा जास्तीत जास्त फायदा कसा मिळवू शकतो?</b><br>ज्या कंपनीत मी डेटाबेस तैनात करण्यास मदत केली तेथे काम करत असताना, त्यांना समर्थन देत नाही याची खात्री करण्यासाठी मी <b>Oracle</b> तैनात करणे किंवा वापरणे टाळले. एखाद्याने थोडीशी चूक केली तर ते त्यातून शिकतात; जोपर्यंत माझा कोणत्याही फर्ममध्ये हात किंवा तांत्रिक प्रभाव आहे, तोपर्यंत मी फक्त अशा तंत्रज्ञानाचा वापर करतो जे आपल्या बांधवांचे रक्त सांडणाऱ्यांना साथ देत नाहीत आणि माझा उदरनिर्वाह अल्लाहवर आहे.",
    "boycott_p3": "आणि अल्लाहची स्तुती असो, आज प्रत्येक तंत्रज्ञानाला एक स्वतंत्र आणि स्वतंत्र पर्याय आहे.. आणि या क्षणभंगुर जीवनातून तुम्ही निघून जाल (म्हणून अल्लाहला घाबरा).",
    "cisco_title": "सिस्को",
    "cisco_sub": "नेटवर्किंग इन्फ्रास्ट्रक्चर आणि हार्डवेअर",
    "cisco_desc": "सिस्कोच्या गुंतागुंतीचे दस्तऐवजीकरण केलेले पुरावे — बाण वापरून स्लाइड्सवर नेव्हिगेट करा:",
    "ms_title": "मायक्रोसॉफ्ट",
