    "oracle_title": "ओरॅकल",
    "oracle_sub": "डेटाबेस आणि एंटरप्राइझ क्लाउड",
    "oracle_desc": "कॉर्पोरेट गुंतागुंतीचे दस्तऐवजीकरण करणे, आणि मुक्त-स्रोत पर्यायांसाठी वचनबद्ध करणे (जसे की PostgreSQL आणि MariaDB):",
    "boycott_tip": "<b>सक्तीसाठी सल्ला:</b> जर एखाद्याला बहिष्कार टाकलेल्या घटकाकडून कोणतेही पर्याय उपलब्ध नसताना उत्पादन खरेदी करण्यास भाग पाडले गेले, तर ते <b>सेकंड-हँड/वापरले</b> खरेदी करा त्यामुळे कंपनीला शून्य नवीन नफा मिळतो. अल्लाहची स्तुती असो आणि आम्ही त्याच्यावर अवलंबून असतो.",
