    "casedesk_sub": "आयटी सपोर्ट तिकीट व्यवस्थापन प्रणाली — फ्लटर डेस्कटॉप",
    "casedesk_desc": "शाखा आणि कर्मचाऱ्यांसाठी संपूर्ण हेल्प डेस्क सिस्टम: ऑफलाइन-फर्स्ट क्लाउड सिंक, परस्पर KPI विश्लेषण डॅशबोर्ड, अरबी PDF/Excel अहवाल, स्मार्ट तिकीट ऑटो-फिल आणि WhatsApp सूचना.",
    "ratil_sub": "रिटेल प्रो → Odoo ERP डेटा स्थलांतर",
    "ratil_desc": "UI गोठविल्याशिवाय स्मार्ट क्लीनिंग अल्गोरिदम आणि समांतर प्रक्रिया (Dart Isolates) सह <b>+715,463 ग्राहक रेकॉर्ड</b> प्रक्रिया आणि साफ केले — 100% अचूकता आणि 95% कमी मॅन्युअल स्थलांतर वेळ.",
    "itsc_sub": "उपक्रमांसाठी अंतर्गत सॉफ्टवेअर वितरण प्लॅटफॉर्म",
    "itsc_desc": "कंपनी नेटवर्कमध्ये मंजूर सॉफ्टवेअर वितरित करण्यासाठी एंटरप्राइझ ॲप: थेट प्रगतीसह डाउनलोड व्यवस्थापक (Dio), ॲनिमेटेड बॅजसह स्वयंचलित अद्यतन शोध, अरबी/इंग्रजी समर्थन आणि गडद मोड (मटेरियल 3).",
    "tpc_sub": "व्हिडिओ स्प्लिटिंग — Electron.js + FFmpeg",
    "tpc_desc": "स्वयंचलित GPU डिटेक्शन आणि आधुनिक Glassmorphism UI सह, स्ट्रीम कॉपी द्वारे 100% दोषरहित गुणवत्तेत व्हिडिओ विभाजित करण्यासाठी डेस्कटॉप ॲप (1/2/3 मिनिटे किंवा अर्धवट). Windows, Linux आणि macOS वर चालते.",
