    "ts_desc": "संपूर्ण RTL समर्थनासह क्रॉस-प्लॅटफॉर्म टायपिंग ट्रेनर (अरबी/हिब्रू/पर्शियन), तपशीलवार WPM आणि अचूकता आकडेवारी, स्नायू मेमरी, जागतिक शॉर्टकट आणि सिस्टम ट्रे तयार करण्यासाठी त्रुटीवर सक्तीने थांबा.",
    "nui_sub": "Android लाँचर — Kotlin + Jetpack Compose",
