    "r30_sub": "पगार आणि बजेट व्यवस्थापन - फडफड",
    "r30_desc": "स्मार्ट ऑफलाइन-प्रथम बजेट ॲप: स्वयंचलित 50/30/20 वितरण, डायनॅमिक दैनिक बजेट, बचत आव्हाने, धर्मादाय विभाग, चार्ट (fl_chart), आणि मासिक आर्थिक कॅलेंडर — सहा समर्थित प्लॅटफॉर्म.",
