    "roms_desc": "पूर्ण AOSP ROM कर्नल ट्यूनिंग, डिव्हाइस ट्री सेटअप आणि व्हेंडर ब्लॉब व्यवस्थापनासह स्त्रोतापासून तयार करते.",
    "rom1_desc": "Evolution X लेयर, कस्टम कर्नल ट्युनिंग आणि डिव्हाईस ट्री, HAL फिक्सेस आणि कॅमेरा सेटअप आणि Xiaomi हार्डवेअरवर Pixel अनुभवासह स्त्रोतापासून संपूर्ण AOSP बिल्ड.",
    "rom2_desc": "AOSP Android 16 Infinity X वैशिष्ट्ये, कर्नल आणि डिव्हाइस ट्री ट्यूनिंग आणि व्हेंडर ब्लॉब आणि HAL व्यवस्थापनासह स्त्रोतापासून तयार केले आहे.",
    "rom3_desc": "पिक्सेलओएस कर्नल संकलन, डिव्हाइस ट्री सेटअप आणि व्हेंडर ब्लॉब एक्सट्रॅक्शनसह स्त्रोतापासून तयार करते — मोटोरोला हार्डवेअरवर पिक्सेलचा स्वच्छ अनुभव.",
