    "haris_sub": "YouTube सामग्री फिल्टर आणि फोकस विस्तार — TypeScript + WXT",
    "haris_desc": "एक मुक्त-स्रोत, गोपनीयता-प्रथम क्रॉस-ब्राउझर विस्तार जो YouTube ला चॅनल व्हाइटलिस्टिंग, शॉर्ट्स ब्लॉकर आणि 40+ भाषांना सपोर्ट करणाऱ्या स्थानिक-प्रथम आर्किटेक्चरसह स्वच्छ, केंद्रित शिक्षण वातावरणात बदलतो.",
    "miqyas_sub": "ॲप आयकॉन सेफ-झोन स्टुडिओ आणि स्टोअर मॉकअप — फ्लटर",
    "miqyas_desc": "Google Play आणि App Store साठी लाइव्ह मल्टी-डिव्हाइस मॉकअप पूर्वावलोकन आणि स्वयंचलित स्टोअर स्क्रीनशॉट जनरेटर वैशिष्ट्यीकृत, सर्व प्लॅटफॉर्मवर 66×66 सुरक्षित क्षेत्रामध्ये ॲप चिन्हे अचूकपणे संरेखित करण्यासाठी विकसकांसाठी परस्परसंवादी स्टुडिओ.",
    "mufarrigh_sub": "स्प्राइट शीट एक्स्ट्रॅक्टर आणि बॅकग्राउंड रिमूव्हर — फ्लटर + डार्ट व्हिजन",
    "mufarrigh_desc": "शुद्ध-डार्ट इंजिन, BFS फ्लड-फिल आणि अडॅप्टिव्ह 3-पेन UI आणि बॅच एक्सपोर्टसह गॅप इरोशन वापरून स्प्राईट शीट्सचे तुकडे करण्यासाठी आणि पार्श्वभूमी काढण्यासाठी स्मार्ट डेस्कटॉप आणि मोबाइल टूल.",
    "tips_small": "मार्गदर्शक, अंतर्दृष्टी आणि उपाय",
    "tips_title": "💡 तांत्रिक टिपा आणि उपाय",
    "tips_desc": "व्यावहारिक मार्गदर्शक, समस्यानिवारण अंतर्दृष्टी आणि विकास आणि सिस्टम प्रशासनादरम्यान प्राप्त केलेली ऑटोमेशन साधने.",
    "tip1_badge": "फ्लटर बिल्ड चेतावणी आणि निराकरण",
    "tip1_title": "आवृत्ती संघर्ष टाळण्यासाठी Java विस्तारासाठी Gradle चा योग्य वापर",
    "tip1_desc": "तुमच्या IDE (VS Code / Antigravity) मध्ये <b>Gradle for Java</b> विस्तार सक्षम करताना, तुमच्या <b>Flutter</b> प्रोजेक्टमध्ये अनेक Gradle आवृत्त्या किंवा मॉड्यूल असल्यास, विस्तार प्रत्येक स्वतंत्रपणे शोधण्याचा आणि तयार करण्याचा प्रयत्न करतो. हे आवृत्ती जुळत नसलेल्या त्रुटी ट्रिगर करू शकते (उदा. <code>किमान समर्थित ग्रेडल आवृत्ती 9.6.0 आहे. वर्तमान आवृत्ती 9.4.0</code> आहे) आणि बिल्ड अयशस्वी होऊ शकते. शिफारस केलेला दृष्टीकोन समर्थित वर्कस्पेसेसच्या विस्ताराला स्कोप करणे किंवा फ्लटर सबडिरेक्टरीजसाठी स्वयंचलित डीप प्रोजेक्ट शोध अक्षम करणे आहे.",
    "tip2_badge": "लिनक्स ऑटोमेशन टूल",
