    "boycott_p1": "Als <b>netwerkspecialist</b> boycot ik <b>Cisco</b> vanwege hun diepe medeplichtigheid en steun aan de moordenaars van profeten en onderdrukkers. Ondanks dat ik in het bezit ben van gecertificeerde referenties van Cisco, doe ik er graag afstand van ter wille van Allah. Wie mijn moslimbroeders ook maar schaadt, ik zal afstand doen, zelfs als dat ten koste gaat van mijn persoonlijke belangen – want ons levensonderhoud is afhankelijk van Allah, de Zelfvoorzienende, de Prijzenswaardige.",
    "boycott_p2": "<b>Ik boycotte deze bedrijven, maar hoe kunnen we hier maximaal van profiteren?</b><br>Terwijl ik werkte bij een bedrijf waar ik hielp bij het implementeren van databases, vermeed ik het implementeren of gebruiken van <b>Oracle</b> om er zeker van te zijn dat ik ze niet ondersteunde. Als iemand een kleine fout maakt, leert hij ervan; Zolang ik een hand of technische invloed heb in welk bedrijf dan ook, gebruik ik alleen technologieën die degenen die het bloed van onze broeders vergieten niet ondersteunen, en mijn levensonderhoud ligt bij Allah.",
    "boycott_p3": "En alle lof zij Allah, vandaag de dag heeft elke technologie een gratis en onafhankelijk alternatief.. en uit dit vluchtige leven zul je vertrekken (vrees dus Allah).",
