    "casedesk_sub": "Ticketbeheersysteem voor IT-ondersteuning - Flutter Desktop",
    "casedesk_desc": "Compleet helpdesksysteem voor vestigingen en medewerkers: Offline-First cloudsynchronisatie, interactief KPI-analysedashboard, Arabische PDF/Excel-rapporten, automatisch invullen van smarttickets en WhatsApp-meldingen.",
    "ratil_sub": "Retail Pro → Odoo ERP-datamigratie",
    "ratil_desc": "<b>+715.463 klantrecords</b> verwerkt en opgeschoond met slimme opschoonalgoritmen en parallelle verwerking (Dart Isolates) zonder de gebruikersinterface te bevriezen — 100% nauwkeurigheid en 95% minder handmatige migratietijd.",
    "itsc_sub": "Intern softwaredistributieplatform voor ondernemingen",
    "itsc_desc": "Enterprise-app voor het distribueren van goedgekeurde software binnen het bedrijfsnetwerk: downloadmanager met live voortgang (Dio), automatische updatedetectie met geanimeerde badge, Arabisch/Engelse ondersteuning en donkere modus (Materiaal 3).",
    "tpc_sub": "Videosplitsen — Electron.js + FFmpeg",
    "tpc_desc": "Desktop-app voor het splitsen van video's (1/2/3 minuten of helften) met 100% verliesvrije kwaliteit via Stream Copy, met automatische GPU-detectie en een moderne Glassmorphism-gebruikersinterface. Draait op Windows, Linux en macOS.",
    "ts_sub": "Typesnelheidstrainer — Electron.js",
    "ts_desc": "Cross-platform typetrainer met volledige RTL-ondersteuning (Arabisch/Hebreeuws/Perzisch), gedetailleerde WPM- en nauwkeurigheidsstatistieken, gedwongen stop bij fouten om spiergeheugen op te bouwen, globale snelkoppelingen en systeemvak.",
    "nui_sub": "Android-opstartprogramma — Kotlin + Jetpack Compose",
    "nui_desc": "Moderne Android-launcher met MVVM-architectuur en Room DB: ingebouwde Hijri/Gregoriaanse kalender, notities op het startscherm, automatische app-categorisatie, prullenbak en verbergen van gevoelige apps.",
    "r30_sub": "Salaris- en budgetbeheer — Flutter",
    "r30_desc": "Slimme Offline-First budget-app: automatische 50/30/20-verdeling, dynamisch dagbudget, spaaruitdagingen, liefdadigheidsgedeelte, grafieken (fl_chart) en een maandelijkse financiële kalender - zes ondersteunde platforms.",
    "pomo_sub": "Pomodoro-productiviteitstimer - Flutter",
    "pomo_desc": "Beheer van werk-/pauzesessies met de Pomodoro-techniek: aanpasbare dagelijkse en wekelijkse doelen, geluidswaarschuwingen, meerdere thema's en Linux-pakketten (Flatpak / .desktop) — draait op 5 platforms.",
    "lm_sub": "Watermerk-videogenerator — Flutter + FFmpeg",
    "lm_desc": "Genereert MP4-video's met een geanimeerd tekstwatermerk zonder enige invoervideo: Arabische tekst weergegeven met de Flutter Canvas-engine met hoge betrouwbaarheid en volledige ondersteuning voor diakritische tekens, geëxporteerd via FFmpeg op Android en Windows.",
    "roms_small": "Besturingssystemen",
    "roms_title": "🤖 Aangepaste Android-ROM's bouwen vanaf de bron",
    "roms_desc": "Volledig AOSP ROM wordt vanaf de bron opgebouwd met kerneltuning, apparaatboomconfiguratie en leveranciersblobbeheer.",
