    "tip1_badge": "Flutter Build-waarschuwing en oplossing",
    "tip1_title": "Correct gebruik van de Gradle voor Java-extensie om versieconflicten te voorkomen",
    "tip1_desc": "Wanneer u de <b>Gradle for Java</b>-extensie in uw IDE (VS Code / Antigravity) inschakelt en uw <b>Flutter</b>-project meerdere Gradle-versies of -modules bevat, probeert de extensie elke versie afzonderlijk te ontdekken en te bouwen. Dit kan fouten veroorzaken die niet overeenkomen met de versies (bijvoorbeeld <code>De minimaal ondersteunde Gradle-versie is 9.6.0. De huidige versie is 9.4.0</code>) en buildfouten veroorzaken. De aanbevolen aanpak is het beperken van de uitbreiding tot ondersteunde werkruimten of het uitschakelen van automatische diepgaande projectdetectie voor Flutter-submappen.",
