    "boycott_p2": "<b>Bojkotuję te korporacje, ale jak zmaksymalizować korzyści z tego?</b><br>Pracując w firmie, w której pomagałem wdrażać bazy danych, unikałem wdrażania lub korzystania z <b>Oracle</b>, aby mieć pewność, że ich nie wspiera. Jeśli ktoś popełni drobny błąd, wyciąga z niego naukę; tak długo jak mam rękę lub wpływ techniczny w jakiejkolwiek firmie, używam tylko technologii, które nie wspierają tych, którzy rozlewają krew naszych braci, a moje zaopatrzenie jest w rękach Allaha.",
    "boycott_p3": "I chwała Allahowi, dzisiaj każda technologia ma wolną i niezależną alternatywę.. i odejdziecie z tego ulotnego życia (więcej się bójcie Allaha).",
