    "tpc_sub": "Podział wideo — Electron.js + FFmpeg",
    "tpc_desc": "Aplikacja komputerowa do dzielenia filmów (1/2/3 minuty lub na pół) w 100% bezstratnej jakości za pomocą funkcji Stream Copy, z automatycznym wykrywaniem procesora graficznego i nowoczesnym interfejsem użytkownika Glassmorphism. Działa na systemach Windows, Linux i macOS.",
    "ts_sub": "Trener szybkości pisania — Electron.js",
    "ts_desc": "Wieloplatformowy trener pisania z pełną obsługą RTL (arabski/hebrajski/perski), szczegółowymi statystykami WPM i dokładności, wymuszonym zatrzymaniem w przypadku błędu w celu zbudowania pamięci mięśniowej, globalnymi skrótami i tacą systemową.",
    "nui_sub": "Program uruchamiający Androida — Kotlin + Jetpack Compose",
    "nui_desc": "Nowoczesny program uruchamiający Androida z architekturą MVVM i Room DB: wbudowany kalendarz hidżry/gregoriański, notatki na ekranie głównym, automatyczna kategoryzacja aplikacji, kosz na śmieci i ukrywanie wrażliwych aplikacji.",
    "r30_sub": "Zarządzanie wynagrodzeniami i budżetem — Flutter",
    "r30_desc": "Aplikacja budżetowa Smart Offline-First: automatyczna dystrybucja 50/30/20, dynamiczny budżet dzienny, wyzwania oszczędnościowe, sekcja charytatywna, wykresy (fl_chart) i miesięczny kalendarz finansowy – sześć obsługiwanych platform.",
    "pomo_sub": "Zegar produktywności Pomodoro — Flutter",
    "pomo_desc": "Zarządzanie sesjami pracy/przerwami za pomocą techniki Pomodoro: konfigurowalne cele dzienne i tygodniowe, alerty dźwiękowe, wiele motywów i pakiety Linux (Flatpak / .desktop) — działa na 5 platformach.",
    "lm_sub": "Generator wideo ze znakiem wodnym — Flutter + FFmpeg",
    "lm_desc": "Generuje filmy MP4 z animowanym tekstowym znakiem wodnym bez żadnego wejściowego wideo: tekst arabski renderowany za pomocą silnika Flutter Canvas z wysoką jakością i pełną obsługą znaków diakrytycznych, eksportowany za pośrednictwem FFmpeg na Androida i Windows.",
    "roms_small": "Systemy operacyjne",
    "roms_title": "🤖 Tworzenie niestandardowych ROM-ów dla Androida ze źródła",
    "roms_desc": "Pełna pamięć ROM AOSP tworzona ze źródła z dostrajaniem jądra, konfiguracją drzewa urządzeń i zarządzaniem obiektami blob dostawcy.",
    "rom1_desc": "Pełna kompilacja AOSP ze źródła z warstwą Evolution X, niestandardowym dostrojeniem jądra i drzewem urządzeń, poprawkami HAL i konfiguracją kamery oraz obsługą Pixel na sprzęcie Xiaomi.",
    "rom2_desc": "Kompilacja AOSP Android 16 ze źródła z funkcjami Infinity X, dostrajaniem jądra i drzewa urządzeń oraz zarządzaniem obiektami blob i HAL dostawców.",
    "rom3_desc": "Kompilacja PixelOS ze źródła z kompilacją jądra, konfiguracją drzewa urządzeń i wyodrębnianiem obiektów blob dostawcy — czyste doświadczenie Pixela na sprzęcie Motorola.",
    "rom4_desc": "Wersja waniliowa bez usług Google (GApps) — w 100% czyste doświadczenie AOSP na tym samym urządzeniu.",
    "rom4_tag3": "Brak GApps",
    "rom5_desc": "Utrzymywanie i budowanie oficjalnej pamięci ROM LineageOS 23.2 dla Moto G54 5G — stabilnej, lekkiej pamięci ROM o otwartym kodzie źródłowym z regularnymi aktualizacjami zabezpieczeń.",
    "rom5_tag2": "Otwarte źródło",
    "rom5_tag3": "Aktualizacje zabezpieczeń",
