    "haris_sub": "Filtr treści YouTube i rozszerzenie ostrości — TypeScript + WXT",
    "haris_desc": "Rozszerzenie do różnych przeglądarek o otwartym kodzie źródłowym, dbające o prywatność, które przekształca YouTube w czyste, skupione środowisko do nauki z białą listą kanałów, blokadą Shorts i architekturą zorientowaną na lokalnie, obsługującą ponad 40 języków.",
    "miqyas_sub": "Makiety studia i sklepu z ikoną bezpiecznej strefy — Flutter",
    "miqyas_desc": "Interaktywne studio dla programistów umożliwiające dokładne wyrównywanie ikon aplikacji w bezpiecznej strefie 66×66 na wszystkich platformach, obejmujące podgląd makiet na żywo na wielu urządzeniach oraz automatyczny generator zrzutów ekranu sklepów dla Google Play i App Store.",
    "mufarrigh_sub": "Ekstraktor arkuszy ikon i narzędzie do usuwania tła — Flutter + Dart Vision",
    "mufarrigh_desc": "Inteligentne narzędzie na komputery stacjonarne i urządzenia mobilne do dzielenia arkuszy ikonek i usuwania tła przy użyciu silnika typu Pure-Dart, BFS Flood-Fill i erozji szczelin z adaptacyjnym interfejsem użytkownika z trzema panelami i eksportem wsadowym.",
    "tips_small": "Przewodniki, spostrzeżenia i rozwiązania",
    "tips_title": "💡 Wskazówki i rozwiązania techniczne",
    "tips_desc": "Praktyczne przewodniki, informacje dotyczące rozwiązywania problemów i narzędzia automatyzacji zdobyte podczas programowania i administrowania systemami.",
    "tip1_badge": "Ostrzeżenie i naprawa Flutter Build",
    "tip1_title": "Prawidłowe użycie rozszerzenia Gradle dla Java, aby zapobiec konfliktom wersji",
    "tip1_desc": "Po włączeniu rozszerzenia <b>Gradle dla Java</b> w swoim IDE (VS Code / Antigravity), jeśli Twój projekt <b>Flutter</b> zawiera wiele wersji lub modułów Gradle, rozszerzenie próbuje odkryć i zbudować każdy z nich niezależnie. Może to powodować błędy niezgodności wersji (np. <code>Minimalna obsługiwana wersja Gradle to 9.6.0. Aktualna wersja to 9.4.0</code>) i powodować błędy kompilacji. Zalecanym podejściem jest określenie zakresu rozszerzenia dla obsługiwanych obszarów roboczych lub wyłączenie automatycznego głębokiego wykrywania projektów dla podkatalogów Flutter.",
    "tip2_badge": "Narzędzie do automatyzacji Linuksa",
    "tip2_sub": "Narzędzie do automatyzacji systemu Linux — Bash + Arch Linux",
    "tip2_title": "Instalator Flutter dla Arch Linux — automatyczna konfiguracja pakietu SDK",
    "tip2_desc": "Skrypt Bash, który automatyzuje instalację najnowszego stabilnego zestawu SDK Flutter na Arch Linux: automatycznie pobiera najnowszą wersję z oficjalnego źródła, konfiguruje zmienne środowiskowe w trzech powłokach (Bash, Zsh i Fish) i ustawia najnowszy OpenJDK jako domyślny poprzez <code>archlinux-java</code> w jednym kroku.",
