    "ratil_desc": "Au fost procesate și curățate <b>+715.463 de înregistrări ale clienților</b> cu algoritmi de curățare inteligenți și procesare paralelă (Dart Isolates) fără a îngheța interfața de utilizare — 100% precizie și 95% mai puțin timp de migrare manuală.",
    "itsc_sub": "Platformă internă de distribuție software pentru întreprinderi",
    "itsc_desc": "Aplicație Enterprise pentru distribuirea software-ului aprobat în rețeaua companiei: manager de descărcare cu progres live (Dio), detectarea automată a actualizării cu insignă animată, suport arabă/engleză și modul întunecat (Material 3).",
    "tpc_sub": "Divizarea video — Electron.js + FFmpeg",
    "tpc_desc": "Aplicație desktop pentru împărțirea videoclipurilor (1/2/3 minute sau jumătate) la o calitate 100% fără pierderi prin Stream Copy, cu detectarea automată a GPU-ului și o interfață de utilizare Glassmorphism modernă. Rulează pe Windows, Linux și macOS.",
    "ts_sub": "Antrenor de viteză de tastare — Electron.js",
    "ts_desc": "Antrenor de tastare multiplatformă cu suport complet RTL (arabă/ebraică/persană), WPM detaliate și statistici de precizie, oprire forțată în caz de eroare pentru a construi memoria musculară, comenzi rapide globale și bara de sistem.",
    "nui_sub": "Lansator Android — Kotlin + Jetpack Compose",
    "nui_desc": "Lansator Android modern cu arhitectură MVVM și Room DB: calendar Hijri/Gregorian încorporat, note de pe ecranul de pornire, clasificare automată a aplicațiilor, coș de gunoi și ascunderea aplicațiilor sensibile.",
    "r30_sub": "Gestionarea salariilor și bugetului — Flutter",
    "r30_desc": "Aplicație inteligentă Offline-Primul buget: distribuție automată 50/30/20, buget zilnic dinamic, provocări de economisire, secțiune de caritate, diagrame (fl_chart) și un calendar financiar lunar - șase platforme acceptate.",
    "pomo_sub": "Temporizator de productivitate Pomodoro — Flutter",
    "pomo_desc": "Gestionarea sesiunilor de lucru/pauza cu tehnica Pomodoro: obiective personalizabile zilnice și săptămânale, alerte sonore, teme multiple și pachete Linux (Flatpak / .desktop) — rulează pe 5 platforme.",
    "lm_sub": "Generator video filigran — Flutter + FFmpeg",
    "lm_desc": "Generează videoclipuri MP4 cu un filigran de text animat fără niciun videoclip de intrare: text arab redat cu motorul Flutter Canvas la înaltă fidelitate cu suport complet pentru diacritice, exportat prin FFmpeg pe Android și Windows.",
    "roms_small": "Sisteme de operare",
