    "haris_desc": "O extensie pentru browsere cu sursă deschisă, care pune pe primul loc confidențialitatea, care transformă YouTube într-un mediu de învățare curat și concentrat, cu lista albă a canalelor, blocarea scurtăturilor și arhitectura locală, care acceptă peste 40 de limbi.",
    "miqyas_sub": "Pictogramă aplicație zone de siguranță studio și machete magazin — Flutter",
    "miqyas_desc": "Studio interactiv pentru dezvoltatori pentru a alinia cu precizie pictogramele aplicațiilor în zona de siguranță 66×66 pe toate platformele, oferind o previzualizare live a machetei pentru mai multe dispozitive și un generator automat de capturi de ecran pentru magazin pentru Google Play și App Store.",
