    "tip1_badge": "Flutter Build Warning & Fix",
    "tip1_title": "Utilizarea corectă a extensiei Gradle pentru Java pentru a preveni conflictele de versiuni",
    "tip1_desc": "Când activați extensia <b>Gradle pentru Java</b> în IDE (VS Code/Antigravity), dacă proiectul <b>Flutter</b> conține mai multe versiuni sau module Gradle, extensia încearcă să le descopere și să le construiască pe fiecare independent. Acest lucru poate declanșa erori de nepotrivire a versiunilor (de exemplu, <code>Versiunea Gradle minimă acceptată este 9.6.0. Versiunea actuală este 9.4.0</code>) și poate cauza erori de compilare. Abordarea recomandată este delimitarea extinderii la spațiile de lucru acceptate sau dezactivarea descoperirii profunde automate a proiectelor pentru subdirectoarele Flutter.",
    "tip2_badge": "Instrument de automatizare Linux",
