    "haris_sub": "Επέκταση φίλτρου και εστίασης περιεχομένου YouTube — TypeScript + WXT",
    "haris_desc": "Μια επέκταση πολλαπλού προγράμματος περιήγησης ανοιχτού κώδικα, πρώτης προστασίας απορρήτου που μετατρέπει το YouTube σε ένα καθαρό, εστιασμένο περιβάλλον εκμάθησης με λίστα επιτρεπόμενων καναλιών, πρόγραμμα αποκλεισμού Shorts και αρχιτεκτονική πρώτης τοπικής υποστήριξης που υποστηρίζει 40+ γλώσσες.",
