    "tips_small": "Οδηγοί, πληροφορίες και λύσεις",
    "tips_title": "💡 Τεχνικές συμβουλές και λύσεις",
    "tips_desc": "Πρακτικοί οδηγοί, πληροφορίες αντιμετώπισης προβλημάτων και εργαλεία αυτοματισμού που αποκτήθηκαν κατά την ανάπτυξη και τη διαχείριση συστημάτων.",
    "tip1_badge": "Flutter Build Προειδοποίηση & Διόρθωση",
    "tip1_title": "Σωστή χρήση της επέκτασης Gradle για Java για την αποφυγή διενέξεων εκδόσεων",
    "tip1_desc": "Όταν ενεργοποιείτε την επέκταση <b>Gradle για Java</b> στο IDE σας (VS Code / Antigravity), εάν το έργο σας <b>Flutter</b> περιέχει πολλές εκδόσεις ή λειτουργικές μονάδες Gradle, η επέκταση επιχειρεί να ανακαλύψει και να δημιουργήσει το καθένα ανεξάρτητα. Αυτό μπορεί να προκαλέσει σφάλματα αναντιστοιχίας έκδοσης (π.χ. <code>Η ελάχιστη υποστηριζόμενη έκδοση Gradle είναι 9.6.0. Η τρέχουσα έκδοση είναι 9.4.0</code>) και να προκαλέσει αποτυχίες κατασκευής. Η συνιστώμενη προσέγγιση είναι ο προσδιορισμός του εύρους της επέκτασης σε υποστηριζόμενους χώρους εργασίας ή η απενεργοποίηση της αυτόματης ανακάλυψης έργου σε βάθος για υποκαταλόγους Flutter.",
    "tip2_badge": "Εργαλείο αυτοματισμού Linux",
    "tip2_sub": "Εργαλείο αυτοματισμού Linux — Bash + Arch Linux",
    "tip2_title": "Πρόγραμμα εγκατάστασης Flutter για Arch Linux — Αυτόματη εγκατάσταση SDK",
    "tip2_desc": "Σενάριο Bash που αυτοματοποιεί την εγκατάσταση του πιο πρόσφατου σταθερού Flutter SDK στο Arch Linux: ανακτά αυτόματα την πιο πρόσφατη έκδοση από την επίσημη πηγή, ρυθμίζει τις μεταβλητές περιβάλλοντος σε τρία κελύφη (Bash, Zsh και Fish) και ορίζει το πιο πρόσφατο OpenJDK ως προεπιλογή μέσω <code>archlinux-java</code> σε ένα βήμα.",
