    "exp1_period": "ፌብሩዋሪ 2026 - ኦገስት 2026",
    "exp1_li1": "የተነደፈ እና የዳበረ <b>ኬዝ ዴስክ</b>፣ ለቅርንጫፎች እና ሰራተኞች የድጋፍ ትኬት አስተዳደር ስርዓት — ከመስመር ውጭ - የመጀመሪያ አርክቴክቸር ባለሁለት ዳታቤዝ (አካባቢያዊ ቀፎ + ደመና በ PHP REST APIs)።",
    "exp1_li2": "በኩባንያው አውታረመረብ ውስጥ የጸደቁ ሶፍትዌሮችን በራስ-ሰር የማዘመን ማወቂያ እና በስማርት አውርድ አስተዳዳሪ ለማሰራጨት <b>የአይቲ ሶፍትዌር ማዕከል</b> መተግበሪያ ሰራ።",
    "exp1_li3": "አብሮ የተሰራ <b>RatilConvert</b>፣<b>+715,463 የደንበኛ መዝገቦችን</b>ን ከችርቻሮ ፕሮቶኮል አጽድቶ በ100% ተኳሃኝነት ለኦዱ ኢአርፒ ወደ ውጭ የላካቸው - በእጅ የሚሰደዱበት ጊዜ በ95% ቀንሷል።",
    "exp1_li4": "የኩባንያውን አካላዊ አውታረ መረብ ዲያግራም draw.io በመጠቀም የነደፈው የአገልጋይ ስርጭትን፣ ፋየርዎልን፣ ኮር ማብሪያና ማጥፊያን እና የመምሪያውን መቀየሪያዎችን ከሙሉ የአውታረ መረብ ሰነዶች ጋር።",
    "exp1_li5": "የጥገና እና የሃርድዌር ስራዎችን ያዘ፣ KPIs በይነተገናኝ ዳሽቦርድ የተተነተነ እና ፕሮፌሽናል አረብ ፒዲኤፍ/ኤክሴል ሪፖርቶችን ፈጥሯል።",
    "exp1_intro": "በኩባንያው በነበርኩበት ጊዜ በቅርንጫፎች እና ሰራተኞች በየቀኑ የሚጠቀሙባቸውን ሙሉ የሶፍትዌር ስርዓቶችን አዳብሬአለሁ፡ የድጋፍ ትኬት አስተዳደር ስርዓት፣ የውስጥ ሶፍትዌር ማከፋፈያ መድረክ እና ትልቅ ዳታ ማቀናበሪያ እና ፍልሰት መሳሪያ - የኔትዎርክ መሠረተ ልማትን ከመንደፍ እና ከመመዝገብ እና የጥገና እና የሃርድዌር ስራዎችን ከማስተናገድ ጎን ለጎን።",
    "boycott_title": "🕊️ የቴክኒክ ቦይኮት",
