    "boycott_badge": "መርህ እና አቋም",
    "boycott_p1": "እንደ <b>የአውታረ መረብ ስፔሻሊስት</b>፣ ለነብያት እና ለጨቋኞች ገዳዮች ባላቸው ጥልቅ አጋርነት እና ድጋፍ የተነሳ <b>ሲስኮን አቋርጬ ነበር። ከሲስኮ የተመሰከረላቸው የትምህርት ማስረጃዎችን ቢይዝም ለአላህ ብዬ በደስታ እተወዋለሁ። ሙስሊም ወንድሞቼን የሚጎዳ ሰው እኔ የግል ጥቅሞቼን እንኳን ቢሆን እክዳለሁ - ሲሳይ ቻይና ምስጉኑ በኾነው አላህ ላይ ነው።",
    "boycott_p2": "<b>እነዚህን ኮርፖሬሽኖች አቋርጬያለሁ፣ ግን ከዚህ ጥቅማጥቅሞችን እንዴት ማሳደግ እንችላለን? አንድ ሰው ትንሽ ስህተት ከሠራ, ከእሱ ይማራሉ; በየትኛውም ድርጅት ውስጥ የእጄ ወይም የቴክኒካል ተጽእኖ እስካለኝ ድረስ የወንድሞቻችንን ደም የሚያፈሱትን የማይደግፉ ቴክኖሎጂዎችን ብቻ ነው የምጠቀመው እና ሲሳይ በአላህ ላይ ነው።",
    "boycott_p3": "እና ምስጋና ለአላህ ይገባው ዛሬ እያንዳንዱ ቴክኖሎጂ ነፃ እና ራሱን የቻለ አማራጭ አለው።",
