    "casedesk_sub": "የአይቲ ድጋፍ ቲኬት አስተዳደር ስርዓት - Flutter ዴስክቶፕ",
    "casedesk_desc": "የተሟላ የእገዛ ዴስክ ስርዓት ለቅርንጫፎች እና ሰራተኞች፡ ከመስመር ውጭ - የመጀመሪያው የደመና ማመሳሰል፣ በይነተገናኝ KPI ትንታኔ ዳሽቦርድ፣ አረብኛ ፒዲኤፍ/ኤክሴል ሪፖርቶች፣ ስማርት ቲኬት ራስ-ሙላ እና የዋትስአፕ ማሳወቂያዎች።",
