    "ts_sub": "የትየባ ፍጥነት አሰልጣኝ - Electron.js",
    "ts_desc": "የመድረክ አቋራጭ ትየባ አሰልጣኝ ከሙሉ የ RTL ድጋፍ ጋር (አረብኛ/ዕብራይስጥ/ፋርስኛ)፣ ዝርዝር WPM እና ትክክለኛነት ስታቲስቲክስ፣ የጡንቻ ማህደረ ትውስታን ለመገንባት በግድ በስህተት ማቆም፣ አለምአቀፍ አቋራጮች እና የስርዓት ትሪ።",
    "nui_sub": "አንድሮይድ አስጀማሪ — Kotlin + Jetpack ጻፍ",
    "nui_desc": "ዘመናዊ የአንድሮይድ አስጀማሪ ከ MVVM አርክቴክቸር እና ክፍል ዲቢ ጋር፡ አብሮገነብ ሂጅሪ/የግሪጎሪያን ካላንደር፣ የመነሻ ስክሪን ማስታወሻዎች፣ አውቶማቲክ መተግበሪያ ምደባ፣ የቆሻሻ መጣያ እና ስሱ መተግበሪያዎችን መደበቅ።",
    "r30_sub": "ደሞዝ እና የበጀት አስተዳደር - Flutter",
    "r30_desc": "ስማርት ከመስመር ውጭ-የመጀመሪያው የበጀት መተግበሪያ፡ አውቶማቲክ የ50/30/20 ስርጭት፣ ተለዋዋጭ ዕለታዊ በጀት፣ የቁጠባ ፈተናዎች፣ የበጎ አድራጎት ክፍል፣ ገበታዎች (fl_chart) እና ወርሃዊ የፋይናንሺያል የቀን መቁጠሪያ - ስድስት የሚደገፉ መድረኮች።",
    "pomo_sub": "የፖሞዶሮ ምርታማነት ጊዜ ቆጣሪ - ፍሉተር",
    "pomo_desc": "የስራ/እረፍት ክፍለ ጊዜ አስተዳደር በፖሞዶሮ ቴክኒክ፡ ሊበጁ የሚችሉ ዕለታዊ እና ሳምንታዊ ግቦች፣ የድምጽ ማንቂያዎች፣ በርካታ ገጽታዎች እና የሊኑክስ ፓኬጆች (Flatpak/.desktop) — በ5 መድረኮች ይሰራል።",
