    "lm_desc": "የኤምፒ 4 ቪዲዮዎችን ከአኒሜሽን የጽሑፍ ውሃ ማርክ ጋር ያለምንም የግቤት ቪዲዮ ያመነጫል፡ የአረብኛ ጽሁፍ በFlutter Canvas Engine በከፍተኛ ታማኝነት ከሙሉ ዲያክሪቲቲ ድጋፍ ጋር፣ በ FFmpeg በአንድሮይድ እና በዊንዶውስ ወደ ውጭ የተላከ።",
