    "rom3_desc": "PixelOS የሚገነባው ከምንጩ በከርነል ቅንብር፣ በመሳሪያው ዛፍ ማዋቀር እና በሻጭ ብሎብ ማውጣት - በMotorola ሃርድዌር ላይ ንጹህ የሆነ የPixel ተሞክሮ ነው።",
