    "haris_sub": "የዩቲዩብ የይዘት ማጣሪያ እና የትኩረት ቅጥያ — TypeScript + WXT",
    "haris_desc": "ክፍት ምንጭ፣ ግላዊነት-የመጀመሪያ አቋራጭ አሳሽ ዩቲዩብን ወደ ንፁህ ትኩረት የሚስብ የትምህርት አካባቢ በሰርጥ የተፈቀደላቸው ዝርዝር፣ ሾርትስ ማገጃ እና 40+ ቋንቋዎችን የሚደግፍ የአካባቢ-መጀመሪያ አርክቴክቸር።",
    "miqyas_sub": "የመተግበሪያ አዶ ደህንነቱ-ዞን ስቱዲዮ እና የሱቅ መሳለቂያዎች - ፍሉተር",
    "miqyas_desc": "ለገንቢዎች በ66×66 ደህንነቱ የተጠበቀ ዞን ውስጥ ያሉ የመተግበሪያ አዶዎችን በሁሉም መድረኮች ላይ በትክክል ለማሰለፍ ለገንቢዎች የቀጥታ ባለብዙ መሳሪያ የማስመሰል ቅድመ እይታ እና ለGoogle Play እና አፕ ስቶር አውቶማቲክ የሱቅ ቅጽበታዊ ገጽ እይታን ያሳያል።",
    "mufarrigh_sub": "Sprite ሉህ ማውጣት እና የጀርባ ማስወገጃ — ፍሉተር + ዳርት ራዕይ",
    "mufarrigh_desc": "ስማርት ዴስክቶፕ እና የሞባይል መሳሪያ የስፕሪት ሉሆችን ለመቆራረጥ እና ዳራዎችን በንጹህ-ዳርት ሞተር፣ BFS Flood-Fill እና ክፍተት መሸርሸርን በተመጣጣኝ ባለ 3-ፓን UI እና ባች ኤክስፖርት።",
    "tips_small": "መመሪያዎች፣ ግንዛቤዎች እና መፍትሄዎች",
    "tips_title": "💡 የቴክኖሎጂ ምክሮች እና መፍትሄዎች",
    "tips_desc": "በልማት እና በስርአት አስተዳደር ወቅት የተገኙ ተግባራዊ መመሪያዎች፣ መላ ፍለጋ ግንዛቤዎች እና አውቶሜሽን መሳሪያዎች።",
    "tip1_badge": "Flutter ግንባታ ማስጠንቀቂያ እና መጠገን",
    "tip1_title": "የስሪት ግጭቶችን ለመከላከል የGradle ለጃቫ ቅጥያ አስተካክል።",
    "tip1_desc": "በእርስዎ አይዲኢ (VS Code/Antigravity) ውስጥ የ<b>Gradle for Java</b> ቅጥያውን ሲያነቃ የ<b>Flutter</b> ፕሮጀክትዎ በርካታ የግራድል ስሪቶችን ወይም ሞጁሎችን ከያዘ፣ ቅጥያው እያንዳንዱን ለብቻው ለማግኘት እና ለመገንባት ይሞክራል። ይህ የስሪት አለመዛመድ ስህተቶችን ሊያስነሳ ይችላል (ለምሳሌ <code>የሚደገፈው ዝቅተኛው የ Gradle ስሪት 9.6.0 ነው። የአሁኑ ስሪት 9.4.0 ነው</code>) እና የግንባታ ውድቀቶችን ያስከትላል። የሚመከረው አካሄድ ማራዘሚያውን ወደሚደገፉ የስራ ቦታዎች ማካተት ወይም ለFlutter ንዑስ ማውጫዎች አውቶማቲክ ጥልቅ የፕሮጀክት ግኝትን ማሰናከል ነው።",
