    "miqyas_sub": "एप आइकन सेफ-जोन स्टुडियो र स्टोर मकअपहरू - फ्लटर",
    "miqyas_desc": "विकासकर्ताहरूका लागि अन्तरक्रियात्मक स्टुडियो सबै प्लेटफर्महरूमा 66×66 सुरक्षित क्षेत्र भित्र एप आइकनहरूलाई सही रूपमा पङ्क्तिबद्ध गर्न, लाइभ बहु-उपकरण मकअप पूर्वावलोकन र Google Play र एप स्टोरको लागि स्वचालित स्टोर स्क्रिनसट जेनेरेटरको विशेषता।",
