    "tips_desc": "व्यावहारिक गाइडहरू, समस्या निवारण अन्तर्दृष्टिहरू, र विकास र प्रणाली प्रशासनको समयमा प्राप्त स्वचालन उपकरणहरू।",
    "tip1_badge": "फ्लटर बिल्ड चेतावनी र समाधान",
    "tip1_title": "संस्करण द्वन्द्व रोक्न जाभा विस्तारको लागि Gradle को सही प्रयोग",
    "tip1_desc": "तपाईंको IDE (VS Code / Antigravity) मा <b>Gradle for Java</b> एक्स्टेन्सन सक्षम गर्दा, यदि तपाईंको <b>Flutter</b> परियोजनामा ​​धेरै Gradle संस्करण वा मोड्युलहरू छन् भने, विस्तारले प्रत्येकलाई स्वतन्त्र रूपमा खोज्ने र निर्माण गर्ने प्रयास गर्छ। यसले संस्करण बेमेल त्रुटिहरू ट्रिगर गर्न सक्छ (जस्तै <code>न्यूनतम समर्थित Gradle संस्करण 9.6.0 हो। हालको संस्करण 9.4.0</code> हो) र निर्माण असफल हुन सक्छ। सिफारिस गरिएको दृष्टिकोणले समर्थित कार्यस्थानहरूमा विस्तार स्कोप गर्दैछ वा फ्लटर उपनिर्देशिकाहरूको लागि स्वचालित गहिरो परियोजना खोज असक्षम पार्दैछ।",
    "tip2_badge": "लिनक्स स्वचालन उपकरण",
    "tip2_sub": "लिनक्स स्वचालन उपकरण - बास + आर्क लिनक्स",
    "tip2_title": "आर्क लिनक्सका लागि फ्लटर स्थापनाकर्ता — स्वचालित SDK सेटअप",
    "tip2_desc": "बास स्क्रिप्ट जसले आर्क लिनक्समा नवीनतम स्थिर फ्लुटर SDK स्थापना गर्न स्वचालित गर्छ: आधिकारिक स्रोतबाट स्वचालित रूपमा नयाँ रिलीज ल्याउँछ, तीनवटा शेलहरू (ब्याश, Zsh, र माछा) मा वातावरण चर कन्फिगर गर्दछ, र एक चरणमा <code>archlinux-java</code> मार्फत पछिल्लो OpenJDK लाई पूर्वनिर्धारित रूपमा सेट गर्दछ।",
    "tip_img_tag": "📸 विस्तार र त्रुटि स्क्रिनसट",
