    "exp1_li5": "Itọju abojuto ati awọn iṣẹ-ṣiṣe ohun elo, awọn KPI ti a ṣe atupale nipasẹ awọn dasibodu ibaraenisepo, ati ipilẹṣẹ awọn ijabọ Arabic PDF/Excel ọjọgbọn.",
    "exp1_intro": "Lakoko akoko mi ni ile-iṣẹ naa, Mo ṣe agbekalẹ awọn eto sọfitiwia pipe ti a lo lojoojumọ nipasẹ awọn ẹka ati awọn oṣiṣẹ: eto iṣakoso tikẹti atilẹyin, pẹpẹ ti pinpin sọfitiwia inu, ati ṣiṣe data nla & irinṣẹ ijira - lẹgbẹẹ apẹrẹ ati kikọ awọn amayederun nẹtiwọọki ati mimu itọju & awọn iṣẹ ṣiṣe ohun elo.",
    "boycott_title": "🕊️ Technical Boycott",
    "boycott_sub": "Ilana Iduroṣinṣin & Iduro ti o Da lori Igbagbọ",
    "boycott_badge": "Ilana & Iduro",
    "boycott_p1": "Gẹ́gẹ́ bí <b>Olóye nẹtiwọọki</b>, Mo kọ <b>Cisco</b> nítorí àkópọ̀ jinlẹ̀ wọn àti àtìlẹ́yìn fún àwọn apànìyàn àwọn wòlíì àti àwọn aninilára. Pelu idaduro awọn iwe-ẹri lati Sisiko, Mo fi ayọ kọ wọn silẹ nitori Allah. Ẹnikẹ́ni tí ó bá pa àwọn arákùnrin mi mùsùlùmí lára, èmi yóò kọ̀ sílẹ̀ kódà bí ó tilẹ̀ jẹ́ pé ohun tí mo ní lọ́kàn—nítorí oúnjẹ wa ń bẹ lọ́dọ̀ Allāhu, Olódodo, Onípẹ́.",
    "boycott_p2": "<b>Mo kọ awọn ile-iṣẹ wọnyi silẹ, ṣugbọn bawo ni a ṣe le mu anfani pọ si lati inu eyi?</b><br>Nigba ti a n ṣiṣẹ ni ile-iṣẹ kan nibiti MO ṣe iranlọwọ lati fi awọn ipamọ data ranṣẹ, Mo yago fun gbigbe tabi lilo <b>Oracle</b> lati rii daju pe ko ṣe atilẹyin wọn. Ti eniyan ba ṣe aṣiṣe diẹ, wọn kọ ẹkọ lati ọdọ rẹ; niwọn igba ti mo ba ni ọwọ tabi ipa imọ-ẹrọ ni eyikeyi ile-iṣẹ, imọ-ẹrọ nikan ni mo lo ti ko ṣe atilẹyin fun awọn ti o ta ẹjẹ awọn arakunrin wa silẹ, ati pe ohun elo mi wa fun Allah.",
    "boycott_p3": "Ati iyin fun Allah, loni gbogbo imọ-ẹrọ ni yiyan ọfẹ ati ominira .. ati pe lati igbesi aye igbafẹ yii iwọ yoo lọ kuro (nitorina bẹru Allah).",
