    "boycott_tip": "<b>Imọran fun ẹni ti a fipa mu:</b> Ti ẹnikan ba fi agbara mu lati ra ọja kan lati ile-iṣẹ ti o ti wa ni boycott lai si yiyan ti o wa, ra <b>ọwọ keji / lilo</b> nitorina ile-iṣẹ gba èrè tuntun odo. Ope ni fun Olohun atipe lowo re ni a gbekele.",
