    "casedesk_desc": "Eto Iduro Iranlọwọ pipe fun awọn ẹka ati awọn oṣiṣẹ: Aisinipo-Amuṣiṣẹpọ awọsanma akọkọ, dasibodu atupale KPI ibaraenisepo, awọn ijabọ ede PDF/Excel Arabic, kikun tikẹti smart, ati awọn iwifunni WhatsApp.",
    "ratil_sub": "Soobu Pro → Odoo ERP data ijira",
    "ratil_desc": "Ti ṣe ilana ati ti mọtoto <b>+715,463 awọn igbasilẹ alabara </b> pẹlu awọn algoridimu mimọ ti o gbọn ati sisẹ afiwera (Dart Isolates) laisi didi UI — 100% deede ati 95% kere si akoko ijira afọwọṣe.",
    "itsc_sub": "Ti abẹnu software pinpin Syeed fun katakara",
    "itsc_desc": "Ohun elo ile-iṣẹ fun pinpin sọfitiwia ti a fọwọsi laarin nẹtiwọọki ile-iṣẹ: oluṣakoso igbasilẹ pẹlu ilọsiwaju laaye (Dio), iṣawari imudojuiwọn adaṣe pẹlu baaji ere idaraya, atilẹyin Arabic/Gẹẹsi ati ipo dudu (ohun elo 3).",
    "tpc_sub": "Video yapa - Electron.js + FFmpeg",
    "tpc_desc": "Ohun elo Ojú-iṣẹ fun pipin awọn fidio (awọn iṣẹju 1/2/3 tabi halves) ni 100% didara ailagbara nipasẹ Daakọ ṣiṣan, pẹlu wiwa GPU aifọwọyi ati UI Glassmorphism ode oni. Ṣiṣẹ lori Windows, Linux ati MacOS.",
    "ts_sub": "Titẹ iyara olukọni - Electron.js",
    "ts_desc": "Olukọni titẹ iru ẹrọ agbelebu pẹlu atilẹyin RTL ni kikun (Larubawa/Heberu/Persian), alaye WPM ati awọn iṣiro deede, iduro ti a fi agbara mu lori aṣiṣe lati kọ iranti iṣan, awọn ọna abuja agbaye ati atẹ eto.",
    "nui_sub": "Ifilọlẹ Android - Kotlin + Jetpack Compose",
    "nui_desc": "Ifilọlẹ Android ode oni pẹlu faaji MVVM ati yara DB: ti a ṣe sinu Hijri/Kalẹnda Gregorian, awọn akọsilẹ iboju ile, isọri ohun elo aifọwọyi, apo idọti, ati fifipamọ awọn ohun elo ifura.",
    "r30_sub": "Ekunwo & isuna isakoso - Flutter",
    "r30_desc": "Aisinipo Smart - Ohun elo isuna akọkọ: pinpin aifọwọyi 50/30/20, isuna ojoojumọ ti o ni agbara, awọn italaya ifowopamọ, apakan ifẹ, awọn shatti (fl_chart), ati kalẹnda owo oṣooṣu - awọn iru ẹrọ atilẹyin mẹfa.",
    "pomo_sub": "Aago sise Pomodoro - Flutter",
    "pomo_desc": "Isakoso igba iṣẹ / isinmi pẹlu ilana Pomodoro: isọdi lojoojumọ ati awọn ibi-afẹde osẹ-sẹsẹ, awọn itaniji ohun, awọn akori pupọ, ati awọn idii Linux (Flatpak / .desktop) - nṣiṣẹ lori awọn iru ẹrọ 5.",
    "lm_sub": "Olupilẹṣẹ fidio Watermark - Flutter + FFmpeg",
