    "tip1_desc": "Nigbati o ba mu itẹsiwaju <b>Gradle fun Java</b> ṣiṣẹ ninu IDE rẹ (koodu VS / Antigravity), ti iṣẹ akanṣe <b>Flutter</b> rẹ ba ni awọn ẹya Gradle pupọ tabi awọn modulu, igbiyanju igbiyanju lati ṣawari ati kọ ọkọọkan ni ominira. Eyi le fa awọn aṣiṣe ibaamu ẹya (fun apẹẹrẹ <koodu> Ẹya Gradle ti o ni atilẹyin ti o kere ju jẹ 9.6.0. Ẹya lọwọlọwọ jẹ 9.4.0</code>) ati fa awọn ikuna kikọ. Ọna ti a ṣeduro ni yiyi itẹsiwaju si awọn aaye iṣẹ ti o ṣe atilẹyin tabi pa wiwa iṣẹ-ṣiṣe jinlẹ laifọwọyi fun awọn iwe-ipamọ Flutter.",
    "tip2_badge": "Ọpa Automation Linux",
    "tip2_sub": "Ọpa adaṣe Linux - Bash + Arch Linux",
    "tip2_title": "Insitola Flutter fun Arch Linux - Eto SDK adaṣe",
    "tip2_desc": "Iwe afọwọkọ Bash ti o ṣe adaṣe fifi sori ẹrọ iduroṣinṣin Flutter SDK tuntun lori Arch Linux: mu idasilẹ tuntun laifọwọyi lati orisun osise, tunto awọn oniyipada ayika kọja awọn ikarahun mẹta (Bash, Zsh, ati Fish), ati ṣeto OpenJDK tuntun bi aiyipada nipasẹ <koodu>archlinux-java </code> ni igbesẹ kan.",
