    "exp1_li1": "Dinisenyo at binuo ang <b>CaseDesk</b>, isang support ticket management system para sa mga sangay at empleyado — Offline-First architecture na may dalawahang database (lokal na Hive + cloud sa pamamagitan ng PHP REST API).",
