    "exp1_li3": "Binuo ang <b>RatilConvert</b>, na nagproseso at naglinis ng <b>+715,463 na mga rekord ng customer</b> mula sa Retail Pro at nag-export ng mga ito nang may 100% compatibility sa Odoo ERP — pinutol ang manu-manong oras ng paglipat ng 95%.",
    "exp1_li4": "Dinisenyo ang pisikal na network diagram ng kumpanya gamit ang draw.io, kabilang ang pamamahagi ng server, firewall, core switch, at mga switch ng departamento, na may buong dokumentasyon ng network.",
    "exp1_li5": "Pinangangasiwaan ang mga gawain sa pagpapanatili at hardware, sinuri ang mga KPI sa pamamagitan ng mga interactive na dashboard, at nakabuo ng mga propesyonal na Arabic PDF/Excel na ulat.",
    "exp1_intro": "Sa tagal ko sa kumpanya, nakabuo ako ng kumpletong software system na ginagamit araw-araw ng mga sangay at empleyado: isang support ticket management system, isang panloob na platform ng pamamahagi ng software, at isang big-data processing at migration tool — kasama ng pagdidisenyo at pagdodokumento ng network infrastructure at paghawak ng maintenance at hardware na mga gawain.",
    "boycott_title": "🕊️ Teknikal na Boycott",
