    "boycott_badge": "Prinsipyo at Paninindigan",
    "boycott_p1": "Bilang isang <b>espesyalista sa network</b>, bino-boykot ko ang <b>Cisco</b> dahil sa kanilang malalim na pakikipagsabwatan at suporta sa mga pumatay sa mga propeta at mapang-api. Sa kabila ng paghawak ng mga sertipikadong kredensyal mula sa Cisco, malugod kong tinatalikuran ang mga ito para sa kapakanan ng Allah. Sinuman ang makapinsala sa aking mga kapatid na Muslim, ako ay tatalikuran kahit na sa kapinsalaan ng aking mga pansariling kapakanan—sapagkat ang ating kabuhayan ay nasa Allah, ang Sapat sa Sarili, ang Kapuri-puri.",
    "boycott_p2": "<b>Bini-boykot ko ang mga korporasyong ito, ngunit paano natin mapakinabangan ang pakinabang mula rito?</b><br>Habang nagtatrabaho sa isang kumpanya kung saan tumulong ako sa pag-deploy ng mga database, iniwasan kong i-deploy o gamitin ang <b>Oracle</b> upang matiyak na hindi sila sinusuportahan. Kung ang isa ay gumawa ng isang maliit na pagkakamali, natututo sila mula dito; Hangga't mayroon akong kamay o teknikal na impluwensya sa anumang kumpanya, gumagamit lamang ako ng mga teknolohiya na hindi sumusuporta sa mga taong dumanak ang dugo ng ating mga kapatid, at ang aking kabuhayan ay nasa Allah.",
    "boycott_p3": "At purihin si Allah, ngayon ang bawat teknolohiya ay may libre at independiyenteng alternatibo.. at mula sa panandaliang buhay na ito ikaw ay lilisan (kaya matakot kay Allah).",
