    "tpc_sub": "Paghahati ng video — Electron.js + FFmpeg",
    "tpc_desc": "Desktop app para sa paghahati ng mga video (1/2/3 minuto o kalahati) sa 100% lossless na kalidad sa pamamagitan ng Stream Copy, na may awtomatikong GPU detection at modernong Glassmorphism UI. Gumagana sa Windows, Linux at macOS.",
    "ts_sub": "Tagasanay ng bilis ng pag-type — Electron.js",
