    "nui_sub": "Android launcher — Kotlin + Jetpack Compose",
    "nui_desc": "Modernong Android launcher na may MVVM architecture at Room DB: built-in na Hijri/Gregorian na kalendaryo, mga home-screen na tala, awtomatikong pagkakategorya ng app, trash bin, at pagtatago ng mga sensitibong app.",
    "r30_sub": "Pamamahala ng suweldo at badyet — Flutter",
    "r30_desc": "Smart Offline-First budget app: awtomatikong 50/30/20 na pamamahagi, dynamic na pang-araw-araw na badyet, mga hamon sa pagtitipid, charity section, mga chart (fl_chart), at isang buwanang kalendaryong pinansyal — anim na sinusuportahang platform.",
    "pomo_sub": "Timer ng pagiging produktibo ng Pomodoro — Kumawag",
    "pomo_desc": "Pamamahala ng work/break session gamit ang Pomodoro technique: nako-customize na pang-araw-araw at lingguhang layunin, sound alert, maraming tema, at Linux packages (Flatpak / .desktop) — tumatakbo sa 5 platform.",
    "lm_sub": "Watermark video generator — Flutter + FFmpeg",
