    "tip1_title": "Tamang paggamit ng Gradle para sa Java extension upang maiwasan ang mga salungatan sa bersyon",
    "tip1_desc": "Kapag pinapagana ang extension ng <b>Gradle para sa Java</b> sa iyong IDE (VS Code / Antigravity), kung ang iyong proyekto sa <b>Flutter</b> ay naglalaman ng maraming bersyon o module ng Gradle, sinusubukan ng extension na tuklasin at buuin ang bawat isa nang nakapag-iisa. Maaari itong mag-trigger ng mga error sa mismatch na bersyon (hal. <code>Minimum na sinusuportahang bersyon ng Gradle ay 9.6.0. Ang kasalukuyang bersyon ay 9.4.0</code>) at magdulot ng mga pagkabigo sa build. Ang inirerekomendang diskarte ay sumasaklaw sa extension sa mga sinusuportahang workspace o hindi pagpapagana ng awtomatikong pagtuklas ng malalim na proyekto para sa mga subdirectory ng Flutter.",
