    "exp1_li2": "အလိုအလျောက်အပ်ဒိတ်သိရှိနိုင်မှုနှင့် စမတ်ဒေါင်းလုဒ်မန်နေဂျာတို့နှင့်အတူ ကုမ္ပဏီကွန်ရက်အတွင်း အတည်ပြုထားသောဆော့ဖ်ဝဲကို ဖြန့်ဝေရန် <b>IT Software Center</b> အက်ပ်ကို တီထွင်ခဲ့သည်။",
    "exp1_li3": "Retail Pro မှ <b>+715,463 ဖောက်သည်မှတ်တမ်းများ</b> ကို စီမံပြီး ရှင်းထုတ်ပြီး Odoo ERP သို့ 100% လိုက်ဖက်ညီမှုဖြင့် ၎င်းတို့ကို တင်ပို့ရောင်းချသည့် <b>RatilConvert</b> ကို တည်ဆောက်ထားသည် — ကိုယ်တိုင် ပြောင်းရွှေ့ချိန်ကို 95% ဖြတ်ပါ။",
    "exp1_li4": "ဆာဗာဖြန့်ဖြူးမှု၊ firewall၊ core switch နှင့် department switches များအပါအဝင် draw.io ကိုအသုံးပြု၍ ကုမ္ပဏီ၏ရုပ်ပိုင်းဆိုင်ရာကွန်ရက်ပုံကြမ်းကို ကွန်ရက်စာရွက်စာတမ်းအပြည့်အစုံဖြင့် ဒီဇိုင်းရေးဆွဲခဲ့သည်။",
    "exp1_li5": "ပြုပြင်ထိန်းသိမ်းမှုနှင့် ဟာ့ဒ်ဝဲလုပ်ငန်းဆောင်တာများကို ကိုင်တွယ်ဆောင်ရွက်ခြင်း၊ အပြန်အလှန်အကျိုးပြုသော ဒက်ရှ်ဘုတ်များမှတစ်ဆင့် KPIs များကို ပိုင်းခြားစိတ်ဖြာပြီး ကျွမ်းကျင်သော အာရဗီ PDF/Excel အစီရင်ခံစာများကို ထုတ်ပေးပါသည်။",
    "exp1_intro": "ကုမ္ပဏီတွင်ရှိစဉ်အတွင်း၊ ဘဏ်ခွဲများနှင့် ဝန်ထမ်းများမှ နေ့စဉ်အသုံးပြုသော ဆော့ဖ်ဝဲလ်စနစ် အပြည့်အစုံ- ပံ့ပိုးမှုလက်မှတ်စီမံခန့်ခွဲမှုစနစ်၊ အတွင်းပိုင်းဆော့ဖ်ဝဲလ်ဖြန့်ဖြူးရေးပလပ်ဖောင်းနှင့် ကွန်ရက်အခြေခံအဆောက်အအုံကို ဒီဇိုင်းရေးဆွဲခြင်းနှင့် မှတ်တမ်းပြုစုခြင်းနှင့် ပြုပြင်ထိန်းသိမ်းခြင်းနှင့် ဟာ့ဒ်ဝဲလုပ်ငန်းတာဝန်များကို ကိုင်တွယ်ဆောင်ရွက်ခြင်းတို့နှင့်အတူ ပြီးပြည့်စုံသော ဆော့ဖ်ဝဲလ်စနစ်များကို တီထွင်ခဲ့သည်။",
    "boycott_title": "🕊️ နည်းပညာပိုင်းဆိုင်ရာ သပိတ်မှောက်ခြင်း။",
    "boycott_sub": "ခိုင်မာသောမူရင်းနှင့် ယုံကြည်ခြင်းအခြေခံရပ်တည်ချက်",
    "boycott_badge": "Principle & ရပ်တည်ချက်",
    "boycott_p1": "<b>ကွန်ရက်ကျွမ်းကျင်သူ</b>တစ်ဦးအနေဖြင့်၊ ကျွန်ုပ်သည် ပရောဖက်များနှင့် ဖိနှိပ်သူများ၏ လူသတ်သမားများအတွက် ၎င်းတို့၏ နက်နဲသောရှုပ်ထွေးမှုနှင့် ပံ့ပိုးမှုများကြောင့် <b>Cisco</b> ကို သပိတ်မှောက်ခဲ့သည်။ Cisco မှ အသိအမှတ်ပြု အထောက်အထားများ ကိုင်ဆောင်ထားသော်လည်း အလ္လာဟ်အရှင်မြတ်အတွက် ဝမ်းမြောက်ဝမ်းသာ စွန့်လွှတ်လိုက်ပါသည်။ မည်သူမဆို ကျွန်ုပ်၏ မွတ်စ်လင်မ် ညီအစ်ကိုများအား ထိခိုက်နစ်နာစေကာမူ ကျွန်ုပ်၏ ကိုယ်ရေးကိုယ်တာ အကျိုးစီးပွားကိုပင် စွန့်လွှတ်ပါမည်၊ အကြောင်းမူကား၊ ငါတို့၏ ဝမ်းစာသည် အလ္လာဟ်အရှင်မြတ်၏ ဖူလုံတော်မူသော အလ္လာဟ်အရှင်မြတ်အပေါ်၌ တည်ရှိနေသောကြောင့် ချီးမွမ်းထိုက်ပေ၏။",
    "boycott_p2": "<b>ကျွန်တော် ဒီကော်ပိုရေးရှင်းတွေကို သပိတ်မှောက်လိုက်ပေမယ့် ဒီကနေ ဘယ်လိုအကျိုးကျေးဇူးတွေ ရနိုင်မလဲ။</b><br>ဒေတာဘေ့စ်တွေ ဖြန့်ကျက်ဖို့ ကူညီပေးခဲ့တဲ့ ကုမ္ပဏီတစ်ခုမှာ အလုပ်လုပ်နေစဉ်၊ သူတို့ကို မထောက်ပံ့ဖို့ <b>Oracle</b> ကို အသုံးချခြင်း သို့မဟုတ် အသုံးချခြင်းတွေကို ရှောင်ရှားခဲ့တယ်။ အနည်းငယ် အမှားလုပ်မိပါက ယင်းမှ သင်ခန်းစာယူပါ။ ကျွန်ုပ်သည် မည်သည့်ကုမ္ပဏီတွင်မဆို လက် သို့မဟုတ် နည်းပညာလွှမ်းမိုးမှုရှိနေသရွေ့၊ ကျွန်ုပ်သည် ကျွန်ုပ်တို့၏ ညီအစ်ကိုများ၏ သွေးယိုဖိတ်သူများအား မထောက်ပံ့နိုင်သော နည်းပညာများကိုသာ အသုံးပြုပြီး ကျွန်ုပ်၏ ဝမ်းစာသည် အလ္လာဟ်အရှင်မြတ်အပေါ်၌ ရှိပါသည်။",
    "boycott_p3": "၎င်းပြင် အလ္လာဟ်အရှင်မြတ်အား ချီးမွမ်းပါလေ။ ယနေ့ နည်းပညာတိုင်းတွင် လွတ်လပ်၍ အမှီအခိုကင်းသော အခြားရွေးချယ်စရာများ ရှိလေသည်..၊ ဤခဏတာဘဝမှ အသင်တို့သည် ထွက်ခွာသွားကြရပေမည်။",
