    "casedesk_desc": "အကိုင်းအခက်များနှင့် ဝန်ထမ်းများအတွက် ပြီးပြည့်စုံသော Help Desk စနစ်- အော့ဖ်လိုင်း-ပထမ cloud ထပ်တူကျမှု၊ အပြန်အလှန်တုံ့ပြန်မှုရှိသော KPI ခွဲခြမ်းစိတ်ဖြာမှု ဒက်ရှ်ဘုတ်၊ အာရဗီ PDF/Excel အစီရင်ခံစာများ၊ စမတ်လက်မှတ် အလိုအလျောက်ဖြည့်သွင်းခြင်းနှင့် WhatsApp အကြောင်းကြားချက်များ။",
