    "haris_sub": "YouTube အကြောင်းအရာ စစ်ထုတ်ခြင်းနှင့် အာရုံစူးစိုက်မှု တိုးချဲ့မှု — TypeScript + WXT",
    "haris_desc": "YouTube သည် ချန်နယ်အဖြူရောင်စာရင်းသွင်းခြင်း၊ Shorts blocker နှင့် ဘာသာစကား 40+ ကျော်ကို ပံ့ပိုးပေးသော ဒေသန္တရပထမဗိသုကာပညာဖြင့် သန့်ရှင်းပြီး အဓိကထား သင်ယူမှုပတ်ဝန်းကျင်အဖြစ် ပြောင်းလဲပေးသည့် open-source၊ ကိုယ်ရေးကိုယ်တာ-ပထမ-ဘရောက်ဆာ တိုးချဲ့မှုတစ်ခု။",
    "miqyas_sub": "အက်ပ်သင်္ကေတ ဘေးကင်းသောဇုန် စတူဒီယိုနှင့် စတိုးဆိုင်ပုံစံများ — Flutter",
    "miqyas_desc": "ပလက်ဖောင်းအားလုံးရှိ 66 × 66 ဘေးကင်းသောဇုန်အတွင်း အက်ပ်အိုင်ကွန်များကို တိကျစွာချိန်ညှိရန် ဆော့ဖ်ဝဲအင်ဂျင်နီယာများအတွက် အပြန်အလှန်တုံ့ပြန်သောစတူဒီယိုသည် Google Play နှင့် App Store အတွက် စက်ပစ္စည်းပေါင်းများစွာကို တိုက်ရိုက်ပုံတူကူးယူကြည့်ရှုခြင်းနှင့် အလိုအလျောက်စတိုးဆိုင်စခရင်ပုံထုတ်ပေးသည့်စနစ်ပါရှိသည်။",
    "mufarrigh_sub": "Sprite စာရွက်ထုတ်ယူခြင်းနှင့် နောက်ခံဖယ်ရှားခြင်း — Flutter + Dart Vision",
    "mufarrigh_desc": "Pure-Dart အင်ဂျင်၊ BFS Flood-Fill နှင့် လိုက်လျောညီထွေရှိသော 3-pane UI နှင့် batch export တို့ဖြင့် sprite စာရွက်များကို လှီးဖြတ်ကာ နောက်ခံများကို ဖယ်ရှားရန် စမတ်ဒက်စ်တော့နှင့် မိုဘိုင်းတူးလ်တူးလ်။",
    "tips_small": "လမ်းညွှန်များ၊ ထိုးထွင်းအမြင်များနှင့် ဖြေရှင်းချက်များ",
    "tips_title": "💡 နည်းပညာဆိုင်ရာ အကြံပြုချက်များနှင့် ဖြေရှင်းချက်များ",
    "tips_desc": "ဖွံ့ဖြိုးတိုးတက်မှုနှင့် စနစ်များ စီမံအုပ်ချုပ်မှုအတွင်း ရရှိသော လက်တွေ့ကျသော လမ်းညွှန်ချက်များ၊ ထိုးထွင်းသိမြင်မှု ပြဿနာဖြေရှင်းခြင်းများနှင့် အလိုအလျောက်စနစ်ဆိုင်ရာ ကိရိယာများ။",
    "tip1_badge": "Flutter တည်ဆောက်မှုသတိပေးချက် & ပြင်ဆင်ပါ။",
    "tip1_title": "ဗားရှင်းကွဲလွဲမှုများကို ကာကွယ်ရန် Java extension အတွက် Gradle ကို မှန်ကန်စွာ အသုံးပြုခြင်း။",
    "tip1_desc": "သင်၏ IDE (VS Code / Antigravity) တွင် <b>Gradle for Java</b> တိုးချဲ့မှုကို ဖွင့်သောအခါ၊ သင်၏ <b>Flutter</b> ပရောဂျက်တွင် Gradle ဗားရှင်းများ သို့မဟုတ် မော်ဂျူးများစွာ ပါဝင်နေပါက၊ တိုးချဲ့မှုတစ်ခုစီကို သီးခြားရှာဖွေပြီး တည်ဆောက်ရန် ကြိုးပမ်းသည်။ ၎င်းသည် ဗားရှင်းမတူညီသော အမှားအယွင်းများကို ဖြစ်ပေါ်စေနိုင်သည် (ဥပမာ <code>အနိမ့်ဆုံးပံ့ပိုးထားသော Gradle ဗားရှင်းမှာ 9.6.0 ဖြစ်သည်။ လက်ရှိဗားရှင်းမှာ 9.4.0</code>) နှင့် တည်ဆောက်မှု မအောင်မြင်မှုများကို ဖြစ်စေသည်။ အကြံပြုထားသော ချဉ်းကပ်မှုသည် ပံ့ပိုးပေးထားသော အလုပ်နေရာများသို့ တိုးချဲ့မှုကို ချဲ့ထွင်ခြင်း သို့မဟုတ် Flutter လမ်းကြောင်းခွဲများအတွက် အလိုအလျောက် နက်ရှိုင်းသော ပရောဂျက်ရှာဖွေမှုကို ပိတ်ခြင်း ဖြစ်သည်။",
    "tip2_badge": "Linux Automation Tool",
    "tip2_sub": "Linux အလိုအလျောက်လုပ်ဆောင်ခြင်းကိရိယာ — Bash + Arch Linux",
    "tip2_title": "Arch Linux အတွက် Flutter Installer — အလိုအလျောက် SDK စနစ်ထည့်သွင်းခြင်း။",
    "tip2_desc": "Arch Linux တွင် နောက်ဆုံးပေါ်တည်ငြိမ်သော Flutter SDK ကို အလိုအလျောက်ထည့်သွင်းပေးသည့် Bash script သည် တရားဝင်အရင်းအမြစ်မှ နောက်ဆုံးထွက်ရှိမှုကို အလိုအလျောက်ရယူကာ အခွံသုံးခု (Bash၊ Zsh၊ နှင့် Fish) တို့တွင် ပတ်ဝန်းကျင်ပြောင်းလဲမှုများကို စီစဉ်သတ်မှတ်ပေးပြီး နောက်ဆုံး OpenJDK ကို ပုံသေအဖြစ် <code>archlinux-java</code> မှတစ်ဆင့် အဆင့်တစ်ဆင့်တွင် သတ်မှတ်ပေးပါသည်။",
