    "exp1_li1": "Được thiết kế và phát triển <b>CaseDesk</b>, một hệ thống quản lý phiếu hỗ trợ dành cho các chi nhánh và nhân viên — Kiến trúc ngoại tuyến đầu tiên với cơ sở dữ liệu kép (Hive + đám mây cục bộ thông qua API PHP REST).",
