    "exp1_intro": "Trong thời gian làm việc tại công ty, tôi đã phát triển các hệ thống phần mềm hoàn chỉnh được các chi nhánh và nhân viên sử dụng hàng ngày: hệ thống quản lý phiếu hỗ trợ, nền tảng phân phối phần mềm nội bộ và công cụ di chuyển và xử lý dữ liệu lớn - cùng với việc thiết kế và ghi lại cơ sở hạ tầng mạng cũng như xử lý các tác vụ bảo trì & phần cứng.",
    "boycott_title": "🕊️ Tẩy chay kỹ thuật",
