    "boycott_badge": "Nguyên tắc & Lập trường",
    "boycott_p1": "Với tư cách là một <b>chuyên gia mạng</b>, tôi tẩy chay <b>Cisco</b> do họ đồng lõa sâu sắc và ủng hộ những kẻ giết hại các nhà tiên tri và những kẻ áp bức. Mặc dù có bằng chứng xác thực được chứng nhận từ Cisco, tôi vui lòng từ bỏ chúng vì lợi ích của Allah. Bất cứ ai làm tổn hại đến những người anh em Hồi giáo của tôi, tôi sẽ từ bỏ ngay cả khi phải trả giá bằng lợi ích cá nhân của mình - vì nguồn sống của chúng tôi phụ thuộc vào Allah, Đấng Tự túc, Đấng Đáng ca ngợi.",
    "boycott_p2": "<b>Tôi tẩy chay các tập đoàn này, nhưng làm cách nào để chúng tôi tối đa hóa lợi ích từ việc này?</b><br>Khi làm việc tại một công ty nơi tôi đã giúp triển khai cơ sở dữ liệu, tôi đã tránh triển khai hoặc sử dụng <b>Oracle</b> để đảm bảo không hỗ trợ họ. Nếu một người mắc một sai lầm nhỏ, họ sẽ rút kinh nghiệm từ đó; Miễn là tôi có ảnh hưởng về mặt kỹ thuật hoặc nhúng tay vào bất kỳ công ty nào, tôi chỉ sử dụng những công nghệ không hỗ trợ những kẻ đã làm đổ máu anh em của chúng tôi và nguồn sống của tôi là của Allah.",
    "boycott_p3": "Và hãy ca ngợi Allah, ngày nay mọi công nghệ đều có một giải pháp thay thế miễn phí và độc lập.. và bạn sẽ rời bỏ cuộc sống phù du này (vì vậy hãy sợ Allah).",
