    "boycott_p2": "<b>ฉันคว่ำบาตรบริษัทเหล่านี้ แต่เราจะได้รับประโยชน์สูงสุดจากสิ่งนี้ได้อย่างไร</b><br>ในขณะที่ทำงานที่บริษัทที่ฉันช่วยปรับใช้ฐานข้อมูล ฉันหลีกเลี่ยงการปรับใช้หรือใช้ <b>Oracle</b> เพื่อให้แน่ใจว่าไม่สนับสนุนพวกเขา หากใครทำผิดพลาดเล็กน้อย พวกเขาก็เรียนรู้จากมัน ตราบใดที่ฉันมีอิทธิพลหรือมีอิทธิพลทางเทคนิคในบริษัทใดๆ ฉันจะใช้เทคโนโลยีที่ไม่สนับสนุนผู้ที่ทำให้พี่น้องของเราหลั่งเลือด และความยังชีพของฉันเป็นของอัลลอฮ์",
    "boycott_p3": "และมวลการสรรเสริญเป็นของอัลลอฮ์ ในวันนี้ทุกเทคโนโลยีมีทางเลือกที่เสรีและเป็นอิสระ... และจากชีวิตที่ประเดี๋ยวเดียวนี้คุณจะต้องจากไป (ดังนั้นจงยำเกรงอัลลอฮ์)",
