    "tip1_desc": "เมื่อเปิดใช้งานส่วนขยาย <b>Gradle สำหรับ Java</b> ใน IDE ของคุณ (VS Code / Antigravity) หากโปรเจ็กต์ <b>Flutter</b> ของคุณมี Gradle เวอร์ชันหรือโมดูลหลายโมดูล ส่วนขยายจะพยายามค้นหาและสร้างแต่ละเวอร์ชันแยกจากกัน ซึ่งอาจทำให้เกิดข้อผิดพลาดที่ไม่ตรงกันของเวอร์ชัน (เช่น <code>เวอร์ชัน Gradle ขั้นต่ำที่รองรับคือ 9.6.0 เวอร์ชันปัจจุบันคือ 9.4.0</code>) และทำให้เกิดความล้มเหลวในการสร้าง แนวทางที่แนะนำคือการกำหนดขอบเขตส่วนขยายไปยังพื้นที่ทำงานที่รองรับ หรือปิดใช้งานการค้นหาโปรเจ็กต์เชิงลึกอัตโนมัติสำหรับไดเร็กทอรีย่อย Flutter",
