    "exp1_li5": "Виконував завдання з технічного обслуговування та апаратного забезпечення, аналізував KPI за допомогою інтерактивних інформаційних панелей і створював професійні арабські звіти PDF/Excel.",
    "exp1_intro": "Під час роботи в компанії я розробив комплексні системи програмного забезпечення, якими щодня користуються філії та співробітники: систему керування заявками на підтримку, внутрішню платформу розповсюдження програмного забезпечення та інструмент обробки та міграції великих даних — разом із проектуванням і документуванням мережевої інфраструктури та виконанням завдань з обслуговування та обладнання.",
