    "boycott_p1": "Як <b>мережевий фахівець</b>, я бойкотую <b>Cisco</b> через їх глибоку співучасть і підтримку вбивць пророків і гнобителів. Незважаючи на те, що я маю сертифікати від Cisco, я з радістю відмовляюся від них заради Аллаха. Я відмовлюся від того, хто завдає шкоди моїм братам-мусульманам, навіть за рахунок моїх особистих інтересів, бо наше життя належить Аллаху, Самодостатньому, Гідному похвали.",
    "boycott_p2": "<b>Я бойкотую ці корпорації, але як отримати від цього максимальну вигоду?</b><br>Під час роботи в компанії, де я допомагав розгортати бази даних, я уникав розгортання або використання <b>Oracle</b>, щоб не підтримувати їх. Якщо хтось робить невелику помилку, вони вчаться на цьому; доки я маю руку чи технічний вплив у будь-якій фірмі, я використовую лише технології, які не підтримують тих, хто проливає кров наших братів, і моє існування належить Аллаху.",
