    "itsc_desc": "Корпоративна програма для розповсюдження схваленого програмного забезпечення в мережі компанії: менеджер завантажень із поточним прогресом (Dio), автоматичне виявлення оновлень за допомогою анімованого значка, підтримка арабською/англійською мовами та темний режим (Матеріал 3).",
    "tpc_sub": "Розбиття відео — Electron.js + FFmpeg",
    "tpc_desc": "Настільний додаток для розділення відео (1/2/3 хвилини або навпіл) із якістю 100% без втрат за допомогою потокового копіювання з автоматичним виявленням GPU та сучасним інтерфейсом користувача Glassmorphism. Працює на Windows, Linux і macOS.",
    "ts_sub": "Тренажер швидкості друку — Electron.js",
    "ts_desc": "Кросплатформний тренажер набору тексту з повною підтримкою RTL (арабська/іврит/перська), докладною статистикою WPM і точності, примусовою зупинкою в разі помилки для нарощування м’язової пам’яті, глобальними ярликами та системною панеллю.",
    "nui_sub": "Панель запуску Android — Kotlin + Jetpack Compose",
    "nui_desc": "Сучасна програма запуску Android з архітектурою MVVM і кімнатною базою даних: вбудований календар Хіджри/Григоріанський календар, нотатки на головному екрані, автоматична категоризація програм, кошик для сміття та приховування конфіденційних програм.",
    "r30_sub": "Управління зарплатою та бюджетом — Flutter",
    "r30_desc": "Додаток Smart Offline-First з бюджетом: автоматичний розподіл 50/30/20, динамічний щоденний бюджет, виклики заощаджень, розділ благодійності, діаграми (fl_chart) і місячний фінансовий календар — шість підтримуваних платформ.",
    "pomo_sub": "Таймер продуктивності Pomodoro — Flutter",
    "pomo_desc": "Управління роботою/перервами за допомогою техніки Pomodoro: настроювані щоденні та тижневі цілі, звукові сповіщення, кілька тем і пакети Linux (Flatpak / .desktop) — працює на 5 платформах.",
    "lm_sub": "Відеогенератор водяних знаків — Flutter + FFmpeg",
    "lm_desc": "Створює відео у форматі MP4 з водяним знаком анімованого тексту без жодного вхідного відео: арабський текст, відтворений механізмом Flutter Canvas із високою точністю з повною підтримкою діакритичних знаків, експортований через FFmpeg на Android і Windows.",
    "roms_small": "Операційні системи",
    "roms_title": "🤖 Створення користувальницьких ПЗУ Android із вихідного коду",
    "roms_desc": "Повні збірки ПЗУ AOSP із джерела з налаштуванням ядра, налаштуванням дерева пристроїв і керуванням blob-об’єктами постачальника.",
    "rom1_desc": "Повна збірка AOSP із вихідного коду з рівнем Evolution X, спеціальним налаштуванням ядра та деревом пристроїв, виправленнями HAL і налаштуванням камери, а також досвідом Pixel на обладнанні Xiaomi.",
    "rom2_desc": "Збірка AOSP Android 16 із вихідного коду з функціями Infinity X, налаштуванням ядра та дерева пристроїв, а також керуванням blob і HAL від постачальника.",
    "rom3_desc": "Створення PixelOS з вихідного коду з компіляцією ядра, налаштуванням дерева пристроїв і вилученням blob-об’єктів від постачальника — чистий досвід Pixel на апаратному забезпеченні Motorola.",
    "rom4_desc": "Vanilla збірка без служб Google (GApps) — 100% чистий досвід AOSP на тому самому пристрої.",
    "rom4_tag3": "Без GApps",
    "rom5_desc": "Обслуговування та створення офіційного ПЗУ LineageOS 23.2 для Moto G54 5G — стабільного, легкого ПЗУ з відкритим вихідним кодом із регулярними оновленнями безпеки.",
    "rom5_tag2": "Відкритий код",
    "rom5_tag3": "Оновлення безпеки",
