    "nav_tips": "Технічні поради",
    "haris_sub": "Фільтр вмісту YouTube і розширення Focus — TypeScript + WXT",
    "haris_desc": "Міжбраузерне розширення з відкритим вихідним кодом, націлене на конфіденційність, яке перетворює YouTube на чисте, цілеспрямоване навчальне середовище з білим списком каналів, блокувальником коротких відео та локальною архітектурою, яка підтримує понад 40 мов.",
    "miqyas_sub": "Піктограма додатка, макети студії та магазину безпечної зони — Flutter",
    "miqyas_desc": "Інтерактивна студія для розробників для точного вирівнювання піктограм додатків у безпечній зоні 66×66 на всіх платформах, що включає попередній перегляд макетів для кількох пристроїв у реальному часі та автоматичний генератор скріншотів для Google Play і App Store.",
    "mufarrigh_sub": "Екстракт листів спрайтів і видалення фону — Flutter + Dart Vision",
    "mufarrigh_desc": "Інтелектуальний настільний і мобільний інструмент для нарізки аркушів спрайтів і видалення фону за допомогою механізму Pure-Dart, BFS Flood-Fill і ерозії прогалин за допомогою адаптивного 3-панельного інтерфейсу користувача та пакетного експорту.",
    "tips_small": "Посібники, ідеї та рішення",
    "tips_title": "💡 Технічні поради та рішення",
    "tips_desc": "Практичні посібники, поради щодо усунення несправностей та інструменти автоматизації, отримані під час розробки та адміністрування систем.",
    "tip1_badge": "Попередження та виправлення збірки Flutter",
    "tip1_title": "Правильне використання розширення Gradle for Java для запобігання конфліктам версій",
    "tip1_desc": "Під час увімкнення розширення <b>Gradle для Java</b> у вашій IDE (VS Code / Antigravity), якщо ваш проект <b>Flutter</b> містить кілька версій або модулів Gradle, розширення намагається виявити та створити кожен окремо. Це може викликати помилки невідповідності версій (наприклад, <code>мінімальна підтримувана версія Gradle – 9.6.0. Поточна версія – 9.4.0</code>) і спричинити помилки збірки. Рекомендований підхід полягає в тому, щоб розмістити розширення в підтримуваних робочих областях або вимкнути автоматичне глибоке виявлення проекту для підкаталогів Flutter.",
    "tip2_badge": "Інструмент автоматизації Linux",
    "tip2_sub": "Інструмент автоматизації Linux — Bash + Arch Linux",
    "tip2_title": "Інсталятор Flutter для Arch Linux — автоматичне налаштування SDK",
    "tip2_desc": "Сценарій Bash, який автоматизує встановлення останньої стабільної версії Flutter SDK на Arch Linux: автоматично отримує найновішу версію з офіційного джерела, налаштовує змінні середовища в трьох оболонках (Bash, Zsh і Fish) і встановлює найновішу версію OpenJDK за замовчуванням через <code>archlinux-java</code> за один крок.",
    "tip_img_tag": "📸 Знімок екрана розширення та помилки",
    "tip_vid_tag": "🎬 Демонстраційне відео",
