    "exp1_period": "فبراير 2026 — أغسطس 2026",
    "exp1_intro": "خلال فترة عملي في الشركة، طوّرت أنظمة برمجية كاملة تُستخدم يومياً من الفروع والموظفين: نظام إدارة بلاغات دعم فني، منصة توزيع برامج داخلية، وأداة معالجة وترحيل بيانات ضخمة — إلى جانب تصميم وتوثيق البنية التحتية للشبكة ومتابعة مهام الصيانة والعتاد.",
    "exp1_li1": "تصميم وتطوير نظام <b>CaseDesk</b> لإدارة ومتابعة بلاغات الدعم الفني للفروع والموظفين — بمعمارية Offline-First وقاعدتي بيانات (Hive محلياً + سحابياً عبر PHP REST APIs).",
    "exp1_li2": "تطوير تطبيق <b>IT Software Center</b> لتوزيع البرامج المعتمدة داخل شبكة الشركة مع نظام كشف تحديثات تلقائي ومدير تحميل ذكي.",
    "exp1_li3": "بناء أداة <b>RatilConvert</b> التي عالجت ونقّت <b>+715,463 سجل عميل</b> من نظام Retail Pro وصدّرتها بتوافق 100% مع نظام Odoo ERP — قلّلت وقت الترحيل اليدوي بنسبة 95%.",
    "exp1_li4": "تصميم مخطط الشبكة الفيزيائية لمبنى الشركة باستخدام draw.io، متضمناً توزيع السيرفرات، وجدار الحماية (Firewall)، والـ Core Switch، وسويتشات الأقسام، مع توثيق بنية الشبكة وربط الأجهزة وفقاً لأقسام الشركة.",
    "exp1_li5": "متابعة مهام الصيانة والعتاد، وتحليل مؤشرات الأداء (KPIs) عبر لوحات بيانية تفاعلية، وتوليد تقارير PDF/Excel عربية احترافية.",
    "boycott_title": "<span>🕊️ المقاطعة التقنية</span>",
    "boycott_sub": "مبدأ راسخ وموقف عقدي وأخلاقي",
    "boycott_badge": "موقف ومبدأ",
    "boycott_p1": "أنا تخصصي <b>شبكات</b>، ولذلك أنا مقاطع لشركة <b>سيسكو (Cisco)</b> بسبب دعمهم وتواطئهم الصريح مع قتلة الأنبياء، ورغم أن لدي شهادات معتمدة من Cisco إلا أنني أتخلى عنها لوجه اللَّه تعالى؛ فمن يسيء لإخواني المسلمين سأتخلى عنه ولو كان ذلك على حساب مصلحتي الشخصية، لأنهم إخواني في الإسلام ورزقي على اللَّه الغني الحميد.",
    "boycott_p2": "<b>هذه الشركات أنا مقاطعها، ولكن كيف أستفيد من هذا بأفضل شكل؟</b><br/>\n          عندما كنت أعمل في إحدى الشركات وكنت مساهماً في تجهيز قواعد البيانات، تجنبت تماماً تنزيل أو استخدام تقنيات <b>أوراكل (Oracle)</b> حتى لا أدعمهم بأي شكل. ولو أخطأت يوماً في شيء يسير فالإنسان يتعلم من خطئه، وطالما أن لي يداً أو قراراً تقنياً في أي جهة فلن أستخدم إلا الحلول التي لا تدعم من يسفك دماء إخواننا، ورزقي على اللَّه الغني الحميد.",
    "boycott_p3": "والحمدللَّه، اليوم لكل تقنية ألف بديل حر ومستقل.. وأنت في هذه الحياة راحل عنها (فاتَّقِ اللَّه).",
