    "boycott_tip": "<b>نصيحة للمضطر:</b> إذا كان الشخص مجبراً على شراء منتج لشركة مقاطعة ولا يوجد بديل متاح إطلاقاً، فاشتره <b>مستعملاً</b> حتى لا تربح الشركة منه فلساً واحداً جديداً. وشكراً، واللَّه المستعان.",
