    "casedesk_desc": "نظام متكامل لإدارة ومتابعة بلاغات الدعم الفني للفروع والموظفين، بمزامنة Offline-First سحابية، ولوحة تحليلات تفاعلية لمؤشرات الأداء (KPIs)، مع تقارير PDF/Excel عربية وتعبئة ذكية للبلاغات وإشعارات واتساب.",
