    "itsc_sub": "منصة توزيع برامج داخلية للشركات",
    "itsc_desc": "منصة سطح مكتب مؤسسية لتوزيع البرامج المعتمدة عبر شبكة الشركة، تتضمن مدير تحميل متقدم بمؤشر تقدم لحظي (Dio)، ونظام كشف تلقائي للتحديثات مع تنبيهات ذكية ودعم كامل للغتين والوضع الداكن.",
    "grp_personal": "👤 مشاريع شخصية — منشورة على GitHub",
