    "haris_sub": "إضافة متصفح لتصفية محتوى يوتيوب — TypeScript + WXT",
    "haris_desc": "إضافة متصفح تفاعلية ومفتوحة المصدر مصممة لتصفية محتوى يوتيوب، حظر التشتيت، واستعادة التحكم في المحتوى المعروض بنظام القائمة المعتمدة وإخفاء Shorts، صُممت بمبدأ الخصوصية أولاً (Local-First) وتعمل محلياً بالكامل مع دعم لأكثر من 40 لغة.",
    "view_github": "عرض على GitHub ←",
    "miqyas_sub": "استوديو الأيقونات والمنطقة الآمنة وقوالب المتاجر — Flutter",
    "miqyas_desc": "استوديو تفاعلي شامل لضبط وتوسيط أيقونات التطبيقات بدقة داخل المنطقة الآمنة لجميع المنصات، مع محاكي حي للأجهزة لمعاينة الأيقونة وسط بيئات الأنظمة، وتوليد لقطات ترويجية احترافية لقوالب المتاجر دفعة واحدة.",
    "mufarrigh_sub": "استخراج شيتات السبرايت وإزالة الخلفيات — Flutter",
    "mufarrigh_desc": "أداة متقدمة لمطوري الألعاب والمصممين لمعالجة وقص شيتات السبرايت وعزل الخلفيات بمحرك Pure-Dart كامل، مع خوارزميات BFS Flood-Fill ومعالجة الفجوات وتنعيم الحواف بواجهة ثلاثية مرنة وتصدير دفعي فوري.",
    "tpc_sub": "تقسيم الفيديو — Electron.js + FFmpeg",
